-- ANIME (part 2)
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (32366, 'Gintama°: Aizome Kaori-hen', '銀魂　愛染香篇', 'OVA', 2, 'FINISHED', 8.38, 49216, 242, 2507, 'The red-light district, Yoshiwara, is suddenly taken over by "Aizen Kou," an incense that has the ability to make anyone fall in love with the first person they see. Having been outlawed for its strong potency, the love drug was thought to have disappeared from the red-light district for good; however, it seems to have found its way back inside Yoshiwara''s walls and now has the entire district under its influence.

Of those affected is the cold-hearted Hyakka captain, Tsukuyo, and the first person she sees after inhaling the smoke is none other than the brazen Yorozuya leader, Gintoki Sakata. Unbeknownst to everyone else though, she was already attracted to Gintoki. With those hidden feelings now intensified, Tsukuyo must overcome her afflictions and work with the Yorozuya to return everyone back to normal. 

[Written by MAL Rewrite]', NULL, 7, 'https://myanimelist.net/images/anime/1962/133573.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5, 'Cowboy Bebop: Tengoku no Tobira', 'カウボーイビバップ 天国の扉', 'UNKNOWN', 1, 'FINISHED', 8.38, 231993, 240, 658, 'Another day, another bounty—such is the life of the often unlucky crew of the Bebop. However, this routine is interrupted when Faye, who is chasing a fairly worthless target on Mars, witnesses an oil tanker suddenly explode, causing mass hysteria. As casualties mount due to a strange disease spreading through the smoke from the blast, a whopping three hundred million woolong price is placed on the head of the supposed perpetrator.

With lives at stake and a solution to their money problems in sight, the Bebop crew springs into action. Spike, Jet, Faye, and Edward, followed closely by Ein, split up to pursue different leads across Alba City. Through their individual investigations, they discover a cover-up scheme involving a pharmaceutical company, revealing a plot that reaches much further than the ragtag team of bounty hunters could have realized.

[Written by MAL Rewrite]', NULL, 3, 'https://myanimelist.net/images/anime/1439/93480.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38475, 'Yuru Camp△ Movie', '映画 ゆるキャン△', 'UNKNOWN', 1, 'FINISHED', 8.38, 35421, 250, 2472, 'As time marches forward, Rin Shima, Nadeshiko Kagamihara, and their friends have grown into full-fledged adults. Now with careers and responsibilities, they can no longer freely spend their days camping and adventuring. However, Chiaki Oogaki, who currently works for the Yamanashi Tourism Organization, reunites the group as she comes up with an exciting proposal—to build a campground together to revitalize an abandoned patch of land from their homeplace, the Yamanashi Prefecture.

Motivated by this ambitious project, the girls combine their efforts to create an environment where future generations can enjoy unique moments as they once did, all while reminiscing the charms of camping from their high school days.

[Written by MAL Rewrite]', NULL, 64, 'https://myanimelist.net/images/anime/1806/124396.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (45556, 'Wu Liuqi: Xuanwu Guo Pian', '伍六七之玄武国篇', 'ONA', 10, 'FINISHED', 8.38, 46483, 249, 2656, 'In order to protect the residents of Xiaoji Island and the peaceful life here, Wu Liuqi and his partners Dabao and Xiaofei embark on a journey to the Xuanwu Kingdom to find out the truth about his identity and a way to save the island. Waiting for them is more unknowns and adventures.

(Source: bilibili, edited)', NULL, 86, 'https://myanimelist.net/images/anime/1884/111224.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (56523, 'Tunshi Xingkong 3rd Season', '吞噬星空 第三季', 'ONA', 33, 'FINISHED', 8.37, 2461, 260, 9446, 'Third season of Tunshi Xingkong.', NULL, 87, 'https://myanimelist.net/images/anime/1250/138217.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (53540, 'Meitantei Conan Movie 26: Kurogane no Submarine', '名探偵コナン 黒鉄の魚影 (サブマリン)', 'UNKNOWN', 1, 'FINISHED', 8.37, 9826, 258, 5585, 'This time''s location is set in the sea near the Hachijo-jima island, Tokyo. Engineers from around the world have gathered for the full-scale operation of "Pacific Buoy," an offshore facility to connect security cameras owned by the worldwide police forces. A test of a certain "new technology" based on a face recognition system is underway there.

Meanwhile, Conan and the Detective Boys visit Hachijo-jima at Sonoko''s invitation and receive a phone call from Subaru Okiya informing them that a Europol employee was murdered in Germany by the Black Organization''s Jin.

Conan, who is disquieted, sneaks into the facility and finds that a female engineer has been kidnapped by the Black Organization...! Furthermore, a USB drive containing certain information in her possession ends up in the hands of the organization... A black shadow also creeps up on Ai Haibara ...

(Source: Crunchyroll, edited)', NULL, 14, 'https://myanimelist.net/images/anime/1138/133101.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5205, 'Kara no Kyoukai Movie 7: Satsujin Kousatsu (Go)', '劇場版 空の境界 the Garden of sinners 第七章『殺人考察（後）』', 'UNKNOWN', 1, 'FINISHED', 8.37, 118964, 256, 1282, 'In February 1999, a string of murders has Shiki Ryougi and Mikiya Kokutou on edge. These crimes share a disturbing resemblance to a similar set of homicides from 1995, when Shiki and Mikiya first met, and awaken a dark, murderous desire that has laid dormant within Shiki''s soul ever since then.

With Shiki under suspicion due to her involvement in the past killings and supposed resemblance to the killer, she and Mikiya set out to find the true perpetrator. In the midst of their separate investigations, Mikiya grows increasingly concerned with Shiki''s well-being and hurries to find the one responsible in order to protect Shiki from her own impulses. With the lead he receives from his cousin, police investigator Daisuke Akimi, Mikiya is led into the underbelly of Mifune City, as the salvation of Shiki''s soul lies in his determination to prove her innocence once and for all.

[Written by MAL Rewrite]', NULL, 35, 'https://myanimelist.net/images/anime/9/56619.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5941, 'Cross Game', 'クロスゲーム', 'TV', 50, 'FINISHED', 8.37, 53809, 252, 1953, 'Kou Kitamura and Aoba Tsukishima are often at odds—even though their families happen to be close friends and business partners. Although the only child of a sports shop owner, Kou has never been interested in playing baseball. Despite this, he possesses an impressive batting ability honed by frequent visits to the local baseball batting center run by the Tsukishima family. On the other hand, Aoba loves to play baseball and is a star player with exceptional pitching form.

However, these two seemingly complete opposites share something very important to them—Wakaba Tsukishima, Aoba''s older sister and Kou''s destined sweetheart. Admired by the quarrelsome duo, Wakaba often finds herself the catalyst to their never-ending rivalry. But whether or not they realize that they have more in common than either would care to admit, only time will tell. The game of baseball may just be what the pair needs to ultimately overcome their own personal struggles.

[Written by MAL Rewrite]', 2, 83, 'https://myanimelist.net/images/anime/6/22103.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (31646, '3-gatsu no Lion', '3月のライオン', 'TV', 22, 'FINISHED', 8.37, 301139, 251, 316, 'Having reached professional status in middle school, Rei Kiriyama is one of the few elite in the world of shogi. Due to this, he faces an enormous amount of pressure, both from the shogi community and his adoptive family. Seeking independence from his tense home life, he moves into an apartment in Tokyo. As a 17-year-old living on his own, Rei tends to take poor care of himself, and his reclusive personality ostracizes him from his peers in school and at the shogi hall.

However, not long after his arrival in Tokyo, Rei meets Akari, Hinata, and Momo Kawamoto, a trio of sisters living with their grandfather who owns a traditional wagashi shop. Akari, the oldest of the three girls, is determined to combat Rei''s loneliness and poorly sustained lifestyle with motherly hospitality. The Kawamoto sisters, coping with past tragedies, also share with Rei a unique familial bond that he has lacked for most of his life. As he struggles to maintain himself physically and mentally through his shogi career, Rei must learn how to interact with others and understand his own complex emotions.

[Written by MAL Rewrite]', 29, 18, 'https://myanimelist.net/images/anime/3/82899.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (48561, 'Jujutsu Kaisen 0 Movie', '劇場版 呪術廻戦 0', 'UNKNOWN', 1, 'FINISHED', 8.37, 789818, 255, 130, 'Violent misfortunes frequently occur around 16-year-old Yuuta Okkotsu, a timid victim of high school bullying. Yuuta is saddled with a monstrous curse, a power that dishes out brutal revenge against his bullies. Rika Orimoto, Yuuta''s curse, is a shadow from his tragic childhood and a potentially lethal threat to anyone who dares wrong him.

Yuuta''s unique situation catches the attention of Satoru Gojou, a powerful sorcerer who teaches at Tokyo Prefectural Jujutsu High School. Gojou sees immense potential in Yuuta, and he hopes to help the boy channel his deadly burden into a force for good. Yet Yuuta struggles to find his place among his talented classmates: the selectively mute Toge Inumaki, weapons expert Maki Zenin, and Panda.

Yuuta clumsily utilizes Rika on missions with the other first-year students, but the grisly aftermath of Rika''s tremendous displays of power draws the interest of the calculating curse user Suguru Getou. As Getou strives to claim Rika''s strength and use it to eliminate all non-jujutsu users from the world, Yuuta fights alongside his friends to stop the genocidal plot.

[Written by MAL Rewrite]', NULL, 4, 'https://myanimelist.net/images/anime/1121/119044.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38883, 'Haikyuu!! To the Top', 'ハイキュー!! TO THE TOP', 'TV', 13, 'FINISHED', 8.37, 647228, 254, 174, 'After their triumphant victory over Shiratorizawa Academy, the Karasuno High School volleyball team has earned their long-awaited ticket to nationals. As preparations begin, genius setter Tobio Kageyama is invited to the All-Japan Youth Training Camp to play alongside fellow nationally recognized players. Meanwhile, Kei Tsukishima is invited to a special rookie training camp for first-years within the Miyagi Prefecture. Not receiving any invitations himself, the enthusiastic Shouyou Hinata feels left behind.

However, Hinata does not back down. Transforming his frustration into self-motivation, he boldly decides to sneak himself into the same rookie training camp as Tsukishima. Even though Hinata only lands himself a job as the ball boy, he comes to see this as a golden opportunity. He begins to not only reflect on his skills as a volleyball player but also analyze the plethora of information available on the court and how he can apply it.

As the much-anticipated national tournament approaches, the members of Karasuno''s volleyball team attempt to overcome their weak points and refine their skills, all while aiming for the top!

[Written by MAL Rewrite]', 79, 23, 'https://myanimelist.net/images/anime/1813/105367.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49721, 'Karakai Jouzu no Takagi-san 3', 'からかい上手の高木さん3', 'TV', 12, 'FINISHED', 8.37, 96629, 257, 1314, 'As summer break comes to an end, Nishikata is stoked to try out his newest pranks and finally outdo his classmate Takagi once and for all. Despite his losing streak, he is slowly getting to know the unrelenting workings of her crafty mind. However, he soon realizes that Takagi''s motivations behind her teasing may not be what he initially assumed. One thing is certain, though: each fun-filled day of strategizing and competing brings the two closer than ever.

[Written by MAL Rewrite]', 30, 33, 'https://myanimelist.net/images/anime/1861/120361.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (51039, 'Doupo Cangqiong: Nian Fan', '斗破苍穹年番', 'ONA', 209, 'AIRING', 8.37, 4241, 253, 6657, 'Fifth season of Doupo Cangqiong.', NULL, 75, 'https://myanimelist.net/images/anime/1419/126374.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (30, 'Shinseiki Evangelion', '新世紀エヴァンゲリオン', 'TV', 26, 'FINISHED', 8.37, 1212276, 259, 45, 'Fifteen years after a cataclysmic event known as the Second Impact, the world faces a new threat: monstrous celestial beings called Angels invade Tokyo-3 one by one. Mankind is unable to defend themselves against the Angels despite utilizing their most advanced munitions and military tactics. The only hope for human salvation rests in the hands of NERV, a mysterious organization led by the cold Gendou Ikari. NERV operates giant humanoid robots dubbed "Evangelions" to combat the Angels with state-of-the-art advanced weaponry and protective barriers known as Absolute Terror Fields.

Years after being abandoned by his father, Shinji Ikari, Gendou''s 14-year-old son, returns to Tokyo-3. Shinji undergoes a perpetual internal battle against the deeply buried trauma caused by the loss of his mother and the emotional neglect he suffered at the hands of his father. Terrified to open himself up to another, Shinji''s life is forever changed upon meeting 29-year-old Misato Katsuragi, a high-ranking NERV officer who shows him a free-spirited maternal kindness he has never experienced.

A devastating Angel attack forces Shinji into action as Gendou reveals his true motive for inviting his son back to Tokyo-3: Shinji is the only child capable of efficiently piloting Evangelion Unit-01, a new robot that synchronizes with his biometrics. Despite the brutal psychological trauma brought about by piloting an Evangelion, Shinji defends Tokyo-3 against the angelic threat, oblivious to his father''s dark machinations.

[Written by MAL Rewrite]', 80, 41, 'https://myanimelist.net/images/anime/1314/108941.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (56524, 'Tunshi Xingkong 4th Season', '吞噬星空 第四季', 'ONA', 175, 'AIRING', 8.36, 2116, 271, 8938, 'Fourth season of Tunshi Xingkong.', NULL, 87, 'https://myanimelist.net/images/anime/1335/138907.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55102, 'Girls Band Cry', 'ガールズバンドクライ', 'TV', 13, 'FINISHED', 8.36, 54650, 264, 1917, 'Everyone yearns to find their true purpose in life. This is also true for Nina Iseri, a 17-year-old girl looking to enroll in a good university, but the world always seems to work against her. On her very first day in Tokyo, she gets lost, ignored, and locked out of her new apartment. However, an unexpected opportunity arises when Nina meets Momoka Kawaragi, one of her favorite guitarists.

After Nina joins Momoka for a street performance, Momoka decides they should start a band together. While Nina initially hesitates, her determination grows as they start acquiring more bandmates—the beautiful drummer Subaru Awa, the aloof keyboardist Tomo Ebizuka, and the intelligent bassist Rupa. The five girls face challenges both in the music industry and within themselves, but their shared passion for music never lets them give up on their dreams.

[Written by MAL Rewrite]', 33, 8, 'https://myanimelist.net/images/anime/1711/140515.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (9617, 'K-On! Movie', '映画 けいおん！', 'UNKNOWN', 1, 'FINISHED', 8.36, 209670, 267, 768, 'Graduation looms for the founding members of the Light Music Club. With only a few precious weeks of school left, the girls decide to make the most of it and plan a trip abroad. Hawaii, New York, Dubai—many destinations are suggested, but after a little help from the club''s precious pet turtle, Ton-chan, London is chosen as the host of their next misadventure!

Yui Hirasawa, Mio Akiyama, Tsumugi Kotobuki, Ritsu Tainaka, and Azusa Nakano will visit famous landmarks, perform live music for Londoners, and eat all sorts of delicious food, all while stumbling clumsily from place to place. But the fun won''t last forever, as heartfelt songs and goodbyes will be made as their high school days together come to a close. One thing is for certain though: the undeniable friendships these girls have formed is something that will carry on long after the final scene rolls.

[Written by MAL Rewrite]', NULL, 15, 'https://myanimelist.net/images/anime/5/76233.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (9260, 'Kizumonogatari I: Tekketsu-hen', '傷物語〈Ⅰ鉄血篇〉', 'UNKNOWN', 1, 'FINISHED', 8.36, 312565, 269, 432, 'During Koyomi Araragi''s second year at Naoetsu Private High School, he has a chance encounter with Tsubasa Hanekawa, the top honor student in his class. When they strike up a conversation, Hanekawa mentions a shocking rumor: a vampire with beautiful blonde hair and freezing cold eyes has been seen lurking around town.

Happy to have made a new friend, Araragi writes off the rumor and goes about the rest of his evening in a carefree manner. However, on his way home, he stumbles across splatters of blood leading down the stairs to the subway. His curiosity pushes him to investigate further, so he follows the gruesome pools into the depths of the station. 

When he arrives at the source of the blood, he is terrified by what he sees—the rumored blonde vampire herself, completely dismembered. After she calls for his help, Araragi must make a decision, one which carries the potential to change his life forever.

[Written by MAL Rewrite]', NULL, 18, 'https://myanimelist.net/images/anime/1783/112810.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6945, 'Gintama: Shiroyasha Koutan', 'ジャンプアニメツアー 2008 白夜叉降誕', 'UNKNOWN', 1, 'FINISHED', 8.36, 36923, 263, 2841, 'According to Aniplex, a 10min short anime of Gintama "Shiroyasha Koutan" will be released on September 30th. It was shown at Jump Super Anime Tour 2008 and had never been released as a DVD.

It''s a trailer of an imaginary Gintama movie. Gintama OVA shown at Jump Anime Tour ''05 is also included in the DVD.', NULL, 9, 'https://myanimelist.net/images/anime/6/16161.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39808, 'Non Non Biyori Nonstop', 'のんのんびより のんすとっぷ', 'TV', 12, 'FINISHED', 8.36, 54218, 270, 1882, 'The carefree journeys of the four girls continue! As their fleeting yet eventful summer becomes a distant memory, the arrival of fall signals a new school year with limitless opportunities. Even as the four girls return to their peaceful routine, the appearance of new faces enlivens the anything but exciting rural life of Asahigaoka.

Non Non Biyori Nonstop leisurely walks back into the lives of Hotaru Ichijou, Komari Koshigaya, Natsumi Koshigaya, and Renge Miyauchi as they fully embrace their rural lifestyles and turn anything they find into nothing but fun!

[Written by MAL Rewrite]', 25, 88, 'https://myanimelist.net/images/anime/1033/111540.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49310, 'Fruits Basket: Prelude', 'フルーツバスケット -prelude-', 'UNKNOWN', 1, 'FINISHED', 8.36, 50568, 262, 1973, 'Despite Kyouko Honda''s tragic death, her vivid memory lives on, providing guidance through times of hardship to her close ones. However, Kyouko was not always the wise and radiant person that she is fondly remembered as in the present day.

Feeling deserted by her own family and rejected by society, a young Kyouko abandons stability for a life of delinquency, jeopardizing her education and future. Fortunately, her descent into despair is interrupted by a fateful encounter with her husband-to-be Katsuya, who has recently started his teaching internship at her school. 

With a composure surprisingly unaffected by Kyouko''s tantrums, Katsuya quickly wins her over through his gentleness and attention toward her—sincere gestures that she has never received before. As the two grow closer together, Kyouko opens her tormented heart to him and, along with it, a door to new horizons.

[Written by MAL Rewrite]', NULL, 14, 'https://myanimelist.net/images/anime/1034/120096.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (46654, 'IDOLiSH7 Third Beat! Part 2', 'アイドリッシュセブン', 'TV', 17, 'FINISHED', 8.36, 6174, 265, 5734, 'IDOLiSH7 is more successful than ever, but no one is smiling because a new threat has taken the stage: the debuting idol group ŹOOĻ. Managed by the nefarious entertainment executive Ryou Tsukumo, they will stop at nothing to get their way, resorting to all kinds of underhanded tactics to bring down their rivals. TRIGGER''s image has already been ruined by scandal, and IDOLiSH7 and Re:vale are headed for the same fate—or worse.

Meanwhile, Zero, the legendary idol who disappeared 15 years ago, continues to haunt the present through those he left behind. His manager seems to be in contact with Tsukumo for his own schemes, and Zero''s songwriter reveals himself in a letter after having been missing for years. IDOLiSH7 finds an ally in Re:vale to thwart ŹOOĻ''s plans while trying to make sense of Zero''s colleagues'' actions, but it may be impossible for everyone to emerge unscathed.

[Written by MAL Rewrite]', 9, 89, 'https://myanimelist.net/images/anime/1458/125998.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (572, 'Kaze no Tani no Nausicaä', '風の谷のナウシカ', 'UNKNOWN', 1, 'FINISHED', 8.36, 258095, 268, 652, 'A millennium has passed since the catastrophic nuclear war named the "Seven Days of Fire," which destroyed nearly all life on Earth. Humanity now lives in a constant struggle against the treacherous jungle that has evolved in response to the destruction caused by mankind. Filled with poisonous spores and enormous insects, the jungle spreads rapidly across the Earth and threatens to swallow the remnants of the human race.

Away from the jungle exists a peaceful farming kingdom known as the "Valley of the Wind," whose placement by the sea frees it from the spread of the jungle''s deadly toxins. The Valley''s charismatic young princess, Nausicaä, finds her tranquil kingdom disturbed when an airship from the kingdom of Tolmekia crashes violently in the Valley. After Nausicaä and the citizens of the Valley find a sinister pulsating object in the wreckage, the Valley is suddenly invaded by the Tolmekian military, who intend to revive a dangerous weapon from the Seven Days of Fire. Now Nausicaä must fight to stop the Tolmekians from plunging the Earth into a cataclysm which humanity could never survive, while also protecting the Valley from the encroaching forces of the toxic jungle.

[Written by MAL Rewrite]', NULL, 90, 'https://myanimelist.net/images/anime/10/75914.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (338, 'Versailles no Bara', 'ベルサイユのばら', 'TV', 40, 'FINISHED', 8.36, 34425, 272, 2176, 'In a time of class stratification and rising tensions amongst the impoverished population, the Austrian Empire sends Princess Marie Antoinette to France to be wed to Crown Prince Louis XVI. The political marriage is arranged to strengthen the alliance between both countries, but the future queen is deeply unsatisfied with her fate being decided for her. Upon arrival in the country, Marie Antoinette is acquainted with Oscar Fançois de Jarjayes—Commander of the Royal Guard.

Due to her father''s desire for a son, Oscar is raised as a boy with an expectation to inherit his title as The Commander. Though she is revered by both men and women alike, Oscar cannot help but desire to live life as a woman instead of masquerading as a man. As Oscar reluctantly serves the young, spoiled queen, the growing resentment and suffering of the poor become harder for her to ignore—especially when Marie Antoinette frivolously spends her wealth.

[Written by MAL Rewrite]', 81, 21, 'https://myanimelist.net/images/anime/9/57043.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (185, 'Initial D First Stage', '頭文字〈イニシャル〉D', 'TV', 26, 'FINISHED', 8.36, 218600, 266, 607, 'Unlike his friends, Takumi Fujiwara is not particularly interested in cars, with little to no knowledge about the world of car enthusiasts and street racers. The son of a tofu shop owner, he is tasked to deliver tofu every morning without fail, driving along the mountain of Akina. Thus, conversations regarding cars or driving in general would only remind Takumi of the tiring daily routine forced upon him.

One night, the Akagi Red Suns, an infamous team of street racers, visit the town of Akina to challenge the local mountain pass. Led by their two aces, Ryousuke and Keisuke Takahashi, the Red Suns plan to conquer every racing course in Kanto, establishing themselves as the fastest crew in the region. However, much to their disbelief, one of their aces is overtaken by an old Toyota AE86 during a drive back home from Akina. After the incident, the Takahashi brothers are cautious of a mysterious driver geared with remarkable technique and experience in the local roads—the AE86 of Mount Akina.

[Written by MAL Rewrite]', 32, 91, 'https://myanimelist.net/images/anime/1384/127972.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37095, 'Violet Evergarden: Kitto "Ai" wo Shiru Hi ga Kuru no Darou', 'ヴァイオレット・エヴァーガーデンきっと"愛"を知る日が来るのだろう', 'UNKNOWN', 1, 'FINISHED', 8.36, 222247, 273, 738, 'The CH Postal Company has just received a request to transcribe a love letter from Irma Felice, a famous opera singer. Accepting the task, Violet Evergarden visits Irma to write her letter. However, not only does Irma provide little information, she asks Violet to write based on her own feelings. Despite Violet''s numerous attempts, Irma finds every version of the letter inadequate.

Violet consults her colleagues, and they help her out by writing love letters of their own. Yet even those are rejected by the opera singer. As a last resort, Violet asks Irma for her true thoughts and feelings, hoping to find the missing puzzle piece. Will the Auto Memory Doll be able to translate Irma''s emotions into words?

[Written by MAL Rewrite]', NULL, 15, 'https://myanimelist.net/images/anime/9/89993.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (22789, 'Barakamon', 'ばらかもん', 'TV', 12, 'FINISHED', 8.36, 361988, 261, 331, 'Seishuu Handa is an up-and-coming calligrapher: young, handsome, talented, and unfortunately, a narcissist to boot. When a veteran labels his award-winning piece as "unoriginal," Seishuu quickly loses his cool with severe repercussions.

As punishment, and also in order to aid him in self-reflection, Seishuu''s father exiles him to the Goto Islands, far from the comfortable Tokyo lifestyle the temperamental artist is used to. Now thrown into a rural setting, Seishuu must attempt to find new inspiration and develop his own unique art style—that is, if boisterous children (headed by the frisky Naru Kotoishi), fujoshi middle schoolers, and energetic old men stop barging into his house! The newest addition to the intimate and quirky Goto community only wants to get some work done, but the islands are far from the peaceful countryside he signed up for. Thanks to his wacky neighbors who are entirely incapable of minding their own business, the arrogant calligrapher learns so much more than he ever hoped to.

[Written by MAL Rewrite]', 82, 48, 'https://myanimelist.net/images/anime/1426/111248.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (58919, 'Hyakuemu.', 'ひゃくえむ。', 'UNKNOWN', 1, 'FINISHED', 8.35, 39996, 280, 2979, 'For as long as anyone can remember, Togashi has been the fastest elementary school student around. His speed makes him untouchable during every gym class and sports day, and there is nowhere his skill shines brighter than the hundred-meter dash. Bored by the lack of competition, he decides to help train Komiya, a transfer student who loves to run, but whose bad form leaves him consistently in last place. For a short time, the two are inseparable, united by their pursuit of speed. That is, until Komiya moves away just as suddenly as he came.

Years pass, and both boys continue to hone their skills. While their paths and obstacles differ, they each strive to push themselves to the limit, and find out whether Togashi''s long-held belief—that all problems can be solved by being the fastest runner in the hundred-meter dash—is true.

[Written by MAL Rewrite]', NULL, 93, 'https://myanimelist.net/images/anime/1259/151080.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (57067, 'Fanren Xiu Xian Zhuan: Xinghai Feichi', '凡人修仙传 星海飞驰', 'ONA', 48, 'FINISHED', 8.35, 1757, 277, 10294, 'Third season of Fanren Xiu Xian Zhuan.', NULL, 56, 'https://myanimelist.net/images/anime/1763/155878.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39547, 'Yahari Ore no Seishun Love Comedy wa Machigatteiru. Kan', 'やはり俺の青春ラブコメはまちがっている。完', 'TV', 12, 'FINISHED', 8.35, 457051, 281, 274, 'Resolved to become a more independent person, Yukino Yukinoshita decides to smoothen things out with her parents, and the first step toward achieving that goal is to prove herself.

As graduation draws closer for the third-year students, Iroha Isshiki—the president of the student council—requests a graduation prom in collaboration with the Volunteer Service Club. Yukino accepts this request of her own volition, hoping to use it as a chance to demonstrate her self-reliance, but what lies ahead of her may prove to be a hard hurdle to cross.

Yahari Ore no Seishun Love Comedy wa Machigatteiru. Kan revolves around the graduation prom as emotions are poured into the preparations for the event. At the same time, a chance for the Volunteer Service Club members to better understand each other presents itself. And thus, Hachiman Hikigaya''s hectic and bittersweet high school life begins to draw to a close.

[Written by MAL Rewrite]', 83, 94, 'https://myanimelist.net/images/anime/1958/107912.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (31988, 'Hibike! Euphonium 2', '響け！ユーフォニアム2', 'TV', 13, 'FINISHED', 8.35, 136476, 279, 1090, 'Following their success in the qualifying round for the Kansai regional competition, the members of the Kitauji High School concert band set their sights on the next upcoming performance. Utilizing their summer break to the utmost, the band participates in a camp where they are instructed by their band advisor Noboru Taki and his friends who make their living as professional musicians.

Kumiko Oumae and her friends remain determined to attain gold at the Kansai competition, but trouble arises when a student who once quit the band shows interest in rejoining and sparks unpleasant memories for the second-year members. Kumiko also learns about her teacher''s surprising past and the motivation behind his desire to lead the band to victory. Reaching nationals will require hard work, and the adamant conviction in each student''s commitment to the band will be put to the test.

[Written by MAL Rewrite]', 29, 15, 'https://myanimelist.net/images/anime/10/81155.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (41025, 'Fumetsu no Anata e', '不滅のあなたへ', 'TV', 20, 'FINISHED', 8.35, 425078, 278, 194, 'An Orb, known only as It, is cast to Earth to be observed from afar. Capable of changing forms from beings whose reflections It captures, It first becomes a rock and then, due to the rising temperature, moss.

It does not move until one snowy day, a wolf at death''s door barely crosses by. When It takes the animal''s form, It attains awareness of its consciousness and starts to wander with an unclear destination in mind. Soon, It comes across the wolf''s master—a young boy waiting for his tribe to return from a paradise abundant with fish and fruit in the south. Although the boy is lonely, he still hopes those whom he holds dear in his memories have not forgotten him and that he will reunite with them one day.

The boy wants to explore new surroundings and decides to abandon his home with It to find the paradise using the traces his tribe left behind. However, with a heavily injured body and no sight of his elder comrades, what will become of the boy?

Fumetsu no Anata e illustrates the story of an immortal being experiencing humanity, meeting all types of people in many places throughout time.

[Written by MAL Rewrite]', 11, 44, 'https://myanimelist.net/images/anime/1880/118484.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (41457, '86', '86―エイティシックス―', 'TV', 11, 'FINISHED', 8.35, 508097, 274, 200, 'According to the Republic of San Magnolia, their ongoing war against the Giadian Empire has no casualties—however, that is mere propaganda. While the silver-haired Alba of the Republic''s eighty-five sectors live safely behind protective walls, those of different appearances are interned in a secret eighty-sixth faction. Known within the military as the Eighty-Six, they are forced to fight against the Empire''s autonomous Legion under the command of the Republican "Handlers."

Vladilena Milizé is assigned to the Spearhead squadron to replace their previous Handler. Shunned by her peers for being a fellow Eighty-Six supporter, she continues to fight against their inhumane discrimination. Shinei Nouzen is the captain of the Spearhead squadron. Infamous for being the sole survivor of every squadron he''s been in, he insists on shouldering the names and wishes of his fallen comrades. When the fates of these young souls from two different worlds collide, will it ignite the spark that lights their path to salvation, or will they burn themselves in the flames of despair?

[Written by MAL Rewrite]', 11, 13, 'https://myanimelist.net/images/anime/1987/117507.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2251, 'Baccano!', 'バッカーノ！', 'TV', 13, 'FINISHED', 8.35, 399057, 275, 205, 'During the early 1930s in Chicago, the transcontinental train, Flying Pussyfoot, is starting its legendary journey that will leave a trail of blood all over the country. At the same time in New York, the ambitious scientist Szilard and his unwilling aide Ennis are looking for missing bottles of the immortality elixir. In addition, a war between the mafia groups is getting worse. On board the Advena Avis, in 1711, alchemists are about to learn the price of immortality.

Based on the award-winning light novels of the same name, Baccano! follows several events that initially seem unrelated, both in time and place, but are part of a much bigger story—one of alchemy, survival, and immortality. Merging these events together are the kindhearted would-be thieves, Isaac and Miria, connecting various people, all of them with their own hidden ambitions and agendas, and creating lifelong bonds and consequences for everyone involved.

[Written by MAL Rewrite]', 75, 44, 'https://myanimelist.net/images/anime/3/14547.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10534, 'Doraemon Movie 31: Shin Nobita to Tetsujin Heidan - Habatake Tenshi-tachi', '映画 ドラえもん 新・のび太と鉄人兵団～はばたけ 天使たち～', 'UNKNOWN', 1, 'FINISHED', 8.35, 14563, 276, 5263, 'Jealous of Suneo''s new robot toy, Nobita asks Doraemon to build him an even better one. Doraemon initially refuses, until Nobita accidentally discovers pieces of a mysterious robot that falls from the sky. After gathering all the robot parts and assembled them together, the giant robot, Zanda Claus, is soon completed. The duo soon learn that the robot is not a mere toy, but a powerful weapon in the fight against the coming Robot Army that is going to attack Earth and enslave the human inhabitants of it. An invasion is near, as a mysterious girl Riruru (リルル, Alternative spelling: Lilulu, Lillele [Doko Demo Doa Scanlations]) shows up, looking for the robot.

(Source: Wikipedia)', NULL, 33, 'https://myanimelist.net/images/anime/7/72436.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59897, 'Kobayashi-san Chi no Maid Dragon: Samishigariya no Ryuu', '小林さんちのメイドラゴン さみしがりやの竜', 'UNKNOWN', 1, 'FINISHED', 8.34, 10951, 286, 3371, 'Miss Kobayashi, Tohru, Kanna, and Iruru''s peaceful lives are shattered when Kanna''s father, Kamun Kamui, leader of the Chaos Forces, arrives and forces her to return to the Dragon World to fix a past mistake. With a war brewing between Chaos and Harmony, Kanna must find a way to unite the two worlds but is torn between her loyalty to her friends and her father''s demands. Miss Kobayashi, however, refuses to let her go and tries to mend Kanna and Kamui''s broken bond. As dragons clash, Iruru uncovers a hidden force manipulating the war. Can they stop the war before it consumes both worlds?

(Source: Crunchyroll)', NULL, 15, 'https://myanimelist.net/images/anime/1134/148744.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (58390, 'Yofukashi no Uta Season 2', 'よふかしのうた Season2', 'TV', 12, 'FINISHED', 8.34, 92023, 290, 1173, 'A human may become a vampire only if they fall in love with one—and 14-year-old Kou Yamori wishes for nothing more. Kou has decided to fall in love with a vampire named Nazuna Nanakusa, and he has only 10 months of nightly rendezvous left to realize his goal.

Kou''s friends, Mahiru Seki and Akira Asai, are slowly coming to terms with the existence of vampires and Kou''s decision to become one. As Kou realizes that a woman close to Mahiru is a vampire, he is unsure whether to support this relationship.

Meanwhile, Anko Uguisu, the human detective bent on killing vampires, closes in on Nazuna and her coven. When an encounter leaves one of the vampires seriously injured, they learn that their human memories hold the key to a weakness that can be their demise—and to protect Nazuna, Kou must find out about her past.

[Written by MAL Rewrite]', 65, 95, 'https://myanimelist.net/images/anime/1509/148453.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55830, 'Fate/strange Fake', 'Fate/strange Fake', 'TV', 13, 'FINISHED', 8.34, 55510, 282, 1635, 'A new Holy Grail War is emerging in Snowfield, Nevada, where mages from around the world summon Servants, heroic spirits drawn from myth and history, to fight on their behalf. However, this war seems to differ from previous ones. The organization behind it appears to have used data from the Fuyuki Grail War for their ritual, resulting in strange happenings. 

Unbeknownst to most participants, this budding conflict is actually a fake Grail War. There exists another set of seven true Servants who are summoned to fight in the genuine Holy Grail War. One of these Servants is a powerful Saber-class who saves the life of Ayaka Sajou, his apparent master, after being summoned. 

With hidden agendas and unpredictable forces at play, the line between the fake and true Grail War becomes unclear, turning Snowfield into a dangerous battlefield.

[Written by MAL Rewrite]', 15, 13, 'https://myanimelist.net/images/anime/1752/150192.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (52684, 'Shen Yin Wangzuo 2nd Season', '神印王座 第二季', 'ONA', 182, 'FINISHED', 8.34, 2969, 288, 8034, 'Revealing himself to be a Dual Knight, Long Hao Chen triumphs in his match within his temple and advances to the finals. But before the grand finals can begin, ranking matches are conducted in each temple to determine the strongest within. During the rankings, Hao Chen is injured, enraging Sheng Cai''er and driving her to seek vengeance for what happened to him. Her actions cause a fight between the Knight Temple and Assassin Temple, only to be subdued after a shocking revelation—that Sheng Cai''er is a Reincarnated Saint.

The finals for the Demon Hunting Team Competition begin with the division of the sixty remaining participants into six groups. The top sixteen participants are then further pitted against each other to determine the top three. Each of the top three will be rewarded with a spiritual stove and the right to pick their teammates.

In order to become a knight that is capable of defeating the Demon Lord, Long Hao Chen must strive to be first in this competition so he can select the best teammates to give him a fighting chance.

[Written by MAL Rewrite]', NULL, 96, 'https://myanimelist.net/images/anime/1897/150028.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10937, 'Kidou Senshi Gundam: The Origin', '機動戦士ガンダムTHE ORIGIN', 'OVA', 6, 'FINISHED', 8.34, 36592, 284, 2660, 'In the year 0068 of the Universal Century, Casval Rem Deikun''s life is thrown into chaotic disarray after the assassination of his father, a prolific figure in the crusade towards civil rights for people who live away from the Earth''s surface. Casval and his sister Artesia receive aid from soldiers who were loyal to their father, and the siblings are whisked away from their home, separated, and thrown into a twisted fate that sees them come into their own as soldiers and adults.

Years before stealing the name Char Aznable or his "Red Comet" moniker, Casval must contend with the rise of a militarized version of his father''s ideology and his own vengeful nature as intergalactic war molds him into a legendary mobile suit pilot.

[Written by MAL Rewrite]', NULL, 9, 'https://myanimelist.net/images/anime/4/72702.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49458, 'Kono Subarashii Sekai ni Shukufuku wo! 3', 'この素晴らしい世界に祝福を！3', 'TV', 11, 'FINISHED', 8.34, 239260, 287, 458, 'Kazuma Satou, former NEET and current reincarnated adventurer, finally returns home after the incident at the Crimson Demon village. He is joined by his ever-reliable companions: self-absorbed goddess Aqua, one-trick pony arch-wizard Megumin, and masochistic crusader Lalatina Ford "Darkness" Dustiness. Following their recent exploits, the party is one step closer to vanquishing the Demon King and his armies—a terrifying task that Kazuma is eager to ignore for as long as possible. Things, however, are not going as smoothly as the group would like; they are constantly racking up debt, getting sidetracked during missions, and falling into traps due to their recklessness and eccentricities.

As the party struggles with their perennial issues, they receive an invitation from a princess interested in hearing tales of the group''s "heroic" deeds. Darkness'' pleas to refuse the invitation only fire the others up to accept it, marking the start of yet another uncanny adventure with unforeseen consequences.

[Written by MAL Rewrite]', 33, 97, 'https://myanimelist.net/images/anime/1758/141268.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (777, 'Hellsing Ultimate', 'HELLSING OVA', 'OVA', 10, 'FINISHED', 8.34, 525326, 283, 182, 'There exist creatures of darkness and evil that plague the night, devouring any human unfortunate enough to be caught in their grasp. On the other side is Hellsing, an organization dedicated to destroying these supernatural forces that threaten the very existence of humanity. At its head is Integra Fairbrook Wingates Hellsing, who commands a powerful military and spends her life fighting the undead.

Integra''s vast army, however, pales in comparison with her ultimate weapon: the vampire Alucard, who works against his own kind as an exterminator for Hellsing. With his new vampire servant, Seras Victoria, at his side, Alucard must battle not only monsters, but all those who stand to oppose Hellsing, be they in the guise of good or evil.

In a battle for mankind''s survival, Hellsing Ultimate proves that appearances are not all they may seem, and sometimes the greatest weapon can come in the form of one''s worst nightmare.

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/1012/143965.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49926, 'Kimetsu no Yaiba: Mugen Ressha-hen', '鬼滅の刃 無限列車編', 'TV', 7, 'FINISHED', 8.34, 591551, 285, 198, 'A mysterious string of disappearances on a certain train has caught the attention of the Demon Slayer Corps, and they have sent one of their best to exterminate what can only be a demon responsible. However, the plan to board the Mugen Train is delayed by a lesser demon who is terrorizing the mechanics and targeting a kind, elderly woman and her granddaughter. Kyoujurou Rengoku, the Flame Hashira, must eliminate the threat before boarding the train.

Sent to assist the Hashira, Tanjirou Kamado, Inosuke Hashira, and Zenitsu Agatsuma enter the train prepared to fight. But their monstrous target already has a devious plan in store for them and the two hundred passengers: by delving deep into their consciousness, the demon intends to obliterate everyone in a stunning display of the power held by the Twelve Kizuki. 

[Written by MAL Rewrite]', 38, 35, 'https://myanimelist.net/images/anime/1065/118763.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39551, 'Tensei shitara Slime Datta Ken 2nd Season', '転生したらスライムだった件', 'TV', 12, 'FINISHED', 8.34, 646587, 289, 162, 'Taking a break from his time as a teacher, the powerful slime Rimuru Tempest returns to his kingdom, eponymously named Tempest, just in time to begin negotiations with a nearby nation—the Kingdom of Eurazania. While the negotiations are anything but peaceful, they do end successfully, allowing Rimuru to return and finish teaching. When trying to again return to Tempest, this time permanently, Rimuru is stopped by a mysterious figure who is somehow able to constrain the many magical abilities he has at his disposal. 

In Tempest, the situation is even worse. A group of unknown humans has invaded the land and are assaulting its citizens, both influential and innocent. They are not just trying to bring harm either—they have the intent to kill. Can Rimuru overcome his powerful and dangerous foe and return to Tempest before it is too late?  

[Written by MAL Rewrite]', 25, 100, 'https://myanimelist.net/images/anime/1271/109841.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (12029, 'Uchuu Senkan Yamato 2199', '宇宙戦艦ヤマト2199', 'OVA', 26, 'FINISHED', 8.33, 42112, 297, 2032, 'Earth''s once green hills and rich blue oceans have been converted into a desolate wasteland by the relentless onslaught of planet bombs from the expansionist Gamilas Empire. By the year 2199, humankind has retreated to the depths of underground cities to escape the radiation.

However, all hope is not lost, as the distant planet Iscandar offers Earth its final salvation: the Cosmo Reverse System, capable of restoring Earth''s irradiated surface. In a desperate bid to retrieve this technology from Iscandar, the Earth Defense Force pours its remaining resources into the Yamato—an innovative, state-of-the-art battleship equipped with an infinite energy Wave Motion Engine.

From young talent such as Tactical Officer Susumu Kodai to accomplished veterans like Captain Juuzou Okita, the Yamato''s crew consists of many individuals, all varying in their experience on the battlefield. But despite their differences, one goal unifies them all: to complete their perilous 168,000 light-year voyage to Iscandar and save humanity from imminent doom.

[Written by MAL Rewrite]', NULL, 101, 'https://myanimelist.net/images/anime/2/36607.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (7655, 'Major S6', 'メジャー 第6シリーズ', 'TV', 25, 'FINISHED', 8.33, 39231, 292, 3045, 'The intense Baseball World Cup has reached its conclusion. Gorou Honda has regained his passion for baseball and is once again back in full gear. He has secured a team position with the Hornets and has travelled back to America to prepare for his spectacular debut as a Major League pitcher.

However, Gorou encounters a sudden series of unexpected issues and devastating events follow, crushing his motivation and potentially reducing the baseball career that he has worked tirelessly to maintain into crumbs. In the final season of Major, Gorou must yet again overcome immense hardship in order to save his baseball career. This time there is no simple solution, as the problem is deeply rooted within his own mind...

[Written by MAL Rewrite]', 62, 83, 'https://myanimelist.net/images/anime/2/75216.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2559, 'Romeo no Aoi Sora', 'ロミオの青い空', 'TV', 33, 'FINISHED', 8.33, 19314, 296, 3366, 'Romeo is a kindhearted and courageous boy living with his family in a small village in Switzerland. Unfortunately, Romeo becomes the interest of a man named Luini, known as "The God of Death," who is infamous for buying children and selling them as chimney sweeps in Milan. While visiting the village, Luini burns down Romeo''s family cornfield in an attempt to have Romeo as his own. With the cornfield gone and his father sustaining a head injury trying to put out the fire, Romeo bravely sells himself to the God of Death in order to help his family afford a doctor. 

On his way to Milan, Romeo meets a boy named Alfredo Martini and they quickly become friends. Just as Alfredo is sold to a different master, the two boys swear eternal friendship and vow to meet again. As a chimney sweep, Romeo faces many hardships and abuse, especially from his master''s family and a gang known as the Wolf Pack. But after reuniting with Alfredo, the two form a fraternity of chimney sweeps called "The Black Brothers," who will learn to fight against the Wolf Pack and help each other in times of need.

[Written by MAL Rewrite]', 84, 73, 'https://myanimelist.net/images/anime/4/17979.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (42984, 'Gotcha!', 'GOTCHA!', 'UNKNOWN', 1, 'FINISHED', 8.33, 20593, NULL, 4597, 'In a bright, grandiose city, a young boy and girl look for their partners amidst a technicolor tour de force. As the two embark on their respective quests, they encounter the familiar faces of those who have made their mark on the Pokémon world. Villains, champions, rivals, and professors alike grace the tallest skyscrapers and largest screens while the adventurous teens carry on in the search for their companions.

Gotcha! takes its viewers on a nostalgic trip to the riveting realm of Pokémon, encapsulating the electrifying essence of the franchise.

[Written by MAL Rewrite]', NULL, 3, 'https://myanimelist.net/images/anime/1637/109512.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (13601, 'Psycho-Pass', 'サイコパス', 'TV', 22, 'FINISHED', 8.33, 830353, 295, 70, 'Justice, and the enforcement of it, has changed. In the 22nd century, Japan enforces the Sibyl System, an objective means of determining the threat level of each citizen by examining their mental state for signs of criminal intent, known as their Psycho-Pass. Inspectors uphold the law by subjugating, often with lethal force, anyone harboring the slightest ill-will; alongside them are Enforcers, citizens that have become latent criminals, granted relative freedom in exchange for carrying out the Inspectors'' dirty work.

Into this world steps Akane Tsunemori, a young woman with an honest desire to uphold justice. However, as she works alongside veteran Enforcer Shinya Kougami, she soon learns that the Sibyl System''s judgments are not as perfect as her fellow Inspectors assume. With everything she has known turned on its head, Akane wrestles with the question of what justice truly is, and whether it can be upheld through the use of a system that may already be corrupt.

[Written by MAL Rewrite]', 7, 23, 'https://myanimelist.net/images/anime/1314/142015.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39535, 'Mushoku Tensei: Isekai Ittara Honki Dasu', '無職転生 ～異世界行ったら本気だす～', 'TV', 11, 'FINISHED', 8.33, 970298, 293, 84, 'Despite being bullied, scorned, and oppressed all of his life, a 34-year-old shut-in still found the resolve to attempt something heroic—only for it to end in a tragic accident. But in a twist of fate, he awakens in another world as Rudeus Greyrat, starting life again as a baby born to two loving parents.

Preserving his memories and knowledge from his previous life, Rudeus quickly adapts to his new environment. With the mind of a grown adult, he starts to display magical talent that exceeds all expectations, honing his skill with the help of a mage named Roxy Migurdia. Rudeus learns swordplay from his father, Paul, and meets Sylphiette, a girl his age who quickly becomes his closest friend.

As Rudeus'' second chance at life begins, he tries to make the most of his new opportunity while conquering his traumatic past. And perhaps, one day, he may find the one thing he could not find in his old world—love.

[Written by MAL Rewrite]', 25, 51, 'https://myanimelist.net/images/anime/1530/117776.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10030, 'Bakuman. 2nd Season', 'バクマン。2ndシーズン', 'TV', 25, 'FINISHED', 8.33, 222226, 291, 737, 'With the serialization of their new manga, "Detective Trap," the writer-artist team, Akito Takagi and Moritaka Mashiro, better known by their pseudonym Muto Ashirogi, are one step closer to becoming world-renowned mangaka. For Mashiro, however, serialization is just the first step. Having promised to marry his childhood sweetheart and aspiring voice actress, Azuki Miho, once his manga gets an anime adaptation, Mashiro must continue his to popularize Ashirogi''s work. A tremendously competitive cast of ambitious mangaka—including the wild genius, Eiji Niizuma; the elegant student, Yuriko Aoki, and her older admirer and partner, Takurou Nakai; the lazy prodigy, Kazuya Hiramaru; and the abrasive artist, Shinta Fukuda—both support and compete against Muto Ashirogi in creating the next big hit.

As they adjust to their young and seemingly untested new editor, the dynamic duo struggle to maintain their current serialization, secure the top spot in Shounen Jack, and ultimately, achieve an anime adaptation of their manga. With new rivals and friends, Bakuman. 2nd Season continues Takagi and Mashiro''s inspiring story of hard work and young love.

[Written by MAL Rewrite]', 6, 58, 'https://myanimelist.net/images/anime/3/34923.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (48653, 'Yoru ni Kakeru', '夜に駆ける', 'UNKNOWN', 1, 'FINISHED', 8.33, 12373, NULL, 5540, 'Music video of the song Yoru ni Kakeru by Yoasobi.', NULL, NULL, 'https://myanimelist.net/images/anime/1548/124083.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (20651, 'Natsume Yuujinchou: Itsuka Yuki no Hi ni', '夏目友人帳 新作OVA いつかゆきのひに', 'OVA', 1, 'FINISHED', 8.33, 38942, 294, 2609, 'As the first delicate snowflake touches the cold ground, Nyanko-sensei dozes on his hot-water bottle next to Takashi Natsume. While his aunt prepares a warm dinner, Natsume takes a walk, welcoming the snow and the chilly weather. However, his peaceful promenade is disturbed by a white, fluffy snowman yokai with perturbing black eyes, searching for something warm and sparkly. With no further information, Natsume sets off to help find what the spirit desires.

[Written by MAL Rewrite]', NULL, 44, 'https://myanimelist.net/images/anime/11/79742.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (60371, 'Seihantai na Kimi to Boku', '正反対な君と僕', 'TV', 12, 'FINISHED', 8.32, 78030, 308, 1528, 'Miyu Suzuki is a high school girl whose cheerful outlook on life is tempered by her need to fit in. Coincidentally, beside her in the classroom sits Yuusuke Tani, a boy unconcerned with others'' expectations. Their exchanges rarely extend beyond brief discourse, yet the polarity of their demeanors unexpectedly draws them to one another.

As their mutual interest grows, the newfound feelings are no longer easy to ignore. Eventually, Suzuki voices what is inside her heart, forcing both of them to confront the unspoken affection between them. With each passing moment, their relationship evolves, and they gradually come to better understand themselves and the person who is their polar opposite.

[Written by MAL Rewrite]', 15, 103, 'https://myanimelist.net/images/anime/1140/154457.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (51805, 'Ginga Eiyuu Densetsu: Die Neue These - Sakubou', '銀河英雄伝説 Die Neue These 策謀', 'UNKNOWN', 12, 'FINISHED', 8.32, 7538, 301, 5644, 'After Yang Wen-li successfully captures the Iserlohn Fortress, the Free Planets Alliance grows bolder in its militaristic ambitions. With recent incursions into Galactic Empire territory and the possession of a perfect beachhead, the Alliance is now able to deal significant damage to the Empire. However, Reinhard von Lohengramm has no intention of allowing the Free Planets Alliance to gain a foothold. He is adamant about carrying on his best friend Siegfried Kircheis'' dearest wish: to be the one to unite the universe. 

As wide-scale military clashes continue, the opportunist Adrian Rubinsky, Fezzan''s ambitious leader, attempts to take advantage of the war to further his personal goals.

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/1700/123762.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (28701, 'Fate/stay night: Unlimited Blade Works 2nd Season', 'Fate/stay night [Unlimited Blade Works] 2nd シーズン', 'TV', 13, 'FINISHED', 8.32, 605546, 299, 220, 'In the midst of the Fifth Holy Grail War, Caster sets her plans into motion, beginning with the capture of Shirou''s Servant Saber. With the witch growing ever more powerful, Rin and Archer determine she is a threat that must be dealt with at once. But as the balance of power in the war begins to shift, the Master and Servant find themselves walking separate ways.

Meanwhile, despite losing his Servant and stumbling from injuries, Shirou ignores Rin''s warning to abandon the battle royale, forcing his way into the fight against Caster. Determined to show his resolve in his will to fight, Shirou''s potential to become a protector of the people is put to the test.

Amidst the bloodshed and chaos, the motivations of each Master and Servant are slowly revealed as they sacrifice everything in order to arise as the victor and claim the Holy Grail.

[Written by MAL Rewrite]', 5, 35, 'https://myanimelist.net/images/anime/1881/124810.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39112, 'Kawaki wo Ameku', 'カワキヲアメク', 'UNKNOWN', 1, 'FINISHED', 8.32, 19045, NULL, 4677, 'Music video for the song Kawaki wo Ameku by Minami.', NULL, NULL, 'https://myanimelist.net/images/anime/1776/121796.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5420, 'Kemono no Souja Erin', '獣の奏者エリン', 'TV', 50, 'FINISHED', 8.32, 23108, 303, 2476, 'In the land of Ryoza, the neighboring provinces of Shin-Ou and Tai-Kou have been at peace. Queen Shinou is the ruler of Ryoza and her greatest general, Grand Duke Taikou, defends the kingdom with his army of powerful war-lizards known as the "Touda." Although the two regions have enjoyed a long-standing alliance, mounting tensions threaten to spark a fierce civil war.

Within Ake, a village in Tai-Kou tasked with raising the Grand Duke''s army, lives Erin, a bright girl who spends her days watching the work of her mother Soyon, the village''s head Touda doctor. But while under Soyon''s care, a disastrous incident befalls the Grand Duke''s strongest Touda, and the peace that Erin and her mother had been enjoying vanishes as Soyon is punished severely. In a desperate attempt to save her mother, Erin ends up falling in a river and is swept towards Shin-Ou.

Unable to return home, Erin must learn to lead a new life with completely different people, all while hunting for the truth of both beasts and humanity itself, with tensions between the two regions constantly escalating.

[Written by MAL Rewrite]', 44, 23, 'https://myanimelist.net/images/anime/1929/121700.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5040, 'One Outs', 'ワンナウツ', 'TV', 25, 'FINISHED', 8.32, 123285, 306, 1091, 'Toua Tokuchi is a prodigy when it comes to both baseball and gambling. Pitching nothing but mediocre fastballs, he has made a name for himself by attaining 499 consecutive victories in the game of One Outs: a one-on-one showdown between a pitcher and a batter. Despite his remarkable abilities, however, Tokuchi sees the sport as nothing more than a way to make some quick money.

When Hiromichi Kojima, a legendary hitter for the struggling Saikyou Saitama Lycaons, witnesses Tokuchi''s skills firsthand, he realizes that the man might be exactly what the team needs to get out of their slump. Determined to recruit Tokuchi no matter what, Kojima places his own career on the line and defeats Tokuchi at his own specialty—One Outs.

Forced to become a Lycaon, Tokuchi soon finds himself at odds with the team''s owner, Tsuneo Saikawa. After Saikawa refuses to give him a reasonable salary, Tokuchi proposes a special contract: pitching an out will earn him five million yen, but giving up a run will cost him fifty million. With every game having the potential to either make or break him, Tokuchi must outwit all who stand in his way.

[Written by MAL Rewrite]', 12, 1, 'https://myanimelist.net/images/anime/7/21065.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39587, 'Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season', 'Re：ゼロから始める異世界生活 2', 'TV', 13, 'FINISHED', 8.32, 755608, 307, 126, 'A reunion that was supposed to spell the arrival of peaceful times is quickly shattered when Subaru Natsuki and Emilia return to Irlam village. Witnessing the devastation left behind by the calamities known as Sin Archbishops, Subaru sinks into the depths of despair as his ability to redo proves futile.

As the group makes their way to the Sanctuary in search of answers, Subaru has an unexpected encounter with the Witch of Greed—Echidna. Subjected to her untamed rhythm, he is forced to dive into the spirals of the past and future. At the same time, several mysterious threats set their sights on the Sanctuary, heralding a horrific fate for the hapless people trapped within.

Everlasting contracts, past sins, and unrequited love will clash and submerge into a river of blood in the second season of Re:Zero kara Hajimeru Isekai Seikatsu. Pushed to the brink of hopelessness, how long will Subaru''s resolve to save his loved ones last?

[Written by MAL Rewrite]', 83, 5, 'https://myanimelist.net/images/anime/1444/108005.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (42941, 'Uma Musume: Pretty Derby Season 2', 'ウマ娘 プリティーダービー Season 2', 'TV', 13, 'FINISHED', 8.32, 59128, 309, 2233, 'Within the horse-racing world, the horse girls of Team Spica have been gaining popularity as they continue to rack up victories. The one receiving the most attention in the group is Toukai Teiou, known for her cheerful personality and exceptional running skills. Teiou aims to become an undefeated Triple Crown horse girl by winning all three G1 races consecutively, a feat that has not been accomplished since the legendary Symboli Rudolf managed to do so many years ago.

On her path to obtaining the Triple Crown, Teiou is met with many challenges, encountering both old and new rivals. Amidst her fierce rivalries, however, Teiou is soon confronted with decisions that will leave a huge impact on her very own racing career.

[Written by MAL Rewrite]', 25, 105, 'https://myanimelist.net/images/anime/1447/114282.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34240, 'Shelter (Music)', 'シェルター', 'UNKNOWN', 1, 'FINISHED', 8.32, 220572, NULL, 855, 'Day 2539: Rin wakes up alone again with blurred memories and still no contact from any other human. She is not bored, however, because in her arms lies a tablet capable of creating any world her heart desires. Day after day, Rin crafts a wonderful reality—one utopia at a time—to shelter her from loneliness, hoping to one day reveal the truth behind her very existence.

[Written by MAL Rewrite]', NULL, 13, 'https://myanimelist.net/images/anime/5/82388.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5081, 'Bakemonogatari', '化物語', 'TV', 15, 'FINISHED', 8.32, 771708, 298, 98, 'Koyomi Araragi, a third-year high school student, manages to survive a vampire attack with the help of Meme Oshino, a strange man residing in an abandoned building. Though being saved from vampirism and now a human again, several side effects such as superhuman healing abilities and enhanced vision still remain. Regardless, Araragi tries to live the life of a normal student, with the help of his friend and the class president, Tsubasa Hanekawa.

When fellow classmate Hitagi Senjougahara falls down the stairs and is caught by Araragi, the boy realizes that the girl is unnaturally weightless. Despite Senjougahara''s protests, Araragi insists he help her, deciding to enlist the aid of Oshino, the very man who had once helped him with his own predicament.

Through several tales involving demons and gods, Bakemonogatari follows Araragi as he attempts to help those who suffer from supernatural maladies.

[Written by MAL Rewrite]', 85, 18, 'https://myanimelist.net/images/anime/11/75274.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (22535, 'Kiseijuu: Sei no Kakuritsu', '寄生獣 セイの格率', 'TV', 24, 'FINISHED', 8.32, 1250964, 304, 43, 'All of a sudden, they arrived: parasitic aliens that descended upon Earth and quickly infiltrated humanity by burrowing into the brains of vulnerable targets. These insatiable beings acquire full control of their host and are able to morph into a variety of forms in order to feed on unsuspecting prey.
 
Sixteen-year-old high school student Shinichi Izumi falls victim to one of these parasites, but it fails to take over his brain, ending up in his right hand instead. Unable to relocate, the parasite, now named Migi, has no choice but to rely on Shinichi in order to stay alive. Thus, the pair is forced into an uneasy coexistence and must defend themselves from hostile parasites that hope to eradicate this new threat to their species.

[Written by MAL Rewrite]', 37, 1, 'https://myanimelist.net/images/anime/3/73178.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10162, 'Usagi Drop', 'うさぎドロップ', 'TV', 11, 'FINISHED', 8.32, 255505, 310, 484, 'Daikichi Kawachi is a 30-year-old bachelor working a respectable job but otherwise wandering aimlessly through life. When his grandfather suddenly passes away, he returns to the family home to pay his respects. Upon arriving at the house, he meets a mysterious young girl named Rin who, to Daikichi’s astonishment, is his grandfather''s illegitimate daughter!
 
The shy and unapproachable girl is deemed an embarrassment to the family, and finds herself ostracized by her father''s relatives, all of them refusing to take care of her in the wake of his death. Daikichi, angered by their coldness toward Rin, announces that he will take her in—despite the fact that he is a young, single man with no prior childcare experience.

Usagi Drop is the story of Daikichi''s journey through fatherhood as he raises Rin with his gentle and affectionate nature, as well as an exploration of the warmth and interdependence that are at the heart of a happy, close-knit family.

[Written by MAL Rewrite]', 57, 23, 'https://myanimelist.net/images/anime/1460/98853.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (137, 'Hunter x Hunter: Original Video Animation', 'HUNTER×HUNTER Original Video Animation', 'OVA', 8, 'FINISHED', 8.32, 70728, 302, 1910, 'After reuniting with Gon and his friends, Kurapika explained to them the risks he bears because of his abilities. Believing that his target of revenge is no longer alive and the search for his fallen comrade''s eyes could truly begin, Kurapika soon after receives a message informing him that all the Spiders still lived. After much discussion between his friends, Gon, Kurapika and company decided to hunt after the one Spider member who''s ability could ultimately result in Kurapika''s defeat and death. Based on the manga by Togashi Yoshihiro.', NULL, 73, 'https://myanimelist.net/images/anime/1/137.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1210, 'NHK ni Youkoso!', 'N・H・Kにようこそ！', 'TV', 24, 'FINISHED', 8.32, 372377, 305, 264, 'Twenty-two-year-old college dropout Tatsuhiro Satou has been a hikikomori for almost four years now. In his isolation, he has come to believe in many obscure conspiracy theories, but there is one in particular which he holds unshakable faith in: the theory that the evil conspirator behind his shut-in NEET (Not in Employment, Education or Training) status is the Nihon Hikikomori Kyokai (NHK)—an evil and secret organization dedicated to fostering the spread of hikikomori culture.

NHK ni Youkoso! is a psychological dramedy that follows Tatsuhiro as he strives to escape from the NHK''s wicked machinations and the disease of self-wrought isolation, while struggling to even just leave his apartment and find a job. His unexpected encounter with the mysterious Misaki Nakahara might signal a reversal of fortune for Tatsuhiro, but with this meeting comes the inevitable cost of having to face his greatest fear—society.

[Written by MAL Rewrite]', 86, 106, 'https://myanimelist.net/images/anime/3/52675.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (42886, 'Ginga Eiyuu Densetsu: Die Neue These - Gekitotsu', '銀河英雄伝説 Die Neue These 激突', 'UNKNOWN', 12, 'FINISHED', 8.32, 10004, 300, 4945, 'As Yang is ordered to appear before the Free Planet Alliance, he’s shaken by the corruption he discovers. Meanwhile, Marshal Reinhardt uncovers disloyalty under his command as an upstart admiral launches a vicious offensive to retake the Iserlohn Fortress. Struggling to make strides in this never-ending bloody war, these two finally see their true enemy lies not from without—but from within!

(Source: Crunchyroll)', NULL, 23, 'https://myanimelist.net/images/anime/1859/118711.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55357, 'Bocchi the Rock! Movie', 'ぼっち・ざ・ろっく！劇場総集編', 'UNKNOWN', 2, 'FINISHED', 8.31, 8516, 311, 2927, 'Theatrical compilation of Bocchi the Rock!', NULL, 26, 'https://myanimelist.net/images/anime/1256/142261.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (51440, 'Sasaki to Miyano Movie: Sotsugyou-hen', '映画 佐々木と宮野ー卒業編ー', 'UNKNOWN', 1, 'FINISHED', 8.31, 22617, 314, 3222, 'With university entrance exams and graduation drawing close, high school senior Shuumei Sasaki has to start taking his future more seriously. However, Sasaki is increasingly finding it hard to study; all he can think about is his boyfriend and junior, Yoshikazu Miyano. Having only recently made their relationship official, Sasaki cannot help but yearn to hold his boyfriend close. But with Sasaki''s graduation on their minds, the couple begins to wonder what lies ahead for them both—especially as a public relationship can garner scrutiny from friends and family.

[Written by MAL Rewrite]', NULL, 32, 'https://myanimelist.net/images/anime/1574/128922.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34534, 'Natsume Yuujinchou Go Specials', '夏目友人帳 伍 特別編', 'UNKNOWN', 2, 'FINISHED', 8.31, 24432, 313, 3501, 'One Night Sake Cup 
On his way back home from an errand, Takashi Natsume gets lost in the forest. Luckily, he is rescued by a traveling youkai couple who make sake cups for a living. Taking a sip of water from one, Natsume feels a surge of energy rush throughout his body, thanks to the "One Night Cup." It is a special cup that makes every drink delicious, but unfortunately, its effects last only for one night. The following day, Natsume attends the youkai banquet with his loyal protector, the sake-loving chubby cat Madara, and gets the once-in-a-lifetime opportunity to learn how to make sake cups.

Party of Fun &amp; Games
Natsume is filled with regret after hastily declining a rare invitation to a banquet from Madara. Curious, he chases after the cat to an old, run-down mansion but soon enough feels the uncanny presence of numerous youkai nearby. When he runs into the seductive youkai Hinoe, she explains that the empty estate serves as a hide-and-seek playground where the winning spirit acquires authority over a valley. With still no trace of Madara, Natsume starts having eerie dreams of the mansion, but this time as the game''s participant.

[Written by MAL Rewrite]', NULL, 22, 'https://myanimelist.net/images/anime/3/84887.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (30230, 'Diamond no Ace: Second Season', 'ダイヤのA[エース]～Second Season～', 'TV', 51, 'FINISHED', 8.31, 83129, 312, 1764, 'After the National Tournament, the Seidou High baseball team moves forward with uncertainty as the Fall season quickly approaches. In an attempt to build a stronger team centered around their new captain, fresh faces join the starting roster for the very first time. Previous losses weigh heavily on the minds of the veteran players as they continue their rigorous training, preparing for what will inevitably be their toughest season yet.
 
Rivals both new and old stand in their path as Seidou once again climbs their way toward the top, one game at a time. Needed now more than ever before, Furuya and Eijun must be determined to pitch with all their skill and strength in order to lead their team to victory. And this time, one of these young pitchers may finally claim that coveted title: "The Ace of Seidou."

[Written by MAL Rewrite]', 5, 23, 'https://myanimelist.net/images/anime/9/74398.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (62568, 'Dr. Stone: Science Future Part 3', 'Dr.STONE SCIENCE FUTURE 第3クール', 'TV', 13, 'AIRING', 8.3, 11022, 318, 2021, 'Third part of Dr. Stone: Science Future.', 17, 14, 'https://myanimelist.net/images/anime/1773/155779.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59953, 'Mushen Ji', '牧神记', 'ONA', NULL, 'AIRING', 8.3, 12952, 322, 6068, 'In the Disabled Elderly Village, there live nine elderly people with unpredictable origins and the young man Qin Mu they raised. One day, the cows that Qin Mu was responsible for grazing began to speak human words. From then on, Qin Mu became more aware of the dangers and beauty of Daxu, a land abandoned by gods: demons descended with darkness, divine bones danced in the ruins, and dragon bones protected their young, a giant ship that drags the sun... No matter what kind of danger he faces, Qin Mu is fearless. He has integrated the skills passed down by the Nine Elders and vowed to carve out a world with his unparalleled hegemony. 

(Source: Bilibili, translated)', NULL, 87, 'https://myanimelist.net/images/anime/1324/150012.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (56752, 'Shiguang Dailiren: Yingdu Pian', '時光代理人 英都篇', 'ONA', 6, 'FINISHED', 8.3, 27759, 325, 3035, 'Lu Guang loses everything when a mysterious man bursts into the photo studio that he is renting with his close friend Cheng Xiaoshi. The man, who comes to punish the members at the studio for playing with time, murders both Qiao Ling and Cheng Xiaoshi in cold blood. However, Lu Guang inherits his friend''s power to go back in time and decides to save everyone from their grim fate.

Now in the past, Lu Guang travels to Bridon to help Cheng Xiaoshi investigate his father''s whereabouts; however, he discovers an uncanny series of small disparities that cause the situation to spiral into complete uncertainty. Suddenly unable to rely on his ability to predict the future, Lu Guang must invent a new strategy to foil the plans of the man who took everything from him.

[Written by MAL Rewrite]', NULL, 107, 'https://myanimelist.net/images/anime/1496/147189.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55644, 'Dr. Stone: New World Part 2', 'Dr.STONE NEW WORLD', 'TV', 11, 'FINISHED', 8.3, 231200, 317, 628, 'Years ago, astronaut Byakuya left behind precious materials in the belief that his son, the scientifically-gifted Senkuu, would one day find them. In the present, the Kingdom of Science''s Kohaku and Ginrou have infiltrated the harem of the Petrification Kingdom’s leader with the help of Amaryllis, a local girl. At first, their mission progresses without a hitch. Unfortunately, an error enacted by Kohaku and Ginrou leads Minister Ibara and the Island’s strongest warrior, Moz, to identify the intruding duo as enemies.

Even worse, Moz tails Amaryllis when she returns to inform Senkuu of the news, discovering the scientist''s secret hideout. However, Moz''s agenda does not align with Ibara''s—he wants to dethrone the minister and keep the petrification device for himself. If Senkuu plays his cards right, he could gain a powerful ally and win the war once and for all.

[Written by MAL Rewrite]', 1, 14, 'https://myanimelist.net/images/anime/1236/138696.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5341, 'Ookami to Koushinryou II', '狼と香辛料II', 'TV', 12, 'FINISHED', 8.3, 289843, 324, 488, 'Traveling merchant Kraft Lawrence continues his northward journey with wolf goddess Holo, in search of her lost home of Yoitsu. Lawrence and his sharp-witted partner continue to make some small profits along the way, while slowly uncovering more information about Holo''s hometown. However, the road to Yoitsu is a bumpy one filled with many troubles—Lawrence runs into a charming young fellow merchant who has his eyes set on the female wolf companion, and he begins to doubt if Holo will remain by his side; he and the goddess will also have to consider precarious and risky business deals as Lawrence strives to achieve his dream of becoming a shopowner. All the while, with his determination tested at every turn during his journey, Lawrence must question his relationship with Holo, take on business ventures, and ask himself whether it is time for him and Holo to go their separate ways.

[Written by MAL Rewrite]', 85, 44, 'https://myanimelist.net/images/anime/6/59399.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (4081, 'Natsume Yuujinchou', '夏目友人帳', 'TV', 13, 'FINISHED', 8.3, 200012, 323, 427, 'Due to an unusual ability to see strange creatures called youkai, Takashi Natsume has never fit in. Passed around from one foster home to another, he was left isolated and lonely. Over time, he has accepted that no one would ever believe him and has closed himself off to his current caretakers and classmates.

When Natsume accidentally breaks an intangible barrier, he frees Madara—a mighty spirit in the form of a lucky cat. Madara notices that Natsume bears a remarkable resemblance to his late grandmother Reiko Natsume, an outcast girl who became known across the youkai world for creating the Book of Friends. It is now in Natsume''s possession, along with its power to call upon the written names of the youkai Reiko had defeated. 

With no interest in its powers, Natsume decides to keep the book for the sake of his grandmother''s memories and to protect it from scheming youkai. Therefore, he makes a deal with Madara: he will hand him the book once his time is up, and in turn, Madara will act as Natsume''s unofficial bodyguard, nicknamed Nyanko-sensei. With his newfound goal of freeing those Reiko had sealed, Natsume''s relationship with both youkai and humans slowly begins to improve.

[Written by MAL Rewrite]', 87, 44, 'https://myanimelist.net/images/anime/1681/108439.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (3784, 'Evangelion Movie 2: Ha', 'ヱヴァンゲリヲン新劇場版:破', 'UNKNOWN', 1, 'FINISHED', 8.3, 365758, 319, 423, 'When the threat of the Angel menace escalates, mankind''s defense force is pushed to its limits, with NERV at the forefront of the struggle. Shinji Ikari and his partner Rei Ayanami are assisted by two new pilots: the fiery Asuka Langley Shikinami and the mysterious Mari Illustrious Makinami.

With the aid of their mechanized Evangelion units, equipped with weapons perfect for engaging their monstrous opponents, the four young souls fight desperately to protect their loved ones and prevent an impending apocalypse. But when startling secrets are brought to light, will the heroes'' greatest challenge prove to be the monsters...or humanity itself?

[Written by MAL Rewrite]', NULL, 53, 'https://myanimelist.net/images/anime/5/74983.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (22507, 'Initial D Final Stage', '頭文字 D Final Stage', 'TV', 4, 'FINISHED', 8.3, 85812, 320, 1632, 'In the final match against the Kanagawa street racing team Sidewinder, Project D street racer Takumi Fujiwara is faced with a surprising challenger: Shinji Inui, a 17-year-old high school student. Beginning to drive at a very young age, Shinji is not only familiar with the mountain pass where the race is taking place, but he also drives a Toyota AE86—the same car model Takumi uses.

Initially reluctant to participate due to a lack of enthusiasm, Shinji becomes motivated after witnessing the fiery battle between Keisuke Takahashi and Gou Houjou. Undefeated in his home course known as the Tsubaki Line, Shinji might prove to be Takumi''s most formidable opponent yet.

[Written by MAL Rewrite]', 42, 83, 'https://myanimelist.net/images/anime/1404/101364.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (31043, 'Boku dake ga Inai Machi', '僕だけがいない街', 'TV', 12, 'FINISHED', 8.3, 1477281, 315, 29, 'When tragedy is about to strike, Satoru Fujinuma finds himself sent back several minutes before the accident occurs. The detached, 29-year-old manga artist has taken advantage of this powerful yet mysterious phenomenon, which he calls "Revival," to save many lives.
 
However, when he is wrongfully accused of murdering someone close to him, Satoru is sent back to the past once again, but this time to 1988, 18 years in the past. Soon, he realizes that the murder may be connected to the abduction and killing of one of his classmates, the solitary and mysterious Kayo Hinazuki, that took place when he was a child. This is his chance to make things right.
 
Boku dake ga Inai Machi follows Satoru in his mission to uncover what truly transpired 18 years ago and prevent the death of his classmate while protecting those he cares about in the present.

[Written by MAL Rewrite]', 60, 13, 'https://myanimelist.net/images/anime/10/77957.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1365, 'Meitantei Conan Movie 06: Baker Street no Bourei', '名探偵コナン ベイカー街の亡霊', 'UNKNOWN', 1, 'FINISHED', 8.3, 51034, 321, 2642, 'The latest innovation in virtual reality gaming is set for a private showcase, with the children of Japan''s elite given the opportunity to playtest it. Unfortunately, their carefree fun is cut short when a company employee is found murdered, his dying message pointing to a clue hidden within the game''s historical setting.

Along with the Detective Boys and Ran Mouri, Conan Edogawa enters the game to solve this mystery and ensure the perpetrator is caught. But once they load in, an artificial intelligence named Noah''s Ark imprisons them and the other children within. To escape and bring the murderer to justice, Conan and company must navigate a simulated 19th-century London and track down the infamous Jack the Ripper—with the lives of 50 innocent children depending on them.

[Written by MAL Rewrite]', NULL, 14, 'https://myanimelist.net/images/anime/1400/94320.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37822, 'Douluo Dalu 2nd Season', '斗罗大陆', 'ONA', 237, 'FINISHED', 8.3, 10602, 316, 5122, 'Second season of Douluo Dalu.', NULL, 87, 'https://myanimelist.net/images/anime/1538/93566.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59408, 'Mononoke Movie 2: Hinezumi', '劇場版モノノ怪 第二章 火鼠', 'UNKNOWN', 1, 'FINISHED', 8.29, 6046, 334, 5365, 'One month after the Karakasa incident, the situation at the Inner Chambers is slowly returning to normal. To the noble families that run the country, normalcy means carrying on with their usual schemes to prevent any undesirable power shifts in the government. Their current target is the high-ranking concubine Fuki Tokita, who seems to be receiving Lord Tenshi''s attention despite being the daughter of a merchant and, therefore, socially unfit to give him an heir.

However, supernatural forces still dwell in the shadows. When several unnatural deaths take place in the Inner Chambers, its residents are once again forced to allow the presence of the mysterious Medicine Seller inside its halls. The Medicine Seller is the only one who might be able to determine the cause of these incidents—and find out what role Fuki plays in them.

[Written by MAL Rewrite]', NULL, 109, 'https://myanimelist.net/images/anime/1593/147889.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (54870, 'Seishun Buta Yarou wa Randoseru Girl no Yume wo Minai', '青春ブタ野郎はランドセルガールの夢を見ない', 'UNKNOWN', 1, 'FINISHED', 8.29, 82142, 338, 1495, 'As Sakuta Azusagawa waits for Mai Sakurajima at the beach on her high school graduation day, he encounters a version of Mai from her child acting days. However, when Mai finally arrives, her younger self disappears, leaving him confused. Sakuta spots an unfamiliar scar on his body when he returns home, which confirms his suspicion—he is involved in another case of the inexplicable Puberty Syndrome.

Not long after, Sakuta and his sister, Kaede, receive a call from their father. He tells them that their mother, who had been recently discharged from the hospital, wants to see her daughter once more. Experiencing strange occurrences while visiting his mother with Kaede, Sakuta must find a way to solve the Puberty Syndrome abnormalities.

[Written by MAL Rewrite]', NULL, 26, 'https://myanimelist.net/images/anime/1937/138379.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (11917, 'Major: World Series', 'メジャー ワールドシリーズ編', 'OVA', 2, 'FINISHED', 8.29, 22336, 333, 4053, 'Gorou Shigeno''s journey with the Indiana Hornets continues as they seek to win the prestigious World Series. However, after an unexpected accident during the match with his fated rival, his quest in becoming the world''s best becomes more challenging. Undaunted, Gorou continues to put the weight of his dreams into every pitch he makes, and forges a path towards his desired future through high-speed pitching.

[Written by MAL Rewrite]', NULL, 83, 'https://myanimelist.net/images/anime/5/75220.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38731, 'Diamond no Ace: Act II', 'ダイヤのA[エース] actII', 'TV', 52, 'FINISHED', 8.29, 51289, 328, 2365, 'The hallowed ground of Koshien Stadium is the "field of dreams," where the ambitions of high school baseball players come true. After emerging victorious in the autumn tournament last year, Seidou High School baseball''s team  has finally earned the right to compete there for the first time in seven years.  Beyond the spring tournament looms the battle to decide who is the best team in the nation  — the Summer Koshien.

 With the third-year players due to retire after the summer tournament, the team has to integrate the experience of the seniors and the potential of the newcomers to overcome familiar and new opponents alike and win the coveted national title. 

Meanwhile, pitcher Eijun Sawamura is as determined as ever to earn jersey No. 1  and seize the position of "ace" from his persistent rival, Satoru Furuya.  As the team prepares for their greatest challenge yet, Sawamura and Furuya carry on their struggle to lead their team to glory and become the star of the game: the true "Ace of the Diamond." 

[Written by MAL Rewrite]', 4, 1, 'https://myanimelist.net/images/anime/1153/100511.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10863, 'Steins;Gate: Oukoubakko no Poriomania', 'シュタインズ ゲート 横行跋扈のポリオマニア', 'UNKNOWN', 1, 'FINISHED', 8.29, 296508, 339, 553, 'A few months after the events of Steins;Gate, Rintarou Okabe and his group of friends are invited to tag along with their acquaintance Faris NyanNyan, who is participating in a Rai-Net battle event in the United States. There, they meet up with an old colleague: Kurisu Makise, who has been recalling fragmented memories of events that happened in the other world lines in the form of dreams. She confronts Okabe, questioning him as to whether these events—particularly the incidents between the two of them—did indeed happen.

[Written by MAL Rewrite]', NULL, 5, 'https://myanimelist.net/images/anime/1805/123188.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (17389, 'Kingdom 2nd Season', 'キングダム 第2シリーズ', 'TV', 39, 'FINISHED', 8.29, 74671, 331, 1773, 'A year after the devastating battle against the formidable Zhao, the State of Qin has returned its focus to pursuing King Ying Zheng''s ambition of conquering the other six states and unifying China. Their next target is Wei, a smaller state which stands as a geographic stepping stone for the sake of conquest.

Xin, now a three hundred man commander of the swiftly rising Fei Xin Unit, continues to seek out lofty achievements in order to garner recognition for himself and his soldiers, motivated by those previously lost in battle. In the preliminary battles ahead of Qin''s invasion of Wei, Xin finds competition in other young commanders who are of a higher social status than him. Back in Qin, the royal palace faces turmoil as opposing factions begin to make their move against Ying Zheng''s regime.

With their hands full both abroad and at home, Zheng and Xin must lead the way in this era of unending war, resolved to etch their names in history by creating a unified China.

[Written by MAL Rewrite]', 31, 12, 'https://myanimelist.net/images/anime/13/53589.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6675, 'Redline', 'REDLINE', 'UNKNOWN', 1, 'FINISHED', 8.29, 226067, 336, 632, 'Every five years, an exhilarating race called Redline is held, and the universe''s most anticipated competition has only one rule: that there are none. Racers are pushed to their absolute limit—a feeling that daredevil driver JP knows all too well. Having just qualified to participate in Redline, he is eager to battle against the other highly skilled drivers, particularly the beautiful rising star and the only other human that qualified, Sonoshee McLaren.

But this year''s Redline may be far more dangerous than usual—it has been announced to take place on the planet Roboworld with its trigger-happy military and criminals who look to turn the race to their own advantage. However, the potential danger doesn''t stop the racers; in fact, it only adds to the thrill. Relying solely on his vehicle''s speed, JP prepares for the event to come, aiming to take first place in the biggest race of his life.

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/12/28553.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (24415, 'Kuroko no Basket 3rd Season', '黒子のバスケ', 'TV', 25, 'FINISHED', 8.29, 512746, 332, 268, 'Seirin prepares to face major obstacles on their path to winning the Winter Cup, including the teams each possessing a member of the Generation of Miracles. Kuroko goes head-to-head with his old teammates once more as he attempts to show them that individual skill is not the only way to play basketball. His firm belief that his form of basketball, team play, is the right way to play the sport will clash with the talents of a perfect copy and an absolute authority.

While Kuroko tries to prove that his basketball is "right," he and the rest of Seirin High ultimately have one goal: to win the Winter Cup and overcome the strength of the Generation of Miracles, who have long dominated the scene of middle and high school basketball.

[Written by MAL Rewrite]', 73, 23, 'https://myanimelist.net/images/anime/4/68299.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6594, 'Katanagatari', '刀語', 'TV', 12, 'FINISHED', 8.29, 223873, 330, 422, 'In an Edo-era Japan lush with a variety of sword-fighting styles, Shichika Yasuri practices the most unique one: Kyotouryuu, a technique in which the user''s own body is wielded as a blade. The enigmatic seventh head of the Kyotouryuu school, Shichika lives quietly in exile with his sister Nanami until one day—the wildly ambitious strategist Togame barges into their lives.

Togame brazenly requests that Shichika help in her mission to collect twelve unique swords, known as the "Deviant Blades," for the shogunate. Shichika accepts, interested in the girl herself rather than petty politics, and thus sets out on a journey. Standing in their way are the fierce wielders of these legendary weapons as well as other power-hungry entities who seek to thwart Togame''s objective. In order to prevail against their enemies, the duo must become an unbreakable team as they forge ahead on a path of uncertainty and peril.

[Written by MAL Rewrite]', 88, 5, 'https://myanimelist.net/images/anime/1112/119225.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (759, 'Tokyo Godfathers', '東京ゴッドファーザーズ', 'UNKNOWN', 1, 'FINISHED', 8.29, 165409, 342, 848, 'One Christmas Eve, Hana, Gin, and Miyuki are rummaging for presents through heaps of garbage when they chance upon an abandoned baby in the cold winter night. Appalled at the pitiful sight, Hana''s maternal instincts kick in and she insists on finding the baby''s biological mother to demand an explanation. Naming the baby Kiyoko—meaning pure child—they begin their search using the possible clues left alongside her: a mysterious key and a single note. However, their plans are soon thrown into disarray as they get caught up in a series of unprecedented events.

Tokyo Godfathers follows the journey of the trio as they stick together through thick and thin, hoping to deliver Kiyoko to her true home, and find their very own Christmas miracle.

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/1480/132791.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (12531, 'Sakamichi no Apollon', '坂道のアポロン', 'TV', 12, 'FINISHED', 8.29, 182711, 337, 646, 'Introverted classical pianist and top student Kaoru Nishimi has just arrived in Kyushu for his first year of high school. Having constantly moved from place to place since his childhood, he abandons all hope of fitting in, preparing himself for another lonely, meaningless year. That is, until he encounters the notorious delinquent Sentarou Kawabuchi.

Sentarou''s immeasurable love for jazz music inspires Kaoru to learn more about the genre, and as a result, he slowly starts to break out of his shell, making his very first friend. Kaoru begins playing the piano at after-school jazz sessions, located in the basement of fellow student Ritsuko Mukae''s family-owned record shop. As he discovers the immense joy of using his musical talents to bring enjoyment to himself and others, Kaoru''s summer might just crescendo into one that he will remember forever.

Sakamichi no Apollon is a heartwarming story of friendship, music, and love that follows three unique individuals brought together by their mutual appreciation for jazz.

[Written by MAL Rewrite]', 63, 111, 'https://myanimelist.net/images/anime/1604/98654.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39533, 'Given', 'ギヴン', 'TV', 11, 'FINISHED', 8.29, 346917, 329, 389, 'Tightly clutching his Gibson guitar, Mafuyu Satou steps out of his dark apartment to begin another day of his high school life. While taking a nap in a quiet spot on the gymnasium staircase, he has a chance encounter with fellow student Ritsuka Uenoyama, who berates him for letting his guitar''s strings rust and break. Noticing Uenoyama''s knowledge of the instrument, Satou pleads for him to fix it and to teach him how to play. Uenoyama eventually agrees and invites him to sit in on a jam session with his two band mates: bassist Haruki Nakayama and drummer Akihiko Kaji.
    
Satou''s voice is strikingly beautiful, filling Uenoyama with the determination to make Satou the lead singer of the band. Though reticent at first, Satou takes the offer after an emotional meeting with an old friend. With the support of his new friends, Satou must not only learn how to play guitar, but also come to terms with the mysterious circumstances that led him to be its owner.

[Written by MAL Rewrite]', 27, 60, 'https://myanimelist.net/images/anime/1666/102238.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (50407, 'Wu Shan Wu Xing: Xichuan Huan Zi Lin', '雾山五行·犀川幻紫林', 'ONA', 4, 'FINISHED', 8.29, 6343, 343, 5598, 'Second season of Wu Shan Wu Xing.', NULL, 112, 'https://myanimelist.net/images/anime/1983/147467.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2150, 'Tanoshii Muumin Ikka', '楽しいムーミン一家', 'TV', 78, 'FINISHED', 8.29, 13937, 340, 4449, 'Spring has finally arrived in Moomin Valley, giving way to another great adventure for Moomintroll and the rest of its inhabitants. With Snufkin coming home from his winter migration, the locals of the valley finally begin to rise from their hibernation. Finding a mysterious hat, the Moomins cannot bring themselves to throw it away due to its fine quality, instead hoping to eventually find its owner. 

While playing games with his friends, Moomin tries to hide in the silk hat. When his friends come looking for him, they are shocked to discover that Moomin has transformed into a hideous creature. Examining himself in the mirror, he is disgusted to find himself completely unrecognizable.

Transforming back to normal after scaring his friends and family, Moomin and Snufkin decide to toss the hat in the river. As it drifts away, they begin to wonder who the hat belonged to and whether its owner will return for their lost possession.

[Written by MAL Rewrite]', 89, 113, 'https://myanimelist.net/images/anime/13/26765.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (41487, 'Tensei shitara Slime Datta Ken 2nd Season Part 2', '転生したらスライムだった件', 'TV', 12, 'FINISHED', 8.29, 527347, 341, 224, 'The nation of Tempest is in a festive mood after successfully overcoming the surprise attack from the Falmuth Army and the Western Holy Church. Beyond the festivities lies a meeting between Tempest and its allies to decide the future of the Nation of Monsters. The aftermath of the Falmuth invasion, Milim Nava''s suspicious behavior, and the disappearance of Demon Lord Carrion—the problems seem to keep on piling up.

Rimuru Tempest, now awakened as a True Demon Lord, decides to go on the offensive against Clayman. With the fully revived Storm Dragon Veldora, Ultimate Skill Raphael, and other powerful comrades, the ruler of the Tempest is confident in taking down his enemies one by one until he can face the man pulling the strings.

[Written by MAL Rewrite]', 90, 100, 'https://myanimelist.net/images/anime/1033/118296.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (57, 'Beck', 'ベック', 'TV', 26, 'FINISHED', 8.29, 151237, 327, 726, 'Fourteen-year-old Yukio "Koyuki" Tanaka is a dispirited young boy with no goals in life. However, this all changes when Koyuki saves a strange-looking dog named Beck from being harassed by a group of local kids. The dog''s owner, 16-year-old Ryuusuke "Ray" Minami, is an emerging guitarist and the former member of a popular rock band. 

After Koyuki meets Ray again in a diner, the older boy leads him to his former band''s meeting place and dazzles Koyuki with his amazing guitar skills. Slowly becoming interested in the glamour of western rock culture, Koyuki decides to start playing the guitar while helping Ray achieve his dream of leading the ultimate rock band. Together with Ray''s younger sister Maho and a few other members, the two boys launch their career into the world of rock by forming a band called BECK. Beck follows the group''s struggles and successes as they spread their fame across Japan.

[Written by MAL Rewrite]', 91, 1, 'https://myanimelist.net/images/anime/11/11636.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (9989, 'Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.', 'あの日見た花の名前を僕達はまだ知らない。', 'TV', 11, 'FINISHED', 8.29, 1034707, 326, 74, 'Jinta Yadomi is peacefully living as a recluse, spending his days away from school and playing video games at home instead. One hot summer day, his childhood friend, Meiko "Menma" Honma, appears and pesters him to grant a forgotten wish. He pays her no mind, which annoys her, but he doesn''t really care. After all, Menma already died years ago.

At first, Jinta thinks that he is merely hallucinating due to the summer heat, but he is later on convinced that what he sees truly is the ghost of Menma. Jinta and his group of childhood friends grew apart after her untimely death, but they are drawn together once more as they try to lay Menma''s spirit to rest. Re-living their pain and guilt, will they be able to find the strength to help not only Menma move on—but themselves as well?

[Written by MAL Rewrite]', 3, 13, 'https://myanimelist.net/images/anime/5/79697.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1735, 'Naruto: Shippuuden', '-ナルト- 疾風伝', 'TV', 500, 'FINISHED', 8.29, 1820792, 335, 15, 'It has been two and a half years since Naruto Uzumaki left Konohagakure, the Hidden Leaf Village, for intense training following events which fueled his desire to be stronger. Now Akatsuki, the mysterious organization of elite rogue ninja, is closing in on their grand plan which may threaten the safety of the entire shinobi world.
 
Although Naruto is older and sinister events loom on the horizon, he has changed little in personality—still rambunctious and childish—though he is now far more confident and possesses an even greater determination to protect his friends and home. Come whatever may, Naruto will carry on with the fight for what is important to him, even at the expense of his own body, in the continuation of the saga about the boy who wishes to become Hokage.

[Written by MAL Rewrite]', 92, 12, 'https://myanimelist.net/images/anime/1565/111305.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (43325, 'Yuukoku no Moriarty Part 2', '憂国のモリアーティ', 'TV', 13, 'FINISHED', 8.29, 137668, 344, 962, 'Great Britain is ablaze with news of a so-called "Lord of Crime," a criminal mastermind responsible for the downfall of several unruly nobles. In truth, the Lord of Crime is not an individual, but rather a group consisting of William James Moriarty and his two brothers, Louis and Albert. Together, they wish to destroy everything rotten about their current world and create a new, fair society for all. To accomplish their goal, they must commit criminal acts, which the great detective Sherlock Holmes and his partner, John H. Watson, cannot abide by. A dangerous cat and mouse game begins between the Lord of Crime and Sherlock, with each trying to outwit the other. Yet Sherlock, despite his skills, has no idea that his foe is right under his nose.

Involved with both parties is a woman named Irene Adler, who is as beautiful as she is cunning. No stranger to scandal, Irene has embroiled herself in one that may be too big even for her, as the classified documents she stole could shake the very foundations of the British Empire. Can Irene be saved, or does a deadly future await her?

[Written by MAL Rewrite]', 11, 23, 'https://myanimelist.net/images/anime/1200/111522.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (36371, 'Ginga Eiyuu Densetsu: Die Neue These - Seiran 3', '銀河英雄伝説 Die Neue These 星乱 第3章', 'UNKNOWN', 4, 'FINISHED', 8.28, 15015, 345, 4657, 'At the behest of Admiral Yang Wen-li, defected intelligence officer Commander Baghdash makes an emergency broadcast announcing that the National Salvation Military Council staged a coup under the direction of the Galactic Empire. Despite the lack of physical evidence, this debilitating declaration inspires former Rear Admiral Andrew Lynch to reveal his own role in sowing discord within the Free Planets Alliance. A fatal shootout between Lynch and Admiral Dwight Greenhill acts as the final death knell to the short-lived period of martial rule.

Within the Galactic Empire, footage of Duke Otto von Braunschweig''s nuclear bombing of Westerland results in the dissolution of the Lippstadt League. Marquis Reinhard von Lohengramm''s decision to allow the massacre for personal gain creates a rift between him and High Admiral Siegfried Kircheis, souring the taste of their inevitable victory. Now on the cusp of achieving absolute power, Reinhard is embattled by his apparent personal failings and the heavy responsibilities of leadership.

Though the civil wars in both the Alliance and the Empire are coming to a close, neither side can ever regain what is lost. Yang Wen-li and Reinhard von Lohengramm each take bitter solace in the knowledge that just on the other side of the galaxy is a worthy opponent—and a true equal.

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/1782/103917.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (486, 'Kino no Tabi: The Beautiful World', 'キノの旅 -the Beautiful World-', 'TV', 13, 'FINISHED', 8.28, 106237, 346, 767, 'Kino, a 15-year-old traveler, forms a bond with Hermes, a talking motorcycle. Together, they wander the lands and venture through various countries and places, despite having no clear idea of what to expect. After all, life is a journey filled with the unknown. 

Throughout their journeys, they encounter different kinds of customs, from the morally gray to tragic and fascinating. They also meet many people: some who live to work, some who live to make others happy, and some who live to chase their dreams. Thus, in every country they visit, there is always something to learn from the way people carry out their lives. 

It is not up to Kino or Hermes to decide whether these asserted values are wrong or right, as they merely assume the roles of observers within this small world. They do not attempt to change or influence the places they visit, despite how absurd these values would appear. That''s because in one way or another, they believe things are fine as they are, and that "the world is not beautiful; therefore, it is."

[Written by MAL Rewrite]', 93, 114, 'https://myanimelist.net/images/anime/1763/95397.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (45, 'Rurouni Kenshin: Meiji Kenkaku Romantan', 'るろうに剣心 -明治剣客浪漫譚-', 'TV', 94, 'FINISHED', 8.28, 248227, 347, 485, 'In the final years of the Bakumatsu era lived a legendary assassin known as Hitokiri Battousai. Feared as a merciless killer, he was unmatched throughout the country, but mysteriously disappeared at the peak of the Japanese Revolution. It has been ten peaceful years since then, but the very mention of Battousai still strikes terror into the hearts of war veterans.

Unbeknownst to them, Battousai has abandoned his bloodstained lifestyle in an effort to repent for his sins, now living as Kenshin Himura, a wandering swordsman with a cheerful attitude and a strong will. Vowing never to kill again, Kenshin dedicates himself to protecting the weak. One day, he stumbles across Kaoru Kamiya at her kendo dojo, which is being threatened by an impostor claiming to be Battousai. After receiving help from Kenshin, Kaoru allows him to stay at the dojo, and so the former assassin temporarily ceases his travels.

Rurouni Kenshin: Meiji Kenkaku Romantan tells the story of Kenshin as he strives to save those in need of saving. However, as enemies from both past and present begin to emerge, will the reformed killer be able to uphold his new ideals?

[Written by MAL Rewrite]', 94, 91, 'https://myanimelist.net/images/anime/1346/119505.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59150, 'Wu Liuqi: Jiyi Suipian', '伍六七之记忆碎片', 'ONA', 10, 'FINISHED', 8.27, 7674, 358, 5597, 'In order to find his cherished partner, Wu Liuqi returns to Xuanwu Country and faces those forgotten fragments of memory. The dusty truth brings pain and anger, but now he is no longer alone. What is the purpose of having power? This time, Wu Liuqi has to make a new choice for his life...

(Source: Official Site)', NULL, 86, 'https://myanimelist.net/images/anime/1787/151956.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (35111, 'Haikyuu!! Movie 4: Concept no Tatakai', 'ハイキュー!! コンセプトの戦い', 'UNKNOWN', 1, 'FINISHED', 8.27, 42670, 351, 2300, 'The long-awaited finals of the Spring Tournament have arrived for Karasuno High School''s volleyball team. The winner of the match will go on to represent all of Miyagi Prefecture at the National Tournament. However, the last challenge Karasuno must overcome is to win against Shiratorizawa Academy, the school that houses Wakatoshi Ushijima, one of Japan''s top three aces. Shiratorizawa is the reigning Miyagi champion for the past three years, and Karasuno seems to have little chance at dethroning them. 

When the other school''s captain Ushijima insults Karasuno to their faces, freshmen duo Shouyou Hinata and Tobio Kageyama swear to defeat them and steal their spot in the nationals. Against a roster full of nationally-ranked players, the former flightless crows will have to use everything in their arsenal if they want to represent Miyagi.

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/1854/147254.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (32188, 'Steins;Gate: Kyoukaimenjou no Missing Link - Divide By Zero', 'シュタインズ・ゲート境界面上のミッシングリンク-Divide By Zero-', 'UNKNOWN', 1, 'FINISHED', 8.27, 161776, 355, 970, 'Having reached his emotional breaking point, Rintarou Okabe refuses to continue aiding time traveler Suzuha Amane in her mission to prevent World War III, believing any further efforts to save Makise Kurisu will be in vain. Shortly after, Okabe abandons his mad scientist persona and becomes a seemingly regular university student. 

Okabe''s close friend Mayuri Shiina perceives him to be recovering from his trauma and is visibly happy. However, something still seems to be bothering Okabe. Steins;Gate: Kyoukaimenjou no Missing Link - Divide By Zero marks the beginning of a critical divergence—a timeline in which the burden of fate escalates beyond one''s limits.

[Written by MAL Rewrite]', NULL, 5, 'https://myanimelist.net/images/anime/7/77324.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (19363, 'Gin no Saji 2nd Season', '銀の匙', 'TV', 11, 'FINISHED', 8.27, 94846, 349, 1724, 'Now accustomed to his life at Ooezo Agricultural High School, Yuugo Hachiken explores the deeper aspects of what school life really means. As Hachiken learns more about himself and earns the skills necessary for his everyday tasks, he is even offered the position of the Equestrian Club''s vice-president. The new semester brings a variety of agricultural dilemmas and personal conflicts, but, nevertheless, Hachiken perseveres in order to discover his dream and continue working together with his friends.

[Written by MAL Rewrite]', 95, 13, 'https://myanimelist.net/images/anime/8/57995.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (23327, 'Space☆Dandy 2nd Season', 'スペース☆ダンディ 第2シリーズ', 'TV', 13, 'FINISHED', 8.27, 96205, 354, 1514, 'Second season of Space Dandy.

Space Dandy is a dandy guy, in space! This dreamy adventurer with a to-die-for pompadour travels across the galaxy in search of aliens no one has ever laid eyes on. Each new species he discovers earns him a hefty reward, but this dandy has to be quick on his feet because it''s first come, first served! Accompanied by his sidekicks, a rundown robot named QT and Meow the cat-looking space alien, Dandy bravely explores unknown worlds inhabited by a variety of aliens. Join the best dressed alien hunter in all of space and time as he embarks on an adventure that ends at the edge of the universe!

(Source: Bandai Visual)', 82, 3, 'https://myanimelist.net/images/anime/3/64451.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34798, 'Yuru Camp△', 'ゆるキャン△', 'TV', 12, 'FINISHED', 8.27, 239714, 359, 464, 'While the perfect getaway for most girls her age might be a fancy vacation with their loved ones, Rin Shima''s ideal way of spending her days off is camping alone at the base of Mount Fuji. From pitching her tent to gathering firewood, she has always done everything by herself, and has no plans of leaving her little solitary world.

However, what starts off as one of Rin''s usual camping sessions somehow ends up as a surprise get-together for two when the lost Nadeshiko Kagamihara is forced to take refuge at her campsite. Originally intending to see the picturesque view of Mount Fuji for herself, Nadeshiko''s plans are disrupted when she ends up falling asleep partway to her destination. Alone and with no other choice, she seeks help from the only other person nearby. Despite their hasty introductions, the two girls nevertheless enjoy the chilly night together, eating ramen and conversing while the campfire keeps them warm. And even after Nadeshiko''s sister finally picks her up later that night, both girls silently ponder the possibility of another camping trip together.

[Written by MAL Rewrite]', 24, 64, 'https://myanimelist.net/images/anime/4/89877.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (30346, 'Doukyuusei', '同級生', 'UNKNOWN', 1, 'FINISHED', 8.27, 158769, 348, 940, 'Hikaru Kusakabe is a normal, carefree boy in a rock band who is always focused on the present. During the summer, his entire class is forced to participate in an upcoming chorus festival. By coincidence, he discovers his classmate Rihito Sajou—known for being an honor student with excellent grades—practicing his singing alone. Sajou just cannot seem to get their class'' song right, and Kusakabe, delighted at seeing a new side of his straight-laced classmate, offers to help him prepare for the event.

Although their lives and personalities are total opposites, they begin to grow closer as time progresses. But with the pressure of an unknown future, what will become of them and their growing relationship?

[Written by MAL Rewrite]', NULL, 13, 'https://myanimelist.net/images/anime/3/78606.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2685, 'Tsubasa: Tokyo Revelations', 'ツバサ TOKYO REVELATIONS', 'OVA', 3, 'FINISHED', 8.27, 46982, 357, 2367, 'Continuing their journey from Record Country (the place that held the book of memories), Syaoran and company land into Tokyo Country, a blood-filled country under war from opposing factions for natural resources and survival. While reluctantly involved in the race to live, the group faces their own problems as certain revelations are made, changing their journey forever.

A shocking betrayal and a battle that risks all of their lives. After this revelation, they will never be the same again.', NULL, 23, 'https://myanimelist.net/images/anime/4/49129.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (9735, 'Gintama: Shinyaku Benizakura-hen', '銀魂 新訳紅桜篇', 'UNKNOWN', 1, 'FINISHED', 8.27, 21041, 350, 3695, 'It''s the running gag of Ben Johnson episode where animation staff reuse the New Years footage; Yorozuya would sit around the kotatsu eating a bowl of tangerines. They discuss elaborate subjects, Shinpachi complains about reusing animation footage, and then Gin-chan always ending the gag with a pointless announcement.', NULL, 9, 'https://myanimelist.net/images/anime/12/26966.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (43, 'Koukaku Kidoutai', 'GHOST IN THE SHELL（攻殻機動隊）', 'UNKNOWN', 1, 'FINISHED', 8.27, 361711, 352, 338, 'In the year 2029, Niihama City has become a technologically advanced metropolis. Due to great improvements in cybernetics, its citizens are able to replace their limbs with robotic parts. The world is now more interconnected than ever before, and the city''s Public Security Section 9 is responsible for combating corruption, terrorism, and other dangerous threats following this shift toward globalization.

The strong-willed Major Motoko Kusanagi of Section 9 spearheads a case involving a mysterious hacker known only as the "Puppet Master," who leaves a trail of victims stripped of their memories. Like many in this futuristic world, the Puppet Master''s body is almost entirely robotic, giving them incredible power.

As Motoko and her subordinates follow the enigmatic criminal''s trail, other parties—including Section 6—start to get involved, forcing her to confront the extremely complicated nature of the case. Pondering about various philosophical questions, such as her own life''s meaning, Motoko soon realizes that the one who will provide these answers is none other than the Puppet Master themself.

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/10/82594.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34036, 'Meitantei Conan: Episode One - Chiisaku Natta Meitantei', '名探偵コナン エピソードONE 小さくなった名探偵', 'UNKNOWN', 1, 'FINISHED', 8.27, 16717, 353, 4372, 'The "real" episode 1 of Meitantei Conan written by the Mangaka Gosho Aoyama.', NULL, 14, 'https://myanimelist.net/images/anime/5/81968.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38826, 'Tenki no Ko', '天気の子', 'UNKNOWN', 1, 'FINISHED', 8.27, 677905, 356, 156, 'Tokyo is currently experiencing rain showers that seem to disrupt the usual pace of everyone living there to no end. Amidst this seemingly eternal downpour arrives the runaway high school student Hodaka Morishima, who struggles to financially support himself—ending up with a job at a small-time publisher. At the same time, the orphaned Hina Amano also strives to find work to sustain herself and her younger brother.

Both fates intertwine when Hodaka attempts to rescue Hina from shady men, deciding to run away together. Subsequently, Hodaka discovers that Hina has a strange yet astounding power: the ability to call out the sun whenever she prays for it. With Tokyo''s unusual weather in mind, Hodaka sees the potential of this ability. He suggests that Hina should become a "sunshine girl"—someone who will clear the sky for people when they need it the most.

Things begin looking up for them at first. However, it is common knowledge that power always comes with a hefty price...

[Written by MAL Rewrite]', NULL, 20, 'https://myanimelist.net/images/anime/1880/101146.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (58572, 'Shangri-La Frontier: Kusoge Hunter, Kamige ni Idoman to su 2nd Season', 'シャングリラ・フロンティア～クソゲーハンター、神ゲーに挑まんとす～ 2nd season', 'TV', 25, 'FINISHED', 8.26, 131640, 370, 1072, 'Ever since Rakurou "Sunraku" Hizutome started to play the extremely popular virtual reality game Shangri-La Frontier, he has truly fallen in love with it. Sunraku has quickly made a big name for himself by fighting two of the seven unique, nearly unbeatable monsters, which is unthinkable for most players. To progress the game''s story, he sets out on an adventure with his leporine guide, Emul, to acquire a magic operation unit from an ancient workshop.

Though Sunraku breezes through this quest alongside his clanmates Towa "Arthur Pencilgon" Amane and Kei "OiKatzo" Uomi, there seems to be an ulterior motive as to why the two of them decided to help Sunraku in the first place. Nevertheless, Sunraku gains valuable knowledge and allies, critical for his advancement in the game. By seeking out powerful enemies and unraveling the inner workings of the game''s world, Sunraku may just change Shangri-La Frontier forever.

[Written by MAL Rewrite]', 36, 115, 'https://myanimelist.net/images/anime/1996/147601.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (53111, 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV: Shin Shou - Yakusai-hen', 'ダンジョンに出会いを求めるのは間違っているだろうかⅣ深章 厄災篇', 'TV', 11, 'FINISHED', 8.26, 156270, 362, 948, 'Second part of Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka IV.', 22, 58, 'https://myanimelist.net/images/anime/1476/128693.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37520, 'Dororo', 'どろろ', 'TV', 24, 'FINISHED', 8.26, 700035, 360, 109, 'The greedy samurai lord Daigo Kagemitsu''s land is dying, and he would do anything for power, even renounce Buddha and make a pact with demons. His prayers are answered by 12 demons who grant him the power he desires by aiding his prefecture''s growth, but at a price. When Kagemitsu''s first son is born, the boy has no limbs, no nose, no eyes, no ears, nor even skin—yet still, he lives.

This child is disposed of in a river and forgotten. But as luck would have it, he is saved by a medicine man who provides him with prosthetics and weapons, allowing for him to survive and fend for himself. The boy lives and grows, and although he cannot see, hear, or feel anything, he must defeat the demons that took him as sacrifice. With the death of each one, he regains a part of himself that is rightfully his. For many years he wanders alone, until one day an orphan boy, Dororo, befriends him. The unlikely pair of castaways now fight for their survival and humanity in an unforgiving, demon-infested world.

[Written by MAL Rewrite]', 26, 111, 'https://myanimelist.net/images/anime/1879/100467.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (40211, 'Luo Xiaohei Zhanji (Movie)', '罗小黑战记', 'UNKNOWN', 1, 'FINISHED', 8.26, 14071, 369, 3944, 'Luo Xiaohei is a young monster who normally takes the form of a small black cat. Living freely in the forests, gradual deforestation and human development force him to flee and find a new home. Wandering the city streets, the black cat struggles to survive until he encounters Feng Xi, a fellow monster who takes Xiaohei to an isolated island inhabited by a small group of monsters. Excited to find what he thinks is his new home, Xiaohei lives with the monsters for only a short time before Wuxian, a human Guild Executor, arrives on the island in pursuit of Feng Xi.

Feng Xi and his companions manage to teleport off the island, leaving Xiaohei and Wuxian alone. Though Xiaohei refuses to cooperate with the man who attacked his friends, Wuxian forces the black cat to travel to the Guild along with him. Embarking on an uncertain journey, Xiaohei is exposed to a new perspective on the relations between humans and monsters in a rapidly changing world.

[Written by MAL Rewrite]', NULL, 43, 'https://myanimelist.net/images/anime/1583/108598.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (25835, 'Shirobako', 'SHIROBAKO', 'TV', 24, 'FINISHED', 8.26, 149785, 371, 556, 'It all started in Kaminoyama High School, when five best friends—Aoi Miyamori, Ema Yasuhara, Midori Imai, Shizuka Sakaki, and Misa Toudou—discovered their collective love for all things anime and formed the animation club. After making their first amateur anime together and showcasing it at the culture festival, the group vows to pursue careers in the industry, aiming to one day work together and create their own mainstream show.

Two and a half years later, Aoi and Ema have managed to land jobs at the illustrious Musashino Animation production company. The others, however, are finding it difficult to get their dream jobs. Shizuka is feeling the weight of not being recognized as a capable voice actor, Misa has a secure yet unsatisfying career designing 3D models for a car company, and Midori is a university student intent on pursuing her dream as a story writer. These five girls will learn that the path to success is one with many diversions, but dreams can still be achieved through perseverance and a touch of eccentric creativity.

[Written by MAL Rewrite]', 37, 80, 'https://myanimelist.net/images/anime/1460/141897.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (3002, 'Gyakkyou Burai Kaiji: Ultimate Survivor', '逆境無頼カイジ Ultimate Survivor', 'TV', 26, 'FINISHED', 8.26, 178506, 364, 693, 'After one of his coworkers fails to repay a debt, apathetic bum Kaiji Itou is pressured by loan sharks to settle the large sum of cash. Since Kaiji has little money and no future prospects of his own, he is unable to return what his colleague borrowed. Faced with massive financial burdens, Kaiji is given an offer to board the illustrious Espoir—it is said that "one night aboard the ship, and all of your debts will be paid."

What seems like a simple night of gambling quickly turns into a game of strategy and betrayal. With the losers of the tournament being subjected to a backbreaking life of indebted servitude, Kaiji must choose his actions—and allies—carefully. However, this is only the beginning of a series of gambles that will wager Kaiji''s life, testing the full extent of his wits and will to survive.

[Written by MAL Rewrite]', 96, 1, 'https://myanimelist.net/images/anime/12/80032.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (513, 'Tenkuu no Shiro Laputa', '天空の城ラピュタ', 'UNKNOWN', 1, 'FINISHED', 8.26, 334894, 372, 468, 'In a world filled with planes and airships, Sheeta is a young girl who has been kidnapped by government agents who seek her mysterious crystal amulet. While trapped aboard an airship, she finds herself without hope—that is, until the ship is raided by pirates. Taking advantage of the ensuing confusion, Sheeta manages to flee from her captors. Upon her escape, she meets Pazu, a boy who dreams of reaching the fabled flying castle, Laputa. The two decide to embark on a journey together to discover this castle in the sky. However, they soon find the government agents back on their trail, as they too are trying to reach Laputa for their own greedy purposes.

Tenkuu no Shiro Laputa follows the soaring adventures of Sheeta and Pazu, all while they learn how dreams and dire circumstances can bring two people closer together.

[Written by MAL Rewrite]', NULL, 24, 'https://myanimelist.net/images/anime/5/37799.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (265, 'Hajime no Ippo: Mashiba vs. Kimura', 'はじめの一歩 間柴vs木村 死刑執行', 'OVA', 1, 'FINISHED', 8.26, 78294, 366, 2007, 'Tatsuya Kimura is beginning to feel left behind. With his friends Ippo Makunouchi and Mamoru Takamura holding the championship belt in their respective weight classes, Kimura''s inability to become Japan''s Junior Lightweight boxing champion eats away at him. Scheduled to fight with the current champion Ryo Mashiba, Kimura begins to train with Ippo''s rival Ichirou Miyata, who previously suffered a crushing defeat from Mashiba''s signature "Hitman" style of boxing.

But Mashiba has his own desire to hold onto the belt, hoping to soon shoot for the World title and secure financial stability for his sister Kumi. Will Kimura''s overwhelming drive to prove his strength as a boxer overcome Mashiba''s desperate wish to provide a better life for Kumi?

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/4/64737.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (264, 'Hajime no Ippo: Champion Road', 'はじめの一歩 -Champion Road-', 'UNKNOWN', 1, 'FINISHED', 8.26, 95068, 365, 1706, 'The challenger has become the champion as Ippo Makunouchi now wears the featherweight championship belt of Japan. 
Some time has passed since Ippo''s victory, and he has found his friends and coach as supportive as ever; his crush, Kumi Mashiba, seems to enjoy spending time with him as well. Things are looking bright for the new champion, but just as he once set his sights on becoming the best, his first challenger poses an intimidating threat. 

Kazuki Sanada works as a doctor at the same hospital as Kumi and fights strategically. Known for integrating his knowledge of the human body into his fights, Sanada is a fearsome contender—however, more unnerving than his physical ability, he has garnered the support of the nurses. Despite being the champion, Ippo feels the pressure as he must face the daunting challenge, retain his belt, and win over the girl he loves.

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/1521/137978.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38691, 'Dr. Stone', 'ドクターストーン', 'TV', 24, 'FINISHED', 8.26, 1178664, 361, 49, 'After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world—turning every single human into stone.

Several millennia later, Taiju awakens to find the modern world completely nonexistent, as nature has flourished in the years humanity stood still. Among a stone world of statues, Taiju encounters one other living human: his science-loving friend Senkuu, who has been active for a few months. Taiju learns that Senkuu has developed a grand scheme—to launch the complete revival of civilization with science. Taiju''s brawn and Senkuu''s brains combine to forge a formidable partnership, and they soon uncover a method to revive those petrified.

However, Senkuu''s master plan is threatened when his ideologies are challenged by those who awaken. All the while, the reason for mankind''s petrification remains unknown.

[Written by MAL Rewrite]', 27, 14, 'https://myanimelist.net/images/anime/1613/102576.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10087, 'Fate/Zero', 'フェイト/ゼロ', 'TV', 13, 'FINISHED', 8.26, 913600, 363, 83, 'With the promise of granting any wish, the omnipotent Holy Grail triggered three wars in the past, each too cruel and fierce to leave a victor. In spite of that, the wealthy Einzbern family is confident that the Fourth Holy Grail War will be different; namely, with a vessel of the Holy Grail now in their grasp. Solely for this reason, the much hated "Magus Killer" Kiritsugu Emiya is hired by the Einzberns, with marriage to their only daughter Irisviel as binding contract.

Kiritsugu now stands at the center of a cutthroat game of survival, facing off against six other participants, each armed with an ancient familiar, and fueled by unique desires and ideals. Accompanied by his own familiar, Saber, the notorious mercenary soon finds his greatest opponent in Kirei Kotomine, a priest who seeks salvation from the emptiness within himself in pursuit of Kiritsugu.

Based on the light novel written by Gen Urobuchi, Fate/Zero depicts the events of the Fourth Holy Grail War—10 years prior to Fate/stay night. Witness a battle royale in which no one is guaranteed to survive.

[Written by MAL Rewrite]', 6, 35, 'https://myanimelist.net/images/anime/1887/117644.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (139, 'Hunter x Hunter: Greed Island Final', 'HUNTER×HUNTER G・I Final', 'OVA', 14, 'FINISHED', 8.26, 83969, 368, 1707, 'Continuing with their adventure at Greed Island, Gon and Killua train furiously under the guidance of Biscuit for better preparation at attempting the game. With their abilities vastly improving and the threat of player killers menacing Greed Island, Gon and company continue the game despite the dangers that they will face with the game activities and encounters with other players. Based on the manga by Togashi Yoshihiro.', NULL, 73, 'https://myanimelist.net/images/anime/1/139.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10408, 'Hotarubi no Mori e', '蛍火の杜へ', 'UNKNOWN', 1, 'FINISHED', 8.26, 487444, 367, 242, 'During a summer vacation at her grandfather’s house, six-year-old Hotaru Takegawa gets lost in a forest rumored to be inhabited by spirits. While crying out in desperation, Hotaru is approached by Gin—a mysterious boy wearing a mask—who offers to help her.

Overjoyed at the sight of another person, Hotaru runs to Gin with open arms only to be rudely fended off. However, she quickly learns the grave reason behind his behavior: a dreadful curse has been cast upon Gin. Should he ever be touched by a human being, he will disappear forever.

Though Gin urges her to never return, Hotaru does the exact opposite, and before too long, the two become close friends despite his delicate situation. Nonetheless, as years pass and their mutual feelings grow stronger, Hotaru and Gin start struggling with the boundaries that destiny has set between them.

[Written by MAL Rewrite]', NULL, 44, 'https://myanimelist.net/images/anime/1599/112267.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (62927, 'Fangkai Nage Nuwu', '放开那个女巫', 'ONA', 8, 'FINISHED', 8.25, 7033, 375, 5449, 'Modern man Cheng Yan unexpectedly dies and his soul travels to a medieval European-style otherworldly continent, becoming Roland, the fourth prince of the Kingdom of Graycastle. This playboy prince saves the witch Anna at an execution scene and is shocked to discover that magic really exists in this medieval-style otherworld.

When Anna, as a witch, displays her magical skills, Roland realizes that magic can replace some modern technology, so he formulates a "great development of magical industry" plan. Thus, in an era where everyone hates witches, the independent Roland begins to recruit witches, using their magic to transform Border Town and improve the lives of himself and the locals.

In addition to using magic to develop industry, Roland also introduces modern business ideas to Border Town. Under Roland''s leadership, people manufacture firearms, and Roland gains public support. As the number of witches in Roland''s camp increases, the magical industry continues to improve. At the same time, Roland will face battles with great families and other princes and princesses.

As his territory expands, Roland successfully creates a harmonious coexistence between witches and ordinary people, gradually bringing the western territory of Graycastle and even the entire kingdom under his rule, and slowly uncovering the secrets of the devil race and the Witch Empire.

(Source: Crunchyroll)', NULL, 116, 'https://myanimelist.net/images/anime/1381/153536.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (60570, 'Ling Long 2nd Season', '灵笼 第二季', 'ONA', 12, 'FINISHED', 8.25, 602, 380, 13342, 'In this thrilling continuation, former Wilderness Hunter Commander Marc has transformed into a blood-stained monster who destroys lighthouses. Guided by the enigmatic Bai Yuekui, he embarks on a new mission. The arrival of survivors on the ground reveals that the lighthouse isn''t humanity''s final refuge. Facing adversity, they harness their innate abilities to combat the Mana ecosystem. Bai Yuekui''s past intricately links to Mark''s origins and the apocalypse''s truth.

Meanwhile, the colossal brain on the lighthouse awakens, the old shadows linger, and a new crisis emerges. As unprecedented disasters loom, where will the two human factions ultimately head?

(Source: Bilibili YouTube Channel)', NULL, 117, 'https://myanimelist.net/images/anime/1980/150040.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (57592, 'Dr. Stone: Science Future', 'Dr.STONE SCIENCE FUTURE', 'TV', 12, 'FINISHED', 8.25, 147738, 374, 921, 'Having resolved the crisis in the Petrification Kingdom, Senkuu and his companions gear up to deal directly with the mastermind behind the petrification phenomenon—who supposedly resides on the moon. The ambitious spaceship project, however, requires immense manpower and critical resources scattered across the world. Thus, the Kingdom of Science exploration team kick-starts its transcontinental journey on the ship Perseus to gather them all.

Equipped with modern technology and bolstered by the new, capable members in their ranks, the exploration team feels confident about setting sail to their first destination: America. They soon realize that the region now hosts adversaries controlling the resources they need, doing so with scientific technology which rivals and even exceeds their own. In a battle of science versus science, Senkuu and his team must outsmart their rivals if they are to have any chance of ensuring the continued survival and rejuvenation of humanity.

[Written by MAL Rewrite]', 16, 14, 'https://myanimelist.net/images/anime/1403/146479.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (54959, 'BanG Dream! It''s MyGO!!!!!', 'バンドリ！It''s MyGO!!!!!', 'TV', 13, 'FINISHED', 8.25, 20792, 373, 3951, 'In their last year of middle school, the five band members of CRYCHIC went their separate ways after an unpleasant disbandment. Each wrestling with their own regrets, the girls enrolled in different high schools, hoping never to hear from one another again.

Meanwhile, Anon Chihaya transfers to Haneoka Girls'' Academy in the middle of the school year. As most students play in a band as a hobby, Anon desires to fit in and spends her first days trying to recruit members for her own band, envisioning herself as the group''s vocalist. She befriends Tomori Takamatsu, a shy girl who seems interested but hesitant about joining. As it turns out, Tomori used to be part of CRYCHIC, an experience that has scarred her deeply.

Through Tomori, Anon meets Taki Shiina and Soyo Nagasaki, both former members of the same band. Although Taki detests the idea of playing with Anon, Soyo is delighted to help her out. Now with Soyo by her side, Anon''s dream of forming a band is within reach—if only she could find a few more members.

[Written by MAL Rewrite]', 41, 118, 'https://myanimelist.net/images/anime/1891/136948.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (54595, 'Kage no Jitsuryokusha ni Naritakute! 2nd Season', '陰の実力者になりたくて！ 2nd Season', 'TV', 12, 'FINISHED', 8.25, 298605, 378, 473, 'Enticed by its rumored wealth, Cid Kagenou happily tags along with his sister, Claire, on a trip to the infamous Lawless City. The region is ruled by three monarchs: Yukime, the Spirit Fox; Juggernaut, the Tyrant; and Elisabeth, a dormant progenitor vampire known as the Blood Queen. Hunting Elisabeth down serves as the perfect opportunity for Claire to prove her true mettle. On the other hand, Cid has different objectives—sneaking away from Claire''s sight, collecting as much loot as possible, and making Shadow''s glorious entrance at the perfect moment.

As Elisabeth''s awakening draws near, her subordinate Crimson enacts a treacherous plot, sending the town into a frenzy. Searching for her now-missing brother, Claire finds an unexpected ally in Mary, a vampire hunter, and the pair hurry to the Crimson Tower—the home of the Blood Queen. Meanwhile, Beta and a small team of Shadow Garden recruits also arrive at the Lawless City. As the key players converge on the Crimson Tower, the stage is set for a grand confrontation under the crimson moon.

[Written by MAL Rewrite]', 1, 119, 'https://myanimelist.net/images/anime/1938/138295.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10271, 'Gyakkyou Burai Kaiji: Hakairoku-hen', '逆境無頼カイジ 破戒録篇', 'TV', 26, 'FINISHED', 8.25, 117748, 376, 1306, 'Owing to an increasing debt, Kaiji Itou ends up resuming his old lifestyle. One day, while walking on the street, he stumbles upon Yuuji Endou, who is hunting Kaiji due to the money he owes to the Teiai Group. Unaware of this, Kaiji eagerly follows Endou, hoping for a chance to participate in another gamble, but soon finds out the loan shark''s real intentions when he is kidnapped.

Given that Kaiji is unable to pay off his huge debt, the Teiai Group instead sends him to work in an underground labor camp. He is told that he will have to live in this hell for 15 years, alongside other debtors, until he can earn his freedom. His only hope to put an early end to this nightmare is by saving enough money to be able to go back to the surface for a single day. Once he is there, he plans to obtain the remaining money needed to settle his account by making a high-stakes wager. However, as many temptations threaten his scarce income, Kaiji may have to resort to gambling sooner than he had expected.

[Written by MAL Rewrite]', 3, 1, 'https://myanimelist.net/images/anime/10/30599.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (36990, 'Non Non Biyori Movie: Vacation', '劇場版 のんのんびより ばけーしょん', 'UNKNOWN', 1, 'FINISHED', 8.25, 41434, 382, 2616, 'With summer vacation coming to an end, the girls are having as much fun as they can with their remaining time. However, their daily shenanigans are cut short when Suguru Koshigaya wins the grand prize of a lottery—tickets to Okinawa! After hasty preparations, the Asahigaoka group embarks on a three-day trip for their final summer getaway.

Upon arriving in Okinawa and checking into an inn, the group comes across Aoi Niizato—the young daughter of the inn''s hostess. Despite being of similar age, her mature demeanor leaves Natsumi Koshigaya reflecting upon her own childish nature. With the sign of an unexpected friendship blooming on the horizon, the girls waste no time diving into their ambitious sightseeing plans and regional activities!

[Written by MAL Rewrite]', NULL, 88, 'https://myanimelist.net/images/anime/1044/93575.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (44940, 'World Trigger 3rd Season', 'ワールドトリガー', 'TV', 14, 'FINISHED', 8.25, 55413, 388, 1861, 'At the Border Defense Agency''s headquarters, the B-Rank Wars are underway as each team fights intensely to secure a spot in the upcoming Away Mission. Though Osamu Mikumo and the rest of Tamakoma-2 have pulled through thus far, the final rounds will require them to push far beyond the limits of their current abilities. Taking in a talented new member, the squad begins to train and develop new strategies, but, amid these efforts, the team is shaken by a heated dispute—one that could jeopardize their ticket to the Neighbor''s dimension.

[Written by MAL Rewrite]', 38, 8, 'https://myanimelist.net/images/anime/1617/117474.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1698, 'Nodame Cantabile', 'のだめカンタービレ', 'TV', 23, 'FINISHED', 8.25, 134643, 381, 843, 'Shinichi Chiaki is a first class musician whose dream is to play among the elites in Europe. Coming from a distinguished family, he is an infamous perfectionist—not only is he highly critical of himself, but of others as well. The only thing stopping Shinichi from leaving for Europe is his fear of flying. As a result, he''s grounded in Japan.

During his fourth year at Japan''s top music university, Shinichi happens to meet Megumi Noda or, as she refers to herself, Nodame. On the surface, she seems to be an unkempt girl with no direction in life. However, when Shinichi hears Nodame play the piano for the first time, he is in awe of the kind of music she creates. Nevertheless, Shinichi is dismayed to discover that Nodame is his neighbor, and worse, she ends up falling head over heels in love with him.

[Written by MAL Rewrite]', 92, 58, 'https://myanimelist.net/images/anime/9/11986.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1033, 'Sennen Joyuu', '千年女優', 'UNKNOWN', 1, 'FINISHED', 8.25, 95498, 385, 1322, 'At the turn of the millennium, Ginei Studio''s dilapidated buildings are set to be demolished. Ex-employee and filmmaker Genya Tachibana decides to honor this occasion with a commemorative documentary about the company''s star actress: Chiyoko Fujiwara, the reclusive sweetheart of Shouwa Era cinema. Having finally obtained permission to interview the retired starlet, an enamored Genya drags along cynical cameraman Kyouji Ida to meet her, ready to put his lifelong idol back in the spotlight once more.

Hidden in this secluded mountain retreat is a thousand years of history condensed into one lifetime, waiting to be narrated. Chiyoko''s recollections take them on an illusionary journey through Japanese cinematic history that transcends the boundaries of reality; the saga of her acting career intertwines with her filmography, the actors in her life blend seamlessly with the characters on screen, and the present melds with the past. Though the actress may have retired at the height of her career 30 years ago, the curtain on her life''s stage has yet to fall.

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/1648/93626.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (523, 'Tonari no Totoro', 'となりのトトロ', 'UNKNOWN', 1, 'FINISHED', 8.25, 756360, 387, 145, 'In 1950s Japan, Tatsuo Kusakabe relocates himself and his two daughters, Satsuki and Mei, to the countryside to be closer to their mother, who is hospitalized due to long-term illness. As the girls grow acquainted with rural life, Mei encounters a small, bunny-like creature in the yard one day. Chasing it into the forest, she finds "Totoro"—a giant, mystical forest spirit whom she soon befriends. Before long, Satsuki too meets Totoro, and the two girls suddenly find their lives filled with magical adventures in nature and fantastical creatures of the woods.

[Written by MAL Rewrite]', NULL, 24, 'https://myanimelist.net/images/anime/1110/147278.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (440, 'Shoujo Kakumei Utena', '少女革命ウテナ', 'TV', 39, 'FINISHED', 8.25, 72175, 386, 1138, 'Years ago, a tragic incident befell a young princess when both her parents died. Devastated, it seemed nothing would calm this poor soul. However, a prince traveling through the area came to see the princess, hoping to cheer her up. After wiping her sorrowful tears, the prince gave her a ring carrying a rose emblem and told her as long as she holds onto the ring, they are destined to meet again. The event leaves a deep impression on the girl, Utena Tenjou, leading her to become a prince herself. 

Years later, Utena attends Ootori Academy, recognized by the same rose emblem as her precious ring''s. There, attracted by the scent of roses, she witnesses Anthy Himemiya tending the flowers, accompanied by the Student Council President Touga Kiryuu and Vice President Kyouichi Saionji, who seem to be arguing over Anthy. While Utena thinks nothing of the occurrence, the Student Council gathers to discuss an important matter. 

Subsequently, a misunderstanding leads to Utena being dragged into the world of Duelists—those with rings similar to her own. The Duelists fight for the ownership of the Rose Bride, Anthy Himemiya, who is said to possess great power. Wanting to prove her capabilities as a prince, and enraged that Anthy is being wronged and objectified, Utena resolves to fight against the Duelists to save her from the cruel fate.

[Written by MAL Rewrite]', 97, 58, 'https://myanimelist.net/images/anime/1078/95285.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (31812, 'Kuroshitsuji Movie: Book of the Atlantic', '劇場版 黒執事 Book of the Atlantic', 'UNKNOWN', 1, 'FINISHED', 8.25, 105216, 379, 1243, 'The young Earl Ciel Phantomhive—the Queen''s Guard Dog—is once again called to investigate seemingly supernatural phenomena when news of miraculous resurrections begins to surface in Victorian London. Along with Sebastian Michaelis, his demon butler, they board the luxury cruise liner Campania to investigate rumors of the Aurora Society—a medical organization suspected of experimenting on the dead.

Grim reapers begin to appear on the ship, and it becomes apparent that the ship is about to be overrun with the undead as a devious plan is put into motion. Ciel and Sebastian must now uncover the secrets that lie behind the Aurora Society''s phoenix symbol, and with the help of some old acquaintances, return the undead to their coffins or share a watery grave.

[Written by MAL Rewrite]', NULL, 13, 'https://myanimelist.net/images/anime/9/85792.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (329, 'Planetes', 'プラネテス', 'TV', 26, 'FINISHED', 8.25, 83317, 383, 1000, 'In 2075, space travel is no longer just a dream, but an everyday reality for mankind. Advancements in science and technology have led to the colonization of the moon, the commercialization of outer space, and the formation of large space corporations. Ai Tanabe, an upbeat woman whose interests lie in the cosmos, joins Technora Corporation as a member of their Debris Section, a department dedicated to the removal of dangerous space junk between the orbits of the Earth and Moon.

However, Ai soon discovers how unappreciated her job is. As the laughingstock of Technora, the Debris Section is severely understaffed, poorly funded, and is forced to use a dilapidated spaceship nicknamed the "Toy Box" for debris retrieval. Undeterred, Ai perseveres and gradually becomes acquainted with the strange personalities that make up the Debris Section''s staff, such as the bumbling but good-natured chief clerk Philippe Myers; the mysterious and tight-lipped temp worker Edelgard Rivera; and the hotheaded and passionate Hachirouta Hoshino, who longs for a spaceship to call his own.

Planetes is an unconventional sci-fi series that portrays the vastness of space as a backdrop for the personal lives of ordinary people—people who may have been born on Earth, but whose hopes and dreams lie amongst the stars.

[Written by MAL Rewrite]', 98, 9, 'https://myanimelist.net/images/anime/1209/142900.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (45577, 'IDOLiSH7 Third Beat!', 'アイドリッシュセブン Third BEAT!', 'TV', 13, 'FINISHED', 8.25, 9337, 377, 4894, 'Nearing their first debut anniversary and with their popularity still on the rise, IDOLiSH7 set a date for a live tour to express their gratitude toward their fans. Meanwhile, the Black or White event draws closer—and as the previous year''s winners—the group must prepare to take on the challengers. Looking to solidify their reputation in the world of idols, IDOLiSH7 are determined to come out victorious and settle the score once and for all with their rival, TRIGGER.

While working around their packed schedules, IDOLiSH7, TRIGGER, and Re:vale meet powerful figures in the entertainment industry. In the midst of the hectic period, some members catch wind of a scandalous rumor regarding IDOLiSH7. As the members of IDOLiSH7 begin to worry about their image, their bonds are put to the test, all while a spiteful figure begins to carry out a certain plan behind the scenes.

[Written by MAL Rewrite]', 90, 89, 'https://myanimelist.net/images/anime/1646/115723.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (31240, 'Re:Zero kara Hajimeru Isekai Seikatsu', 'Re:ゼロから始める異世界生活', 'TV', 25, 'FINISHED', 8.25, 1564652, 384, 23, 'When Subaru Natsuki leaves the convenience store, the last thing he expects is to be wrenched from his everyday life and dropped into a fantasy world. Things are not looking good for the bewildered teenager; however, not long after his arrival, he is attacked by some thugs. Armed with only a bag of groceries and a now useless cell phone, he is quickly beaten to a pulp. Fortunately, a mysterious beauty named Satella, in hot pursuit after the one who stole her insignia, happens upon Subaru and saves him. In order to thank the honest and kindhearted girl, Subaru offers to help in her search, and later that night, he even finds the whereabouts of that which she seeks. But unbeknownst to them, a much darker force stalks the pair from the shadows, and just minutes after locating the insignia, Subaru and Satella are brutally murdered.

However, Subaru immediately reawakens to a familiar scene—confronted by the same group of thugs, meeting Satella all over again—the enigma deepens as history inexplicably repeats itself.

[Written by MAL Rewrite]', 68, 5, 'https://myanimelist.net/images/anime/1522/128039.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37989, 'Golden Kamuy 2nd Season', 'ゴールデンカムイ', 'TV', 12, 'FINISHED', 8.24, 130034, 389, 1184, 'In Hokkaido, it is rumored that there is a stash of hidden gold. This gold was supposedly stolen by a man who killed the original Ainu owners; and before being captured and imprisoned by the police, he hid it in a secret location. In order to relay the gold''s location to his comrades on the outside, he tattooed the map on the bodies of his cellmates and promised them a share of the gold—provided they managed to escape and find it.

First Lieutenant Tokushirou Tsurumi plans to give the 7th Division an advantage in the war for the tattoos by getting a taxidermist to create skins that only he can distinguish as fake. Meanwhile, Saichi Sugimoto, Asirpa, and their companions continue their hunt for the skins by following a strange rumor: a thief who broke into a home in Yubari found taxidermied human corpses, among which was a torso with strange tattoos.

[Written by MAL Rewrite]', 55, 74, 'https://myanimelist.net/images/anime/1180/95018.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (29831, 'Tamayura: Sotsugyou Shashin Part 4 - Ashita', 'たまゆら～卒業写真～ 第4部 朝-あした-', 'UNKNOWN', 1, 'FINISHED', 8.24, 4650, 399, 6311, 'The final movie of a four-part finale of Tamayura.', NULL, 120, 'https://myanimelist.net/images/anime/1697/134884.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (35677, 'Liz to Aoi Tori', 'リズと青い鳥', 'UNKNOWN', 1, 'FINISHED', 8.24, 67011, 393, 1663, 'Liz''s days of solitude come to an end when she meets a blue bird in the form of a young girl. Although their relationship blossoms, Liz must make a heart-wrenching decision in order to truly realize her love for Blue Bird.

High school seniors and close friends Mizore Yoroizuka and Nozomi Kasaki are tasked to play the lead instruments in the third movement of Liz and the Blue Bird, a concert band piece inspired by this fairy tale. The introverted and reserved Mizore plays the oboe, representing the kind and gentle Liz. Meanwhile, the radiant and popular Nozomi plays the flute, portraying the cheerful and energetic Blue Bird.

However, as they rehearse, the distance between Mizore and Nozomi seems to grow. Their disjointed duet disappoints the band, and with graduation on the horizon, uncertainty about the future spurs complicated emotions. With little time to improve as their performance draws near, they desperately attempt to connect with their respective characters. But when Mizore and Nozomi consider the story from a brand-new perspective, will the girls find the strength to face harsh realities?

A spin-off film adaptation of the Hibike Euphonium! series, Liz to Aoi Tori dances between the parallels of a charming fairy tale, a moving musical piece, and a delicate high school friendship.

[Written by MAL Rewrite]', NULL, 15, 'https://myanimelist.net/images/anime/1638/93032.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (15227, 'Kono Sekai no Katasumi ni', 'この世界の片隅に', 'UNKNOWN', 1, 'FINISHED', 8.24, 84744, 391, 1336, 'Suzu Urano is a pure and kindhearted girl who loves to draw and keep her head in the clouds. Growing up in the outskirts of Hiroshima with her family, she is more than happy to help with her grandmother''s nori business.

However, when she becomes of age, Suzu leaves her beloved home to marry Shuusaku Houjou, a man she barely knows. As she integrates into her new husband''s household, the homesick bride struggles to adjust to the unfamiliar environment as the war effort extends far beyond its point of no return. When the war reaches Suzu''s own backyard and peace gives way to brutality, how will she support herself and those she comes to love along the way?

Kono Sekai no Katasumi ni paints a colorful yet haunting depiction of everyday life in the years before and after World War II, showcasing the perseverance and fortitude of ordinary Japanese during one of the darkest periods of modern history.

[Written by MAL Rewrite]', NULL, 4, 'https://myanimelist.net/images/anime/2/87704.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (25681, 'Kamisama Hajimemashita◎', '神様はじめました◎', 'TV', 12, 'FINISHED', 8.24, 249666, 390, 558, 'Nanami Momozono and her familiars Tomoe and Mizuki have survived quite a few challenges since Nanami took up the mantle of Mikage Shrine''s patron god. Naturally, the wind god Otohiko comes to invite Nanami to the Divine Assembly in Izumo, the home of the gods, and Nanami chooses to take Mizuki with her, leaving Tomoe to pose as her at school. However, she has an ulterior motive for attending the Divine Assembly: to discover the whereabouts of the missing Lord Mikage, the former god of the shrine. 

After her adventures in Izumo, Nanami meets Botanmaru, a tengu child looking for someone she knows all too well—tengu turned goth idol Shinjirou Kurama. Botanmaru needs Shinjirou, their prince, to return home to Mount Kurama and stop the tyranny of Jirou, who has taken over the rule of their hometown. However, Nanami soon discovers a force much darker than Jirou is at work on the mountain.

As a fledgling god becoming more accustomed to divinity, Nanami finds herself dealing with a tengu rebellion, her blooming feelings for Tomoe, and a strange man with ties to both Tomoe''s past and Nanami''s future.

[Written by MAL Rewrite]', 73, 14, 'https://myanimelist.net/images/anime/8/69187.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (13125, 'Shinsekai yori', '新世界より', 'TV', 25, 'FINISHED', 8.24, 289653, 395, 271, 'In the year 2011, a small percentage of humans began manifesting psychokinetic abilities known as "Cantus." Over a millennium later, in the small town of Kamisu 66, Saki Watanabe is the last of her friends to awaken her powers and join the Sage Academy, a school for psychics like her. Although everyone at the institution has Cantus, they are not all equal; shortly after Saki enrolls, one of her classmates who is regarded as being weaker than the others suddenly disappears.

Walking home one day with her friends—the determined Maria Akizuki, the intelligent Shun Aonuma, the observant Satoru Asahina, and the timid Mamoru Itou—she comes across two unfamiliar creatures known as "Monster Rats." These beings resemble moles and worship those with Cantus as gods. As a result, when Saki uses her abilities to save one from trouble, she is met with exceptional gratitude.

Now unsure about the Monster Rats'' place in society, Saki and her friends find out about another disappearance. As time passes, they slowly look for answers to the mysteries that surround them and begin to realize that this seemingly "perfect" new world masks humanity''s dark past.

[Written by MAL Rewrite]', 7, 13, 'https://myanimelist.net/images/anime/1549/136389.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2418, 'Stranger: Mukou Hadan', 'ストレンヂア -無皇刃譚-', 'UNKNOWN', 1, 'FINISHED', 8.24, 172556, 397, 775, 'In the Sengoku period of Japan, a young orphan named Kotarou and his dog Tobimaru steal from unsuspecting villagers in order to make ends meet. However, Kotarou is forced to remain on the run when he finds himself being hunted down by assassins sent by China''s Ming Dynasty for mysterious reasons not involving his petty crimes. 

Fortunately, the duo run into Nanashi, a ronin who has taken refuge in a small temple, when Kotarou is attacked and Tobimaru poisoned. Although the samurai  saves the helpless pair from their pursuers, he feels that there is no need to help them further; but when offered a gem in exchange for his services as a bodyguard, he reluctantly accepts Kotarou''s offer of employment—just until Tobimaru is healed and the two reach their destination. As the three set out on a perilous journey, it soon becomes evident that their path is riddled with danger, as the Ming Dynasty has now sent a terrifying swordsman after them to capture Kotarou and fulfill a certain prophecy.

[Written by MAL Rewrite]', NULL, 3, 'https://myanimelist.net/images/anime/9/87066.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (32937, 'Kono Subarashii Sekai ni Shukufuku wo! 2', 'この素晴らしい世界に祝福を！ 2', 'TV', 10, 'FINISHED', 8.24, 1092025, 392, 76, 'When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then.

Not only is he stuck with a useless deity turned party archpriest, the pair also has to make enough money for living expenses. To add to their problems, their group continued to grow as more problematic adventurers joined their ranks. Their token spellcaster, Megumin, is an explosion magic specialist who can only cast one spell once per day and refuses to learn anything else. There is also their stalwart crusader, Lalatina Ford "Darkness" Dustiness, a helpless masochist who makes Kazuma look pure in comparison.

Kono Subarashii Sekai ni Shukufuku wo! 2 continues to follow Kazuma and the rest of his party through countless more adventures as they struggle to earn money and have to deal with one another''s problematic personalities. However, things rarely go as planned, and they are often sidetracked by their own idiotic tendencies.

[Written by MAL Rewrite]', 8, 32, 'https://myanimelist.net/images/anime/2/83188.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (512, 'Majo no Takkyuubin', '魔女の宅急便', 'UNKNOWN', 1, 'FINISHED', 8.24, 429139, 394, 369, 'Kiki, a 13-year-old witch-in-training, must spend a year living on her own in a distant town in order to become a full-fledged witch. Leaving her family and friends, Kiki undertakes this tradition when she flies out into the open world atop her broomstick with her black cat Jiji.

As she settles down in the coastal town of Koriko, Kiki struggles to adapt and ends up wandering the streets with no place to stay—until she encounters Osono, who offers Kiki boarding in exchange for making deliveries for her small bakery. Before long, Kiki decides to open her own courier service by broomstick, beginning her journey to independence. In attempting to find her place among the townsfolk, Kiki brings with her exciting new experiences and comes to understand the true meaning of responsibility.

[Written by MAL Rewrite]', NULL, 24, 'https://myanimelist.net/images/anime/1579/140483.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (50594, 'Suzume no Tojimari', 'すずめの戸締まり', 'UNKNOWN', 1, 'FINISHED', 8.24, 279358, 398, 515, 'On her way to school one day, Suzume Iwato stumbles upon Souta Munakata, a young man searching for abandoned areas. The high school girl directs Souta to a nearby ruin, but out of pure curiosity, she herself decides to head to the same destination.

Once there, Suzume discovers an isolated door with a dreamlike universe lying beyond it—a place that she can see and feel, but not enter. A strange stone rests on the ground nearby, but it turns into a cat-like creature and scurries away when Suzume lifts it. Suddenly afraid, she heads back toward her school, not realizing that her act of leaving the door open will have consequences.

With the "keystone" released, the evil within the other universe can now freely escape and wreak havoc throughout Japan. Intending to correct her dangerous mistake, Suzume joins Souta—whose true goal is to prevent evil from festering—in finding and locking all open doors before the country is destroyed.

[Written by MAL Rewrite]', NULL, 20, 'https://myanimelist.net/images/anime/1598/128450.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (35838, 'Shoujo Shuumatsu Ryokou', '少女終末旅行', 'TV', 12, 'FINISHED', 8.24, 151775, 396, 675, 'Amid the desolate remains of a once-thriving city, only the rumbling of a motorbike breaks the cold winter silence. Its riders, Chito and Yuuri, are the last survivors in the war-torn city. Scavenging old military sites for food and parts, the two girls explore the wastelands and speculate about the old world to pass the time. Chito and Yuuri each occasionally struggle with the looming solitude, but when they have each other, sharing the weight of being two of the last humans becomes a bit more bearable. Between Yuuri''s clumsy excitement and Chito''s calm composure, their dark days get a little brighter with shooting practice, new books, and snowball fights on the frozen battlefield. 

Among a scenery of barren landscapes and deserted buildings, Shoujo Shuumatsu Ryokou tells the uplifting tale of two girls and their quest to find hope in a bleak and dying world.

[Written by MAL Rewrite]', 18, 5, 'https://myanimelist.net/images/anime/12/88321.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (56215, 'Yi Nian Yong Heng 3rd Season', '一念永恒 第3季', 'ONA', 59, 'FINISHED', 8.23, 1370, 409, 10102, 'After Bai Xiaochun merged the four downstream sects to form the Reverse River Sect, he successfully challenged the three midstream sects and established a firm foothold. He was then chosen by the Celestial Being of the Starry Sky Dao Sect in the upstream to be a hostage, thus beginning the third season, the Hostage arc.

(Source: Tencent, translated)', NULL, 50, 'https://myanimelist.net/images/anime/1105/150044.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (54029, 'Wu Liuqi: Anying Suming', '伍六七之暗影宿命', 'ONA', 10, 'FINISHED', 8.23, 20622, 408, 4059, 'The protagonist Wu Liuqi originally lived a carefree life on Xiaoji Island, but his identity became a mystery due to amnesia. As outsiders landed on the island and recognized Wu Liuqi, various conspiracies began to cover Xiaoji Island. So Wu Liuqi decided to return to Xuanwu Kingdom to meet his destiny in order to protect his partners and their homeland. 

(Source: Bilibili, translated)', NULL, 86, 'https://myanimelist.net/images/anime/1016/153863.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37055, 'Youjo Senki Movie', '劇場版 幼女戦記', 'UNKNOWN', 1, 'FINISHED', 8.23, 175386, 410, 852, 'With its armies sweeping across the continent, the Empire seems unstoppable. After securing victory over the remnants of the Republic''s army, the Empire''s ultimate victory is finally within reach. However, dark clouds are gathering in the East. The communist-led Russy Federation is mustering troops on its western border, preparing to enter the war. Supported by a detachment of Allied volunteer magicians—among whom is Mary Sioux, the daughter of a soldier killed by Tanya von Degurechaff—the Federation is determined to spread the communist creed and bring the Empire to its knees.

Meanwhile, Tanya and her battalion return to the imperial capital from the southern front. Upon their arrival, they are tasked with investigating troop movements on the border with the Federation. Any escalation of violence at this point may lead to new conflicts, plunging the world into a devastating global war.

Will the Empire eventually emerge victorious from its struggle, or will it crumble in the face of superior enemies and radically different ideologies?

[Written by MAL Rewrite]', NULL, 79, 'https://myanimelist.net/images/anime/1249/117182.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (40853, 'Stand By Me Doraemon 2', 'STAND BY ME ドラえもん ２', 'UNKNOWN', 1, 'FINISHED', 8.23, 18673, 407, 3957, 'After reminiscing about his late grandmother, Nobita Nobi wishes to see her again and asks Doraemon to return them to the past. Following the wholesome reunion of the two, Nobita''s grandmother confesses that she hopes to meet his future bride. Nobita accepts her request out of filial love and quickly scrambles into the time machine as he and Doraemon journey forward in time.

However, when the duo warps to Nobita''s wedding day, they discover that the future Nobita is missing from the ceremony! Determined to set things right, Doraemon and Nobita embark on a mission to search for Nobita''s future self and encourage him to discover the happiness he deserves.

[Written by MAL Rewrite]', NULL, 121, 'https://myanimelist.net/images/anime/1842/109657.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (33051, 'Kidou Senshi Gundam: Tekketsu no Orphans 2nd Season', '機動戦士ガンダム 鉄血のオルフェンズ 第2期', 'TV', 25, 'FINISHED', 8.23, 90204, 401, 1676, 'Tekkadan has now become a direct affiliate of Teiwaz after procuring a new trade agreement with Arbrau. With its newfound funds and prestige, Tekkadan finds both its list of allies and enemies growing. Meanwhile, the flames of the Gjallarhorn power struggle continue to rage in full force. As a part of her efforts to make Mars financially independent from Earth, Kudelia Aina Bernstein founds the Admoss Company and enlists Tekkadan as her business partner. 

The stakes are getting higher as the Tekkadan family continues to grow. Will Orga, Mikazuki, and the rest of the Tekkadan faction be able to keep up, or will Kudelia''s dream of Martian independence die out?

[Written by MAL Rewrite]', 29, 9, 'https://myanimelist.net/images/anime/6/80899.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (11843, 'Danshi Koukousei no Nichijou', '男子高校生の日常', 'TV', 12, 'FINISHED', 8.23, 442106, 400, 239, 'Roaming the halls of the all-boys Sanada North High School are three close comrades: the eccentric ringleader with a hyperactive imagination Hidenori, the passionate Yoshitake, and the rational and prudent Tadakuni. Their lives are filled with giant robots, true love, and intense drama... in their colorful imaginations, at least. In reality, they are just an everyday trio of ordinary guys trying to pass the time, but who said everyday life couldn''t be interesting? Whether it''s an intricate RPG reenactment or an unexpected romantic encounter on the riverbank at sunset, Danshi Koukousei no Nichijou is rife with bizarre yet hilariously relatable situations that are anything but mundane.

[Written by MAL Rewrite]', 47, 9, 'https://myanimelist.net/images/anime/3/33257.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37450, 'Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai', '青春ブタ野郎はバニーガール先輩の夢を見ない', 'TV', 13, 'FINISHED', 8.23, 1237477, 406, 48, 'The rare and inexplicable Puberty Syndrome is thought of as a myth. It is a rare disease which only affects teenagers, and its symptoms are so supernatural that hardly anyone recognizes it as a legitimate occurrence. However, high school student Sakuta Azusagawa knows from personal experience that it is very much real, and happens to be quite prevalent in his school.

Mai Sakurajima is a third-year high school student who gained fame in her youth as a child actress, but recently halted her promising career for reasons unknown to the public. With an air of unapproachability, she is well known throughout the school, but none dare interact with her—that is until Sakuta sees her wandering the library in a bunny girl costume. Despite the getup, no one seems to notice her, and after confronting her, he realizes that she is another victim of Puberty Syndrome. As Sakuta tries to help Mai through her predicament, his actions bring him into contact with more girls afflicted with the elusive disease.

[Written by MAL Rewrite]', 55, 26, 'https://myanimelist.net/images/anime/1301/93586.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5690, 'Nodame Cantabile Finale', 'のだめカンタービレ フィナーレ', 'TV', 11, 'FINISHED', 8.23, 72156, 405, 1950, 'Shinichi Chiaki is quickly making a name for himself as the principal conductor of the revitalized Roux-Marlet Orchestra, and Megumi "Nodame" Noda has made leaps and bounds as a pianist at the Conservatoire de Paris. However, tensions mount between the two as Nodame feels left behind by Chiaki''s growing success and his close friendship with legendary piano prodigy Rui Son. Disregarding her teacher Professor Charles Auclair''s advice, Nodame enters another piano competition in an attempt to jumpstart her own performance career. 

Meanwhile, those around Chiaki and Nodame are at their own crossroads. Rui begins to doubt herself after hearing Nodame''s playing and being denied tutelage from Auclair; Maestro Franz von Stresemann faces the reality of his mortality; pianists Yunlong Li and Tatiana Vishneva feverishly prepare for a competition, while the latter also struggles with her growing feelings for oboist and fellow student Yasunori Kuroki. 

As Chiaki, Nodame, and their friends continue on their respective journeys, they must not only strive to stay true to themselves, but also remember where it all started.

[Written by MAL Rewrite]', 88, 58, 'https://myanimelist.net/images/anime/1084/119096.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1453, 'Maison Ikkoku', 'めぞん一刻', 'TV', 96, 'FINISHED', 8.23, 21471, 403, 2688, 'In the town of Clock Hill, there is an old boarding house called Maison Ikkoku. While the residence itself is fairly normal, most of its occupants are not. Yuusaku Godai, its most quiet tenant, has finally reached his limit with his neighbors'' constant disruptions and boisterous partying. Wanting a calmer place to call home so that he can study in peace, he prepares to move away.

However, his plans to leave are suddenly interrupted when he meets the new boarding house manager, Kyoko Otonashi. Falling madly in love with her, he decides that the boarding house may not be such a bad place to live after all. Unfortunately for him, Kyoko has her own romantic troubles: she is a widow whose husband died six months into their marriage. And despite her blossoming feelings for Godai, Kyoko still cherishes her dearly departed husband, and she believes that no other man could possibly fill the void in her heart. But with Godai''s persistence and some help of the other eccentric tenants, she may experience true love once again.

[Written by MAL Rewrite]', 99, 32, 'https://myanimelist.net/images/anime/6/17576.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (11977, 'Mahou Shoujo Madoka★Magica Movie 1: Hajimari no Monogatari', '劇場版 魔法少女まどか☆マギカ 始まりの物語', 'UNKNOWN', 1, 'FINISHED', 8.23, 108391, 402, 1296, 'Madoka Kaname and her best friend Sayaka Miki are ordinary middle school students in the city of Mitakihara. But one day, they encounter a strange cat-like creature named Kyuubey, who claims he can grant them one wish. In exchange, they would become magical girls and fight against evil perpetrated by witches. A veteran magical girl in the area, Mami Tomoe, decides to show them how to hunt witches, while the mysterious transfer student Homura Akemi warns them to not take Kyuubey''s deal, though she refuses to say why.

However, after witnessing the brutal reality of fighting witches, the girls decide it may be safer to decline Kyuubey''s offer. But when another magical girl arrives in the city and Sayaka decides to make a wish to help the one she loves, things quickly escalate as they are confronted with the harsh truth behind their powers and the ultimate price of their wishes.

[Written by MAL Rewrite]', NULL, 18, 'https://myanimelist.net/images/anime/6/42331.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (585, 'Mimi wo Sumaseba', '耳をすませば', 'UNKNOWN', 1, 'FINISHED', 8.23, 229590, 404, 670, 'Shizuku Tsukishima is an energetic 14-year-old girl who enjoys reading and writing poetry in her free time. Glancing at the checkout cards of her books one evening, she notices that her library books are frequently checked out by a boy named Seiji Amasawa. Curiosity strikes Shizuku, and she decides to search for the boy who shares her love for literature.

Meeting a peculiar cat on the train, Shizuku follows the animal and is eventually led to a quaint antique shop, where she learns about a cat statuette known as "The Baron." Taking an interest in the shop, she surprisingly finds Seiji, and the two quickly befriend one another. Shizuku learns while acquainting herself with Seiji that he has a dream that he would like to fulfill, causing her dismay as she remains uncertain of her future and has yet to recognize her talents.

However, as her relationship with Seiji grows, Shizuku becomes determined to work toward a goal. Guided by the whispers of her heart and inspiration from The Baron, she resolves to carve out her own potential and dreams.

[Written by MAL Rewrite]', NULL, 24, 'https://myanimelist.net/images/anime/1764/138714.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59062, 'Gachiakuta', 'ガチアクタ', 'TV', 24, 'FINISHED', 8.22, 211464, 414, 535, 'The inhabitants of a certain wealthy town think nothing of throwing objects away. However, their waste is priceless to Rudo, a resident of the town''s slums. Despite the constant warnings from his adoptive father Regto, Rudo spends his days searching for reusable materials that would otherwise be sent to the giant disposal area known as the Pit. Due to its vastness, the Pit doubles as a means of criminal punishment; those dropped in are never to return again.

When Regto is murdered by a mysterious assailant, Rudo is falsely accused of the crime and thrown into the Pit. To his surprise, he awakens in a trash-filled area inhabited by enormous monsters formed from the junk. As the toxic air and Trash Beasts push Rudo to the brink of death, he is saved by Enjin, one of the Cleaners who wield weapons known as Vital Instruments to fight the monstrosities. Having gained his own Vital Instrument, Rudo soon joins the Cleaners in the hopes of finding a way to escape the Pit and avenge his father.

[Written by MAL Rewrite]', 65, 29, 'https://myanimelist.net/images/anime/1682/150432.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (52588, 'Kaijuu 8-gou', '怪獣8号', 'TV', 12, 'FINISHED', 8.22, 419194, 417, 324, 'After the destruction of their hometown, childhood friends Kafka Hibino and Mina Ashiro make a pact to become officers in the Defense Force—a militarized organization tasked with protecting Japan from colossal monsters known as "kaijuu." Decades later, the 32-year-old Kafka has all but given up on his dreams of heroism. Instead, he cleans up the remains of the slaughtered kaijuu after they are defeated by valiant soldiers—including Mina, who has successfully achieved their shared goal.

Upon meeting his new coworker, Reno Ichikawa, Kafka faces a mirror of his past self: an ambitious young man whose one desire is to fight as a member of the Defense Force. Unfortunately, the two are soon involved in a freak encounter with a rogue kaijuu. Though Kafka demonstrates his innate heroic nature and rescues Reno from certain doom, he is left gravely injured.

While both men recover in a hospital, Kafka is seemingly attacked by another one of the beasts. As a result, he gains the ability to transform into a humanoid kaijuu with the strength and powers of the massive monsters menacing Japan. Dubbed "Kaijuu No. 8" by the military, Kafka resolves to use his newfound gifts for the greater good. Tied together by mutual respect, Kafka and Reno set out to join warriors like Mina at the forefront of the Defense Force.

[Written by MAL Rewrite]', 33, 23, 'https://myanimelist.net/images/anime/1370/140362.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (28805, 'Bakemono no Ko', 'バケモノの子', 'UNKNOWN', 1, 'FINISHED', 8.22, 240125, 411, 580, 'Two souls, living very different lives, wander alone and isolated in their respective worlds. For nine-year-old Ren, the last person who treated him with any form of kindness has been killed, and he is shunned by what is left of his family. With no parents, no real family, and no place to go, Ren escapes into the confusing streets and alleyways of Shibuya. Through the twists and turns of the alleys, Ren stumbles into the intimidating Kumatetsu, who leads him to the beast realm of Shibuten.

For Kumatetsu, the boy represents a chance for him to become a candidate to replace the lord of the realm once he retires. While nearly unmatched in combat, Kumatetsu''s chilly persona leaves him with no disciples to teach and no way to prove he is worthy of becoming the lord''s successor. 

While the two share different goals, they agree to help each other in order to reach them. Kumatetsu searches for recognition; Ren, now known as Kyuuta, searches for the home he never had. As the years pass by, it starts to become apparent that the two are helping each other in more ways than they had originally thought. Perhaps there has always been less of a difference between them, a boy and a beast, than either of the two ever realized.

[Written by MAL Rewrite]', NULL, 54, 'https://myanimelist.net/images/anime/11/73540.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1382, 'Yuusha-Ou GaoGaiGar Final', '勇者王ガオガイガーFINAL', 'OVA', 8, 'FINISHED', 8.22, 5453, 421, 6480, 'Following Gutsy Galaxy Guard''s victory over the Zonder Empire and the 31 Primevals, a new threat makes their appearance on Earth. GGG—with Guy Shishio and the newly-constructed GaoFighGar—team up with their French counterpart Chasseur to battle the evil organization BioNet. Among Chasseur''s ranks is Renais Cardiff Shishioh, a former BioNet cyborg with the relentless pursuit of destroying those who took away her humanity. But as GGG and Chasseur fight the BioNet, GGG''s bases around the world are suddenly attacked, and the recently-discovered "Q-Parts" and the original Gao Machines are stolen by Mamoru Amami, who has been abducted and cloned by an even greater threat known as the "Eleven Kings of Sol." Evicted from Earth by the United Nations, GGG must now travel to the far reaches of the galaxy to battle the Eleven Kings of Sol and save Mamoru before it''s too late.

(Source: ANN, edited)', NULL, 9, 'https://myanimelist.net/images/anime/1187/132740.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (48316, 'Kage no Jitsuryokusha ni Naritakute!', '陰の実力者になりたくて！', 'TV', 20, 'FINISHED', 8.22, 468965, 415, 250, 'For as long as he can remember, Minoru Kagenou has been fixated on becoming as strong as possible, which has led him to undertake all kinds of rigorous training. This wish, however, does not stem from a desire to be recognized by others; rather, Minoru does everything he can to blend in with the crowd. So, while pretending to be a completely average student during the day, he arms himself with a crowbar and ruthlessly thrashes local biker gangs at night. Yet when Minoru finds himself in a truck accident, his ambitions seemingly come to a sudden end. In his final moments, he laments his powerlessness—no matter how much he trained, there was nothing he could do to overcome his human limitations.

But instead of dying, Minoru reawakens as Cid, the second child of the noble Kagenou family, in another world—one where magic is commonplace. With the power he so desired finally within his grasp, he dons the moniker "Shadow" and establishes Shadow Garden: a group whose sole purpose is to combat the enigmatic Cult of Diablos, an organization born from Cid''s imagination. However, as Shadow Garden grows in both membership and influence, it becomes increasingly apparent that the Cult of Diablos is not as fictional as Cid had intended.

[Written by MAL Rewrite]', 9, 119, 'https://myanimelist.net/images/anime/1091/128729.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49571, 'Tunshi Xingkong 2nd Season', '吞噬星空 第二季', 'ONA', 26, 'FINISHED', 8.22, 3437, 420, 7550, 'Second season of Tunshi Xingkong.', NULL, 87, 'https://myanimelist.net/images/anime/1558/117008.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49918, 'Boku no Hero Academia 6th Season', '僕のヒーローアカデミア', 'TV', 25, 'FINISHED', 8.22, 422677, 412, 276, 'With Tomura Shigaraki at its helm, the former Liberation Army is now known as the Paranormal Liberation Front. This organized criminal group poses an immense threat to the Hero Association, not only because of its sheer size and strength, but also the overpowering quirks of Jin "Twice" Bubaigawara and Gigantomachia.

As new intel from the covert hero Keigo "Hawks" Takami confirms that Shigaraki is nowhere to be seen, the Hero Association decides to strike the enemy headquarters with a surprise attack using the entirety of its assets—and the UA students find themselves on the battlefield once again. As the fight rages on, the unsuspecting villains must regroup and push back, but the brave heroes are determined to eradicate every last one of them.

[Written by MAL Rewrite]', 9, 3, 'https://myanimelist.net/images/anime/1483/126005.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1842, 'Major S3', 'メジャー (第3シリーズ)', 'TV', 26, 'FINISHED', 8.22, 45982, 418, 2866, 'Having bid farewell to his former teammates at Kaido High School''s baseball club, Gorou Honda returns to his hometown eager to continue playing. Attending a new high school proves to be more difficult than he initially expected, as Tetsufumi Egashira''s merciless slandering of his name prevents Gorou from being accepted into any school with an existing baseball team. 

Left with no other options, Gorou joins Seishuu High School, where his childhood friend Kaoru Shimizu also attends. However, Seishuu has always been an all-girls school until two years ago, so there is not yet a dedicated men’s baseball team.

But nothing will stop Gorou in his pursuit of Koshien. He must now create a baseball team from scratch with the seven male students at Seishuu, but all of them are complete amateurs! He decides to train the incompetent team up to nationally competitive levels, but such a feat is easier said than done. Will Gorou once again perform miracles? Or will he give up on achieving his goal of defeating Kaido with his own team? 

[Written by MAL Rewrite]', 92, 122, 'https://myanimelist.net/images/anime/9/73971.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (16664, 'Kaguya-hime no Monogatari', 'かぐや姫の物語', 'UNKNOWN', 1, 'FINISHED', 8.22, 136599, 416, 1076, 'Deep in the countryside, a man named Okina works as a bamboo cutter in a forest, chopping away at the hollow plants day after day. One day, he discovers a small baby inside a glowing shoot. He immediately takes her home, convinced that she is a princess sent to Earth as a divine blessing from heaven. Okina and his wife Ouna take it upon themselves to raise the infant as their own, watching over her as she quickly grows into an energetic young girl. Given the name Kaguya, she fits right in with the village she has come to call home, going on adventures with the other children and enjoying what youth has to offer.

But when Okina finds a large fortune of gold and treasure in the forest, Kaguya''s life is completely changed. Believing this to be yet another gift from heaven, he takes it upon himself to turn his daughter into a real princess using the wealth he has just obtained, relocating the family to a mansion in the capital. As she leaves her friends behind to enter into an unwanted life of royalty, Kaguya''s origins and purpose slowly come to light.

[Written by MAL Rewrite]', NULL, 24, 'https://myanimelist.net/images/anime/1935/93606.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6, 'Trigun', 'トライガン', 'TV', 26, 'FINISHED', 8.22, 401133, 419, 265, 'Vash the Stampede is the man with a $$60,000,000,000 bounty on his head. The reason: he''s a merciless villain who lays waste to all those that oppose him and flattens entire cities for fun, garnering him the title "The Humanoid Typhoon." He leaves a trail of death and destruction wherever he goes, and anyone can count themselves dead if they so much as make eye contact—or so the rumors say. In actuality, Vash is a huge softie who claims to have never taken a life and avoids violence at all costs.

With his crazy doughnut obsession and buffoonish attitude in tow, Vash traverses the wasteland of the planet Gunsmoke, all the while followed by two insurance agents, Meryl Stryfe and Milly Thompson, who attempt to minimize his impact on the public. But soon, their misadventures evolve into life-or-death situations as a group of legendary assassins are summoned to bring about suffering to the trio. Vash''s agonizing past will be unraveled and his morality and principles pushed to the breaking point.

[Written by MAL Rewrite]', 32, 1, 'https://myanimelist.net/images/anime/1130/120002.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (372, 'Cardcaptor Sakura Movie 2: Fuuin Sareta Card', '劇場版 カードキャプターさくら 封印されたカード', 'UNKNOWN', 1, 'FINISHED', 8.22, 70985, 413, 2062, 'For this year''s Nadeshiko Festival, Sakura Kinomoto''s elementary school class is presenting a play. She will portray a princess who struggles to respond to the love confession of the neighboring country''s prince. Sakura empathizes with her character all too well, since she herself still owes an answer to the boy who confessed his love for her four months ago.

When cousins Shaoran and Meiling Li return from Hong Kong to pay a surprise visit to their friends in Japan, Sakura receives further encouragement to finally declare her feelings. However, she is repeatedly distracted by a presence reminiscent of a Clow Card as well as unexplained disappearances around town.

Eventually, Sakura learns of another of Clow Reed''s creations—the "Nothing"—which was formerly sealed away beneath the magician''s old house. It has power equal to all 52 cards Sakura possesses, and furthermore, it wants to take those cards away from her! Objects, space, and people disappear from Tomoeda with each card that is stolen. Sakura sets out to capture the Nothing so everything will return to normal, but what must she sacrifice in the process?

[Written by MAL Rewrite]', NULL, 1, 'https://myanimelist.net/images/anime/1652/90326.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59027, 'Spy x Family Season 3', 'SPY×FAMILY Season 3', 'TV', 13, 'FINISHED', 8.21, 127411, 435, 815, 'Despite occasional setbacks, Operation Strix has remained on track to extract sensitive information from the enigmatic politician Donovan Desmond. To this end, spy Loid Forger has managed to maintain his pretend family consisting of his telepathic daughter, Anya; assassin wife, Yor; and their clairvoyant dog, Bond. Still the only one aware of everyone''s true identities, Anya tries to sustain the family''s cohesion while working to befriend Donovan''s son Damian, her Eden Academy classmate.

However, Anya''s efforts instead earn her another Tonitrus Bolt, bringing her closer to getting expelled and jeopardizing the operation''s success. Hearing the news, Loid faints from shock. In his unconsciousness, he reminisces about his tragic past and his journey to becoming a spy. Realizing what Operation Strix means to him and the world, Loid finds renewed motivation. Although they each work toward their own covert goals, the Forgers continue to cherish their chaotic yet blissful family life.

[Written by MAL Rewrite]', 39, 6, 'https://myanimelist.net/images/anime/1697/151793.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (53393, 'Tengoku Daimakyou', '天国大魔境', 'TV', 13, 'FINISHED', 8.21, 291939, 436, 395, 'Fifteen years ago, disaster struck human civilization, and now dangerous man-eating monsters roam the ravaged lands, posing an existential threat to the remaining survivors. Amid this turmoil, an isolated facility shelters children and nurtures them in peace. However, as a few among them find out about the world beyond the narrow periphery of their nursery''s walls, their curiosity about it slowly grows.

Meanwhile, in the outside world, young survivors Maru and Kiruko band together to search for a special place called Heaven, each for their own reasons. Carrying past burdens and tragic secrets, the two hope to find answers to the cruelty they have experienced in their lives and in the world, which still remains in tatters.

[Written by MAL Rewrite]', 64, 23, 'https://myanimelist.net/images/anime/1121/133132.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (35110, 'Haikyuu!! Movie 3: Sainou to Sense', 'ハイキュー!! 才能とセンス', 'UNKNOWN', 1, 'FINISHED', 8.21, 44496, 427, 2248, 'Following the events of the Inter-High, the Karasuno High School volleyball team decides to regroup by attending an intensive boot camp organized by Nekoma High School in Tokyo. At the camp, the team continues to suffer loss upon loss to the other schools in attendance. Reaching an impasse, the players each struggle to break out of their routine to hone their skills. 

For the team''s setter-and-ace duo Shouyou Hinata and Tobio Kageyama, the frustrations cause them to falter more than anyone else. While Hinata develops his own playstyle, his recklessness leads him to fall out of sync with Kageyama''s sets and earns his partner''s ire instead. As they search for an answer to their woes, the two find what they are lacking from two unlikely people. Will it be enough for the team to overcome their rut?

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/1034/147253.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (12115, 'Berserk: Ougon Jidai-hen III - Kourin', 'ベルセルク 黄金時代篇Ⅲ 降臨', 'UNKNOWN', 1, 'FINISHED', 8.21, 153466, 422, 1145, 'The Band of the Hawk has dwindled in the year since Guts left them on his journey to forge his own destiny. Unaware of their fate, Guts returns to the Hawks—now being led by his former ally Casca—after a rumor about them passes his way. Once the saviors of the kingdom of Midland, the Band of the Hawk are now hunted as they desperately fight for their lives while plotting to free their leader, Griffith, after he was imprisoned for committing treason. But the man they save is far from the Griffith they remember.

Griffith is a shell of his former charismatic self after a year of continuous, horrific torture. No longer able to walk, speak, or even hold a sword, he has nothing but the small, strange trinket, the Crimson Behelit, that will not leave him. The entire Band of the Hawk want to rise to greatness once more, but how much are they willing to sacrifice to return to their past glory? It doesn''t seem possible, but when Griffith''s heart darkens and a solar eclipse blackens the sky, the Behelit offers a choice that will leave the Band of the Hawk with a blood-soaked fate that will haunt them for the rest of their days.

[Written by MAL Rewrite]', NULL, 123, 'https://myanimelist.net/images/anime/12/41305.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39166, 'Girls & Panzer: Saishuushou Part 3', '『ガールズ＆パンツァー 最終章』第3話', 'UNKNOWN', 1, 'FINISHED', 8.21, 16960, 426, 3681, 'The quarterfinal round of the Winter Continuous Track Cup is in full swing, and each school is going all out. What started as a furious back-and-forth firefight between Ooarai Girls Academy and Chi-Ha-Tan Academy has become a 12-hour jungle slugfest with neither team having the advantage and almost everyone running on fumes. In spite of this, Miho Nishizumi and her teammates continue to fight into the morning, hoping to land a decisive blow before their rivals.

Meanwhile, Kuromorimine Girls Academy—now led by Erika Itsumi—is struggling in its match against Pravda High School. Taking Maho Nishizumi''s words of advice to heart, Erika manages to break free of Kuromorimine''s rigid, traditional tactics and turn the tide in her favor. At the same time, St. Gloriana Girls College faces off against Anzio High School, while Saunders University High School has a tough fixture with underdog Continuation High School and its mysterious sharpshooter, Jouko. 

With only four semifinal spots up for grabs, the members of each team must give their absolute best performance if they want to survive and successfully make it to the next round!

[Written by MAL Rewrite]', NULL, 81, 'https://myanimelist.net/images/anime/1894/119214.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (5460, 'Meitantei Conan Movie 13: Shikkoku no Chaser', '名探偵コナン漆黒の追跡者(チェイサー)', 'UNKNOWN', 1, 'FINISHED', 8.21, 36722, 429, 3087, 'Kudou Shinichi is living his life as Edogawa Conan, but those days seem like they might end pretty soon. The Black Syndicate is coming dangerously close to learning the truth about Shinichi having survived. Conan and everybody around him may end up dead if he doesn''t manage to find Irish—a member of the Black Organization who has infiltrated the police forces, currently investigating a big serial murder case.', NULL, 21, 'https://myanimelist.net/images/anime/2/22558.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38249, 'Saiki Kusuo no Ψ-nan: Kanketsu-hen', '斉木楠雄のΨ難 完結編', 'UNKNOWN', 1, 'FINISHED', 8.21, 147611, 432, 1130, 'The ground shakes, a rumble follows, and before anyone in Japan can prepare themselves, a cataclysmic volcanic eruption engulfs the country in molten lava and suffocating ashes. Of course, high school student Kusou Saiki repeatedly uses his psychic powers to prevent this harrowing catastrophe.

But between restoring the planet and watching his friends discuss their aspirations, Saiki finally resolves to stop the eruption and allow the world to continue spinning. However, this straightforward task is challenging even for the most powerful of psychics, let alone one who must deal with the usual shenanigans his ludicrous friends present.

[Written by MAL Rewrite]', NULL, 58, 'https://myanimelist.net/images/anime/1159/95661.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (2966, 'Ookami to Koushinryou', '狼と香辛料', 'TV', 13, 'FINISHED', 8.21, 414829, 430, 244, 'Holo is a powerful wolf deity who is revered in the small town of Pasloe for blessing the annual harvest. Yet as years go by and the villagers become more self-sufficient, Holo has been reduced to a mere folktale. When a traveling merchant named Kraft Lawrence stops at the settlement, Holo offers to become his business partner if he takes her to her northern home of Yoitsu. The savvy trader recognizes Holo''s unusual ability to evaluate a person''s character and accepts her proposition. 

Now in the possession of both sharp bargaining skills and a charismatic negotiator, Lawrence inches closer to his goal of opening his own shop. However, as Lawrence travels the countryside with Holo in search of economic opportunities, he begins to realize that his aspirations are slowly morphing into something unexpected.

[Written by MAL Rewrite]', 70, 124, 'https://myanimelist.net/images/anime/5/59401.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (47794, 'MILGЯAM', 'ミルグラム', 'UNKNOWN', NULL, 'AIRING', 8.21, 2142, NULL, 6486, 'Es awakens in the facility Milgram to find a strange talking animal named Jackalope staring them down. Soon, they learn their purpose: as the prison guard, Es must delve into the psyches of 10 inmates, each of them imprisoned for causing the loss of life in some form or another. Their fates rest in Es'' hands. Do the means justify an end, and how much does intent matter if the result is death? No matter how the lines between good and evil, right and wrong, and just and cruel are blurred, there are only two options Es can choose between: innocent or guilty.

[Written by MAL Rewrite]', NULL, 125, 'https://myanimelist.net/images/anime/1497/112023.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (35466, 'ReLIFE: Kanketsu-hen', 'ReLIFE 完結編', 'UNKNOWN', 4, 'FINISHED', 8.21, 266266, 431, 592, 'After reliving the life of a high school student through the ReLIFE experiment, 27-year-old Arata Kaizaki cannot believe how quickly it has changed him. He has begun to see the world through a different perspective that he had completely forgotten as an adult. He has made friends and formed deep relationships with each one of them. However his support, Ryou Yoake, reminds him that the experiment is all an illusion; after his experiment ends, he will be forgotten by all of them.

The experiment of another ReLIFE subject is also coming to an end. After spending two years with ReLIFE, Chizuru Hishiro has developed into a more open, more thoughtful person than she could have ever imagined. She has met people who have changed her life, her perspective, and ultimately her. However, now that their ReLIFE is coming to an end, will they be able to let go of the memories they have made?

[Written by MAL Rewrite]', NULL, 14, 'https://myanimelist.net/images/anime/1566/91061.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (3091, 'xxxHOLiC◆Kei', '×××HOLiC◆継', 'TV', 13, 'FINISHED', 8.21, 70489, 437, 1719, 'Kimihiro Watanuki''s life was never really normal. But in addition to his ability to see spirits, this sequel to xxxHOLiC finds him still slaving away for Yuuko, the bizarre owner of a strange shop, who promised to rid him of this ability. However, this otherworldly woman can only do so when he has worked enough to earn his wish. Such is the way for anyone who finds their way into the shop to have their request granted: a compensation equal to their wish must be paid. 

In this odd shop that straddles the world of the living and the dead, Watanuki finds himself doing household chores for the seemingly lazy Yuuko and her companions, while also helping out clients. Along with his classmates, supposed romantic rival Shizuka Doumeki and his crush Himawari Kunogi, Watanuki deals with the many misfortunes surrounding Yuuko''s customers, as well as those that closely follow him and his friends.

[Written by MAL Rewrite]', 14, 23, 'https://myanimelist.net/images/anime/9/8626.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (32843, 'Senki Zesshou Symphogear XV', '戦姫絶唱シンフォギアXV', 'TV', 13, 'FINISHED', 8.21, 16101, 433, 3868, 'Humanity is finally confronted with the threat of the Custodians—the ancient, sentient species held responsible for cursing humanity to speak different languages thousands of years ago. The Symphogear wielders—Hibiki Tachibana, Tsubasa Kazanari, Chris Yukine, Maria Cadenzavna Eve, Kirika Akatsuki, and Shirabe Tsukuyomi—are sent to the Antarctic in order to retrieve an ancient relic. After securing it and rescuing the scientific staff present there from a Coffin, the automated defense mechanism protecting it, the relic is given to American researchers due to international agreements.

The criminal organization Noble Red, a remnant of the previously fought Bavarian Illuminati, starts targeting the relic. Will the Symphogear wielders and their supporting organization S.O.N.G. be able to foil the plans of the organizations conspiring against them?

[Written by MAL Rewrite]', 27, 98, 'https://myanimelist.net/images/anime/1899/101966.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (627, 'Major S1', 'メジャー （第1シリーズ）', 'TV', 26, 'FINISHED', 8.21, 54335, 428, 2259, 'Gorou Honda, a little boy obsessed with baseball, has always admired his father, Shigeharu. Wishing to follow in his father''s footsteps, Gorou dreams of becoming a professional baseball player. In turn, his son''s starry-eyed admiration encourages Shigeharu to keep persevering, despite his late wife''s death and his unsatisfying position on the second-string team Blue Ocean.

Unfortunately, an elbow injury forces Shigeharu off the team, and he falls into despair. However, after an offhand joke from his childhood friend, Shigeharu reevaluates his choices and decides to keep playing, leaving behind his prime position as pitcher and taking up the bat. Now motivated more than ever, Gorou works hard to carve his way in the Japanese Little League.

[Written by MAL Rewrite]', 91, 122, 'https://myanimelist.net/images/anime/13/73973.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38680, 'Fruits Basket 1st Season', 'フルーツバスケット', 'TV', 25, 'FINISHED', 8.21, 449644, 425, 213, 'Tooru Honda has always been fascinated by the story of the Chinese zodiac that her beloved mother told her as a child. However, a sudden family tragedy changes her life, and subsequent circumstances leave her all alone. Tooru is now forced to live in a tent, but little does she know that her temporary home resides on the private property of the esteemed Souma family. Stumbling upon their home one day, she encounters Shigure, an older Souma cousin, and Yuki, the "prince" of her school. Tooru explains that she lives nearby, but the Soumas eventually discover her well-kept secret of being homeless when they see her walking back to her tent one night.

Things start to look up for Tooru as they kindly offer to take her in after hearing about her situation. But soon after, she is caught up in a fight between Yuki and his hot-tempered cousin, Kyou. While trying to stop them, she learns that the Souma family has a well-kept secret of their own: whenever they are hugged by a member of the opposite sex, they transform into the animals of the Chinese zodiac.

With this new revelation, Tooru will find that living with the Soumas is an unexpected adventure filled with laughter and romance.

[Written by MAL Rewrite]', 4, 14, 'https://myanimelist.net/images/anime/1447/99827.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (813, 'Dragon Ball Z', 'ドラゴンボールZ', 'TV', 291, 'FINISHED', 8.21, 905748, 424, 117, 'Five years after winning the World Martial Arts tournament, Gokuu is now living a peaceful life with his wife and son. This changes, however, with the arrival of a mysterious enemy named Raditz who presents himself as Gokuu''s long-lost brother. He reveals that Gokuu is a descendant of the once powerful but now virtually extinct Saiyan race, whose homeworld was annihilated. When he was sent to Earth as a baby, Gokuu''s sole purpose was to conquer and destroy the planet; but after suffering amnesia from a head injury, his violent and savage nature changed, and instead was raised as a kind and well-mannered boy, now fighting to protect others.

With his failed attempt at forcibly recruiting Gokuu as an ally, Raditz warns Gokuu''s friends of a new threat that''s rapidly approaching Earth—one that could plunge Earth into an intergalactic conflict and cause the heavens themselves to shake. A war will soon be fought over the seven mystical Dragon Balls, magic objects that can grant any wish. Only the strongest will survive.

[Written by MAL Rewrite]', 100, 8, 'https://myanimelist.net/images/anime/1277/142022.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (9863, 'SKET Dance', 'スケットダンス', 'TV', 77, 'FINISHED', 8.21, 88723, 434, 1185, 'At Kaimei High School there is a special club dedicated to helping others known as the SKET Brigade. The brains of the group is Kazuyoshi "Switch" Usui, a tech-savvy otaku who speaks through speech synthesis software, while the brawn is provided by Hime "Himeko" Onizuka, the hockey stick-wielding girl once known as "Onihime."  And last but not least, their leader is Yuusuke "Bossun" Fujisaki, whose latent ability is evoked by his goggles, allowing him to summon the awesome power of extraordinary concentration.  

However, most of the school only know them as the club that handles odd jobs. Many of their days are spent in the clubroom slacking off, but when there is something to be done, they give their all to help others—usually in sincere, but unintentionally hilarious, ways. The SKET Brigade do all they can to provide support, kindness, encouragement, and troubleshooting to any students crazy enough to ask for their services.  

[Written by MAL Rewrite]', 3, 45, 'https://myanimelist.net/images/anime/9/73974.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (36946, 'Dragon Ball Super: Broly', 'ドラゴンボール超（スーパー） ブロリー', 'UNKNOWN', 1, 'FINISHED', 8.21, 324420, 423, 560, 'Forty-one years ago on Planet Vegeta, home of the infamous Saiyan warrior race, King Vegeta noticed a baby named Broly whose latent power exceeded that of his own son. Believing that Broly''s power would one day surpass that of his child, Vegeta, the king sends Broly to the desolate planet Vampa. Broly''s father Paragus follows after him, intent on rescuing his son. However, his ship gets damaged, causing the two to spend years trapped on the barren world, unaware of the salvation that would one day come from an unlikely ally.

Years later on Earth, Gokuu Son and Prince Vegeta—believed to be the last survivors of the Saiyan race—are busy training on a remote island. But their sparring is interrupted when the appearance of their old enemy Frieza drives them to search for the last of the wish-granting Dragon Balls on a frozen continent. Once there, Frieza shows off his new allies: Paragus and the now extremely powerful Broly. A legendary battle that shakes the foundation of the world ensues as Gokuu and Vegeta face off against Broly, a warrior without equal whose rage is just waiting to be unleashed.

[Written by MAL Rewrite]', NULL, 8, 'https://myanimelist.net/images/anime/1575/93498.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (60420, 'Cang Yuan Tu 2', '沧元图2', 'ONA', 36, 'FINISHED', 8.2, 1003, 440, 12131, 'Second season of Cang Yuan Tu.', NULL, 96, 'https://myanimelist.net/images/anime/1403/155838.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55866, 'Yubisaki to Renren', 'ゆびさきと恋々', 'TV', 12, 'FINISHED', 8.2, 160327, 452, 802, 'For hearing-impaired university student Yuki Itose, silence has been a natural part of life since birth. Her world is small and isolated; she commutes to campus, interacts with her best friend Rin Fujishiro, and communicates through writing and text messages—a lifestyle that offers little to no change. One day, during her commute, Yuki meets fellow student Itsuomi Nagi, a multilingual travel enthusiast and friend of Rin. When Itsuomi learns of Yuki''s condition, he takes it in stride, moving Yuki''s heart. From this one simple gesture, Yuki and Itsuomi''s lives start changing day by day as they let each other into their own worlds.

[Written by MAL Rewrite]', 35, 127, 'https://myanimelist.net/images/anime/1478/140828.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (52578, 'Boku no Kokoro no Yabai Yatsu', '僕の心のヤバイやつ', 'TV', 12, 'FINISHED', 8.2, 229284, 438, 605, 'Kyoutarou Ichikawa may look like a shy and reserved middle school student, but deep within his heart is a bloodthirsty killer. His ultimate desire is to see his classmate Anna Yamada''s beautiful face writhing in pain before he ends her life. But this fantasy may never come to fruition, as Ichikawa starts to see an entirely different side to Yamada.

Often seeking refuge in the library, Ichikawa frequently runs into Yamada. It is during these encounters that Ichikawa realizes his model classmate is actually an airhead who can never read the room. As they spend more time together, the boy cannot help but feel not only a sense of endearment toward the very girl he wishes to murder but also a desire to protect her at all costs. Is it possible that this sudden change in Ichikawa''s perspective could lead to something more?

[Written by MAL Rewrite]', 64, 33, 'https://myanimelist.net/images/anime/1545/133887.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (51179, 'Mushoku Tensei II: Isekai Ittara Honki Dasu', '無職転生 II ～異世界行ったら本気だす～', 'TV', 12, 'FINISHED', 8.2, 441113, 448, 308, 'After his relationship with Eris Boreas Greyrat reaches new heights, Rudeus Greyrat is ecstatic. Unfortunately, his joy is short-lived, as Eris suddenly abandons him to embark on her own journey. Believing that Eris has lost all interest in him, a heartbroken and depressed Rudeus sets forth to the Northern Territories. With his sole goal being to locate his mother on the vast continent, Rudeus wonders if persisting through daily life is worth the pain, falling into a robotic routine as he endlessly ruminates on his lost love.

However, the dangers of the North soon prove that one cannot survive with a dulled mind. While on a quest with the party Counter Arrow, with whom he recently became acquainted, Rudeus has a brush with death—an experience that forces him to finally snap out of his despair. With his newfound teammates, Rudeus rediscovers the pleasure of daily adventuring and moves forward with his original goal of living his second lease on life to the fullest.

[Written by MAL Rewrite]', 41, 51, 'https://myanimelist.net/images/anime/1898/138005.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (18617, 'Girls & Panzer Movie', 'ガールズ&パンツァー 劇場版', 'UNKNOWN', 1, 'FINISHED', 8.2, 65011, 442, 1974, 'Having won the 63rd National Sensha-dou tournament, the girls from Ooarai Girls Academy managed to prevent their school from closure by the Japanese Ministry of Education. However, new troubles loom on the horizon: a ministry official argues that the deal was not legally binding and that the Ooarai school carrier is to be decommissioned. Students and their families are frustrated with this injustice and overwhelmed with despair; it seems little can be done to save the school.

Their last glimmer of hope is a proposed match against the All-Stars University Sensha-dou team, consisting of the most talented students from all over the country. Despite Ooarai being severely outnumbered and clearly outclassed, they accept the challenge.

[Written by MAL Rewrite]', NULL, 81, 'https://myanimelist.net/images/anime/1776/91467.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38003, 'Bungou Stray Dogs 3rd Season', '文豪ストレイドッグス 第3期', 'TV', 12, 'FINISHED', 8.2, 377533, 439, 334, 'Following the conclusion of the three-way organizational war, government bureaucrat Ango Sakaguchi recalls an event that transpired years ago, after the death of the former Port Mafia boss. Osamu Dazai, still a new recruit at the time, was tasked with investigating rumors related to a mysterious explosion that decimated part of the city years ago—and its connection to the alleged reappearance of the former boss.

Due to circumstances out of his control, he is partnered with Chuuya Nakahara, the gifted yet impulsive leader of a rival clan known as the Sheep, to uncover the truth behind the case and shine a light on the myth of Arahabaki—the god of fire who might just lead Dazai to the case''s solution.

Meanwhile, in the present day, it is business as usual once again for the Armed Detective Agency. Their peaceful break will not last for long, however, as enemies old and new gather their strength and prepare for another face-off.

[Written by MAL Rewrite]', 4, 3, 'https://myanimelist.net/images/anime/1037/100463.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (44412, 'Doupo Cangqiong 4th Season', '斗破苍穹 第4季', 'ONA', 24, 'FINISHED', 8.2, 5026, 441, 7171, 'To awaken his teacher Yao Cheng, Xiao Yan travels to the capital for a meeting of the pill masters. His power was immediately noticed, people who wanted to use it, but at the decisive moment Xiao Yan still becomes a champion and defends the honor of the empire. But Xiao Yan is waiting for a meeting, for which he has been preparing for three whole years...', NULL, 75, 'https://myanimelist.net/images/anime/1887/112452.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (23847, 'Yahari Ore no Seishun Love Comedy wa Machigatteiru. Zoku', 'やはり俺の青春ラブコメはまちがっている。続', 'TV', 13, 'FINISHED', 8.2, 746700, 450, 146, 'With the Volunteer Service Club now firmly established, it is receiving more requests from students in search of solutions to their various issues. However, the club members often struggle to see eye to eye when it comes to their problem-solving ideals. The suggestions that Hachiman Hikigaya recommends frequently clash with those of Yukino Yukinoshita, fracturing the relationships within the club. 

Despite their differences, with the trio constantly trying to find common ground, they may soon reach a point where they discover something genuine.

[Written by MAL Rewrite]', 5, 94, 'https://myanimelist.net/images/anime/11/75376.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6811, 'InuYasha: Kanketsu-hen', '犬夜叉 完結編', 'TV', 26, 'FINISHED', 8.2, 153555, 444, 916, 'Thwarted again by Naraku, Inuyasha, Kagome Higurashi, and their friends must continue their hunt for the few remaining Shikon Jewel shards, lest they fully form into a corrupted jewel at the hands of Naraku. But Naraku has plans of his own to acquire them, and will destroy anyone and anything standing in his way—even his own underlings.

The persistent, unyielding danger posed by Naraku forces Sango and Miroku to decide what is most important to them—each other or their duty in battle. Meanwhile, Inuyasha must decide whether his heart lies with Kikyou or Kagome, before fate decides for him. Amid the race to find the shards, Inuyasha and his brother Sesshoumaru must also resolve their feud and cooperate for their final confrontation with Naraku, as it is a battle they must win in order to put a stop to his evil and cruelty once and for all.

[Written by MAL Rewrite]', 101, 9, 'https://myanimelist.net/images/anime/7/75570.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (16894, 'Kuroko no Basket 2nd Season', '黒子のバスケ', 'TV', 25, 'FINISHED', 8.2, 587984, 446, 218, 'With the Interhigh Championship finally over, Seirin''s basketball team refocuses their efforts, training harder than ever to get the chance to participate in the Winter Cup. Both Tetsuya Kuroko and Taiga Kagami see old friends walk back into their lives, providing a challenge both on and off the court.

As new skills are developed and new alliances created, enemies from various teams—giants of high school basketball such as Yousen, Shuutoku, and Touou—stand in the way of Seirin''s steadfast attempts to get to the top. All of these schools prove to be formidable foes whose abilities progress exponentially, while Kuroko struggles to find a balance between his resolve to play as part of a team and his desire to win. 

With old wounds reopening, new challenges to face on the court, and a new set of foes—the "Uncrowned Kings"—vowing to defeat the new hopefuls, will Seirin ever be able to achieve their dream of beating the Generation of Miracles?

[Written by MAL Rewrite]', 51, 23, 'https://myanimelist.net/images/anime/9/56155.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49590, 'Yojouhan Time Machine Blues', '四畳半タイムマシンブルース', 'ONA', 6, 'FINISHED', 8.2, 16104, 451, 3108, 'On a hot summer day in Kyoto, a young man walks toward his apartment, dreaming of turning on the air conditioner and cooling down. But before he can turn his dream into reality, disaster naturally strikes in the form of Ozu, who spills soda all over the remote. With the air conditioner rendered completely unusable, the man and his friends are left to suffer in the terrible August heat.

Just when all hope seems lost, the group finds a true-to-life time machine in their storage room. Not knowing the dire consequences of doing so, they decide to travel back to the past and grab the remote before Ozu even has a chance to destroy it. What awaits them on the other side is a staggering adventure none of them are prepared for.

[Written by MAL Rewrite]', NULL, 76, 'https://myanimelist.net/images/anime/1583/126128.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (186, 'Initial D Second Stage', '頭文字〈イニシャル〉D SECOND STAGE', 'TV', 13, 'FINISHED', 8.2, 152929, 443, 1070, 'Accumulating an impressive series of victories with his AE86, Takumi Fujiwara has imposed himself as street racing''s newest rising star. However, his newly found confidence of winning at his home turf of Mount Akina has been put in jeopardy by a new Emperor team exclusively using a car model favored by most professional racing pilots: the Mitsubishi four-wheel drive Lancer Evolutions—also known as Lan Evos. The Emperor team leader, Kyouichi Sudou, looks down on Takumi and regards him as an inferior pilot for driving an antique car that lacks the makings of a true modern race car. Kyouichi''s elitist philosophy is also the reason why his team is only made of Lan Evo drivers.

Will Takumi be able to keep his perfect track record intact against the highly skilled and mechanically superior Emperor team, or does his hot streak end here?

[Written by MAL Rewrite]', 34, 128, 'https://myanimelist.net/images/anime/8/12750.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (50602, 'Spy x Family Part 2', 'SPY×FAMILY', 'TV', 13, 'FINISHED', 8.2, 617646, 449, 154, 'With Anya Forger successfully enrolled at the renowned Eden Academy, Operation Strix advances to its second phase. To investigate Ostanian politician Donovan Desmond, Anya must either befriend his son Damian or collect eight Stella Stars to become an Imperial Scholar. Fortunately, Anya has already acquired her first star. In celebration, her adoptive father, Loid, decides to fulfill her wish to adopt a dog.

During their canine search, Loid receives new orders from his superiors, who have found that a band of Berlint University students is plotting to assassinate Westalis'' Minister Brantz using bombs worn by trained dogs. While Loid tries to stop their plans, Anya stumbles upon the terrorists'' base of operations. There, she befriends a kindhearted, clairvoyant dog who the family later names Bond.

Although the Forgers continue to lead their individual lives in secrecy, the family—with a new fluffy addition—remains united through all of the unusual obstacles thrown their way.

[Written by MAL Rewrite]', 9, 6, 'https://myanimelist.net/images/anime/1111/127508.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39247, 'Kobayashi-san Chi no Maid Dragon S', '小林さんちのメイドラゴンS', 'TV', 12, 'FINISHED', 8.2, 309439, 445, 409, 'As Tooru continues on her quest to become the greatest maid and Kanna Kamui fully immerses in her life as an elementary school student, there is not a dull day in the Kobayashi household with mischief being a daily staple. On one such day, however, a massive landslide is spotted on the hill where Kobayashi and Tooru first met—a clear display of a dragon''s might. When none of the dragons they know claim responsibility, the perpetrator herself descends from the skies: Ilulu, the radical Chaos Dragon with monstrous power rivaling that of Tooru.

Sickened by Tooru''s involvement with humans, Ilulu resorts to the typical dragon method of resolving conflict—a battle to the death. Despite such behavior, she becomes intrigued by Kobayashi''s ability to befriend dragons and decides instead to observe just what makes Kobayashi so special. With a new troublesome dragon in town, Kobayashi''s eccentric life with a dragon maid is only getting merrier.

[Written by MAL Rewrite]', 90, 15, 'https://myanimelist.net/images/anime/1252/115539.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (18115, 'Magi: The Kingdom of Magic', 'マギ The kingdom of magic', 'TV', 25, 'FINISHED', 8.2, 484051, 447, 233, 'After celebrating their victory against Al-Thamen, Aladdin and his friends depart the land of Sindria. With the end of the battle, however, comes the time for each of them to go their separate ways. Hakuryuu and Kougyoku are ordered to go back to their home country, the Kou Empire. Meanwhile Aladdin announces he needs to head for Magnostadt—a mysterious country ruled by magicians—to investigate the mysterious events occurring in this new kingdom and become more proficient in magic. For their part, encouraged by Aladdin''s words, Alibaba and Morgiana also set off in pursuit of their own goals: training and going to her homeland, respectively.

Magi: The Kingdom of Magic follows these friends as they all go about their separate adventures, each facing their own challenges. However, a new threat begins to rise as a great war looms over the horizon...

[Written by MAL Rewrite]', 51, 13, 'https://myanimelist.net/images/anime/13/55039.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59654, 'Jujutsu Kaisen: Kaigyoku/Gyokusetsu', '呪術廻戦 懐玉・玉折', 'UNKNOWN', 1, 'FINISHED', 8.19, 12256, 458, 3238, 'A compilation movie of Jujutsu Kaisen''s Hidden Inventory and Premature Death arc.', NULL, 4, 'https://myanimelist.net/images/anime/1999/147023.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37171, 'Asobi Asobase', 'あそびあそばせ', 'TV', 12, 'FINISHED', 8.19, 251597, 453, 471, 'During recess, Olivia, a foreign transfer student who doesn''t know English, plays a game of "look-the-other-way" with Hanako Honda, a loud-mouthed airhead. Their rowdy behavior spurs the ire of Kasumi Nomura, a deadpan loner constantly teased by her older sister for her tendency to lose games. Not willing to compete, Kasumi declines Olivia''s offer to join the fun, but eventually gets involved anyway and dispenses her own brand of mischief. Soon, a strange friendship blossoms between the peculiar trio, and they decide to form the "Pastime Club," where they are free to resume their daily hijinks. 

Whether it be failing to learn English, trying desperately to become popular, or getting caught by teachers at the wrong time, school life will never be boring when the girls of Asobi Asobase are up to their hilarious antics.

[Written by MAL Rewrite]', 20, 60, 'https://myanimelist.net/images/anime/1139/95077.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (37514, 'Made in Abyss Movie 1: Tabidachi no Yoake', '劇場版総集編【前編】メイドインアビス 旅立ちの夜明け', 'UNKNOWN', 1, 'FINISHED', 8.19, 60848, 460, 1667, 'The movie is a compilation of episodes 1-8 of the 2017 television series with new scenes added for the introduction. It covers the period from when Riko descends into the Abyss with her robot companion Reg, reaching the second layer where they meet the White Whistle Ozen who reveals information about Riko''s mother.

(Source: Wikipedia)', NULL, 48, 'https://myanimelist.net/images/anime/1173/95167.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (32005, 'Meitantei Conan Movie 20: Junkoku no Nightmare', '劇場版　名探偵コナン　純黒の悪夢（ナイトメア）', 'UNKNOWN', 1, 'FINISHED', 8.19, 26325, 462, 3714, 'On a dark night, the Japanese police is raided by a spy. Different countries'' intelligence agencies—such as England''s MI6, Germany''s BND, and America''s CIA—as well as the FBI''s secret files are going to be taken, but public safety officers lead by Tooru Amuro arrive just in time. The spy steals a car and escapes. The spy and Amuro are then locked in a dead heat on the highway, and just as it is about to cause an accident with multiple cars, the spy''s car is hit by FBI agent Shuichi Akai''s rifle bullet and falls of the roadway.
The next day, Conan and his friends go to a newly-remodeled aquarium in Tokyo. Under the main attraction, a Ferris wheel, Conan finds an attractive woman alone and injured. Her left and right eyes are different colors.

But the woman is in a state of amnesia where she doesn''t even remember her own name, and the cellphone she''s carrying is broken. Conan and his friends promise to help her regain her memory, so they stay with her.

Throughout all this, Vermouth is watching behind the scenes. Afterwards, she pulls out a silencer and speaks into an attached intercom, "It''s as planned, Gin."', NULL, 14, 'https://myanimelist.net/images/anime/10/78894.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (39592, 'Kidou Senshi Gundam: The Origin - Zenya Akai Suisei', '機動戦士ガンダム THE ORIGIN 前夜 赤い彗星', 'TV', 13, 'FINISHED', 8.19, 13032, 459, 4767, 'What was the tragedy that decided the fates of Char Aznable, the man later nicknamed the "Red Comet" as an ace pilot of the Zeon forces, and his sister Sayla Mass?

The two siblings'' journeys, brought on by the sudden death of their father Zeon Zum Deikun who was a leader of the Spacenoids, are depicted in the four episodes of "Chronicle of Char and Sayla."

The Zabi family who seize control of Side 3 and lead the Principality of Zeon, the early days of many renowned Zeon ace pilots who later fight in the One Year War, the secrets of mobile suit development, conflicts with the Earth Federation Forces, and the road leading to the outbreak of war—all will be revealed.

(Source: Official Website)', 4, 9, 'https://myanimelist.net/images/anime/1897/100015.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (3226, 'Major S4', 'メジャー　（第4シリーズ)', 'TV', 26, 'FINISHED', 8.19, 43152, 461, 2986, 'Having finished high school, Gorou Honda sets his sights on becoming a professional baseball player. His dreams are much more ambitious than becoming a Japanese Baseball League player, so he instead decides to move to the birthplace of his beloved sport, America, in order to play in the Major League.

However, Gorou finds that the Major League players are much faster, stronger, and more driven than he is. Nonetheless, he is eager to catch up with them. In order to do so, Gorou must first conquer the ranks of the Minor League, where numerous skilled players compete in the grueling rise to the Majors.

Gorou learns that he will have to adapt to the stark differences of American culture and push himself to new extremes as his race to join the Major League begins.

[Written by MAL Rewrite]', 70, 83, 'https://myanimelist.net/images/anime/9/75217.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (6864, 'xxxHOLiC Rou', 'xxxHOLiC 籠', 'OVA', 2, 'FINISHED', 8.19, 34663, 467, 2624, 'Ten years after the events of xxxHOLiC Shunmuki, a melancholic Kimihiro Watanuki has taken over the shop formerly run by the mysterious Yuuko due to a promise he made to her. His companions Maru, Moro, and Mokona live together with him in relative contentment, and some familiar faces arrive every now and then: former rival turned-steadfast friend Shizuka Doumeki, and the former psychic prodigy Kohane Tsuyuri. While Kohane studies folklore under Doumeki at university, they encounter a case that is perfect for the master of the shop.

Eventually, Watanuki receives a visit from Doumeki''s grandfather, Haruka. He requests that Watanuki investigates his grandson''s dreams. While inside the dream world, he discovers how their past adventures played out from Doumeki''s perspective of view, leading Watanuki to discover truths from 10 years ago and secrets about the ties that bind their friendship.

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/9/25080.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (38088, 'Digimon Adventure: Last Evolution Kizuna', 'デジモンアドベンチャー LAST EVOLUTION 絆', 'UNKNOWN', 1, 'FINISHED', 8.19, 22633, 455, 3157, 'As the Chosen Children and their partner Digimon live happily together in the human world, Taichi Yagami and Yamato Ishida, alongside their friends, dedicate themselves to maintaining this hard-earned peace. Though united by this innate responsibility, each one has already started to take their first steps toward a future beyond being a Chosen Child. 

However, this new journey is interrupted by the appearance of Menoa Bellucci, an American professor specializing in Digimon research. She bears news of several Chosen Children from around the world being found comatose, with their partner Digimon nowhere to be found. Menoa''s investigations indicate that a new breed of Digimon is behind the alarming phenomenon: Eosmon, who hides within the internet''s depths. 

To succeed in this mission, the team must endeavor through the growing distance between them and band together one last time.

[Written by MAL Rewrite]', NULL, 129, 'https://myanimelist.net/images/anime/1654/104884.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (40784, 'Wu Liuqi: Zui Qiang Fa Xing Shi', '伍六七之最强发型师', 'ONA', 10, 'FINISHED', 8.19, 56623, 466, 2421, 'Seeking to recover his memories, a scissor-wielding hairdresser, bungling quasi-assassin stumbles into a struggle for power among two feuding factions.

(Source: IMDb)', NULL, 86, 'https://myanimelist.net/images/anime/1962/153860.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (19123, 'One Piece: Episode of Merry - Mou Hitori no Nakama no Monogatari', 'ワンピース エピソード・オブ・メリー ～もうひとりの仲間の物語～', 'UNKNOWN', 1, 'FINISHED', 8.19, 34850, 463, 2732, 'After Brook questions the origin of the Mini Merry name, Usopp and Chopper Tony Tony recall the adventures of the Straw Hat Crew''s beloved ship, friend, and crew member—the Going Merry. Usopp abandons the crew for a fight over the Going Merry while Robin Nico leaves with the government''s top assassin group, CP9. In order to bring the crew back together, Monkey D. Luffy and the remaining Straw Hats follow Robin to rescue her from the claws of the World Government.

[Written by MAL Rewrite]', NULL, 8, 'https://myanimelist.net/images/anime/9/61015.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (40052, 'Great Pretender', 'GREAT PRETENDER', 'TV', 23, 'FINISHED', 8.19, 357134, 456, 309, 'A series of unfortunate events has led Makoto Edamura to adopt the life of crime—pickpocketing and scamming others for a living. However, after swindling a seemingly clueless tourist, Makoto discovers that he was the one tricked and, to make matters worse, that the police are now after him. 

While making his escape, he runs into the tourist once again, who turns out to be a fellow con man named Laurent Thierry, and ends up following him to Los Angeles. In an attempt to defend his self-proclaimed title of "Japan''s Greatest Swindler," Makoto challenges his rival to determine the better scammer. Accepting the competition, Laurent drops them off outside a huge mansion and claims that their target will be the biggest mafia boss on the West Coast.

As Makoto becomes increasingly involved with the cunning Laurent, his colorful associates, and the world of international high-stakes fraud, he soon realizes that he got more than what he bargained for as his self-declared skills are continually put to the test.

[Written by MAL Rewrite]', 83, 6, 'https://myanimelist.net/images/anime/1418/107954.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (138, 'Hunter x Hunter: Greed Island', 'HUNTER×HUNTER Greed Island', 'OVA', 8, 'FINISHED', 8.19, 92645, 457, 1517, 'After the battle with the Spiders, the search for Ging continues as Gon and Killua decided to once again attempt to purchase the rare game "Greed Island." However, Gon came up with a better plan, which was to volunteer to complete the game for the billionaire who owned it. But some training must be done, as Gon and Killua''s abilities are still at a developing stage and "Greed Island" is no simple game for anyone to play with. It is the infamous game that could easily lead to one''s death. Based on the manga by Togashi Yoshihiro.', NULL, 73, 'https://myanimelist.net/images/anime/1902/122320.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (49114, 'Vanitas no Karte Part 2', 'ヴァニタスの手記', 'TV', 12, 'FINISHED', 8.19, 150885, 465, 806, 'Vanitas and Noé Archiviste head out to the town of Gévaudan in search of the "Beast," an enormous wolf-like creature that has slaughtered hundreds of people. Suspecting that the Beast is a curse-bearing vampire, Vanitas primarily aims to heal it using the powers of his grimoire.

Along the way, the two get separated and suddenly travel back to the past—to the exact moment the Beast is lurking in the woods. After a battle against the gigantic wolf and a vampire hunter, Vanitas decides to team up with Jeanne in order to find Noé. Despite being allies, Jeanne''s goal is the opposite of Vanitas'', as she was tasked to kill the Beast—suspecting it may be someone she used to know.

Meanwhile, a severely wounded Noé is picked up by the mysterious Chloé d''Apchier and her servant. Like Noé, Chloé is a vampire whose existence was erased from the public''s knowledge. She has been a guardian for future generations and once tried to find a way to become human again. While Noé is grateful to Chloé for her hospitality, little does he know that she might be siding with forces far more dangerous than the Beast itself.

[Written by MAL Rewrite]', 30, 3, 'https://myanimelist.net/images/anime/1247/120579.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (232, 'Cardcaptor Sakura', 'カードキャプターさくら', 'TV', 70, 'FINISHED', 8.19, 234318, 454, 536, 'Ten-year-old Sakura Kinomoto is an ordinary fourth-grade student living in Tomoeda until, one day, she stumbles upon a mysterious book of cards titled "The Clow." Pondering over her discovery, she unintentionally causes a magical gust of wind to scatter the cards all over town.

The accident awakens the Beast of the Seal—Keroberos, nicknamed "Kero"—who tells Sakura that she has released the mystical "Clow Cards" created by the sorcerer Clow Reed. Due to each Card''s ability to act independently and their incredible power, Clow had sealed them away. Now that they have been set free, the Cards pose great danger to the world, and it is up to Sakura to put an end to them.

Appointing Sakura as the "Cardcaptor" and granting her the Sealed Key, Kero tasks her with finding and recapturing all the Clow Cards. Alongside her best friend Tomoyo Daidouji, and with Kero''s guidance, Sakura must learn to balance her new secret duty with the everyday troubles as she takes flight on her magical adventures as Cardcaptor Sakura.

[Written by MAL Rewrite]', 32, 1, 'https://myanimelist.net/images/anime/8/60781.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (44055, 'Sasaki to Miyano', '佐々木と宮野', 'TV', 12, 'FINISHED', 8.19, 107826, 464, 1192, 'Yoshikazu Miyano''s troubles first start one hot summer day when Shuumei Sasaki steps into his life. Sasaki saves Miyano''s classmate from a group of bullies, and after that, Miyano cannot seem to shake off his eccentric upperclassman. His silent admiration for Sasaki gradually sours into annoyance each time the so-called delinquent refuses to leave him alone. Constantly being called by cute nicknames and having his boundaries ignored, Miyano wonders why Sasaki wants to get close to him.

The shy and easily flustered Miyano harbors an embarrassing secret—he is a "fudanshi," a boy who likes boys'' love (BL) manga. The last thing he wants is for other students to find out, but through a slip of the tongue, he reveals the truth to Sasaki. Intrigued, the clueless Sasaki asks to borrow a book to read, which he is given very reluctantly. To Miyano''s surprise, Sasaki enjoys the BL that he receives and asks for more, marking a shift in their strange dynamic.

Although Sasaki appears to possess some personal agenda, his feelings for Miyano become complicated the more time they spend together. As they now share a common interest, their relationship is poised to change and further develop.

[Written by MAL Rewrite]', 30, 32, 'https://myanimelist.net/images/anime/1182/119308.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (55825, 'Jigokuraku 2nd Season', '地獄楽第二期', 'TV', 12, 'FINISHED', 8.18, 114612, 477, 751, 'Seeking the key to the elixir of immortality, the group arrives at the fortress of the island''s monstrous ruler, the "Tensen." To survive and escape the island, cooperation becomes essential—regardless of whether one is a condemned criminal or an executioner.

Meanwhile, the shogunate orders additional landings on the island of the Immortal Realm, led by Shugen Yamada Asayemon. Among them are the Ishigakure clan, who share a past with Gabimaru.

Desperate to find the elixir and escape the island, Gabimaru and his companions face the Tensen in a battle that escalates into an all-out confrontation between humans and immortals!

(Source: Twin Engine, edited)', 15, 4, 'https://myanimelist.net/images/anime/1772/154456.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (53065, 'Sono Bisque Doll wa Koi wo Suru Season 2', 'その着せ替え人形は恋をする Season 2', 'TV', 12, 'FINISHED', 8.18, 201999, 485, 566, 'After Marin Kitagawa introduced Wakana Gojou to the world of cosplay, he has been creating her outfits with ease. Even so, he still has a lot to learn, and every new lesson seems to strengthen his love for sewing and for the hina dolls his grandfather taught him to make.

Meanwhile, Kitagawa finds it harder and harder to hide her feelings for Gojou. Friends and strangers alike constantly mistake them for a couple, much to Gojou''s embarrassment. After all, in his eyes, their worlds are far too different for anyone to think they could be romantically linked. However, as Gojou spends more time with Kitagawa and realizes that his passions are not ridiculed by other people, a relationship between the two no longer seems so far-fetched.

[Written by MAL Rewrite]', 65, 26, 'https://myanimelist.net/images/anime/1024/150787.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34537, 'Yoru wa Mijikashi Arukeyo Otome', '夜は短し歩けよ乙女', 'UNKNOWN', 1, 'FINISHED', 8.18, 57586, 487, 1853, 'On a mysterious night that seems to last for a year, an ordinary college student continues to chase one of his underclassmen, a girl with black hair—the girl of his dreams. Up until now, he has been relying on a simple plan, which is to calculatingly bump into her every day while making it seem like a meaningful coincidence. However, his efforts remain futile as their relationship is not progressing at all.

Meanwhile, the black-haired girl believes that everything is connected by fate and endeavors to experience as many new things as possible, leaving it all for destiny to decide. While strolling along the lively streets of Kyoto, she discovers that the very beginning of her fateful journey—a book she had as a child—is currently being sold in a second-hand bookstore. Upon knowing this, the college student eyes another opportunity to run into her "by chance": this time, he hopes to get the book before she does and finally grasp the thread of fate that could connect their hearts.

[Written by MAL Rewrite]', NULL, 76, 'https://myanimelist.net/images/anime/2/86940.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (36370, 'Ginga Eiyuu Densetsu: Die Neue These - Seiran 2', '銀河英雄伝説 Die Neue These 星乱 第2章', 'UNKNOWN', 4, 'FINISHED', 8.18, 15086, 473, 4023, 'Marquis Reinhard von Lohengramm''s plot to destabilize the Free Planets Alliance succeeds when the treacherous former Rear Admiral Arthur Lynch instigates a coup on Heinessen. Equipped with a plan crafted by Reinhard himself, Lynch encourages his longtime friend Admiral Dwight Greenhill to supervise the National Salvation Military Council''s toppling of the civilian government. Seeking to defend democracy and restore the Alliance constitution, Admiral Yang Wen-li faces off against his fellow citizens—and, regrettably, the father of his devoted adjutant Lieutenant Frederica Greenhill.

Now with the Free Planets Alliance thoroughly occupied with their own internal matters, the forces of the Galactic Empire can safely suppress the newly formed Lippstadt League led by Duke Otto von Braunschweig. However, with his friend and loyal subordinate High Admiral Siegfried Kircheis fighting far away in the noble-controlled frontier regions, Reinhard increasingly relies on the advice of the ruthless Vice Admiral Paul von Oberstein, whose influence within the esteemed Lohengramm admiralty steadily grows.

Though bloodshed is inevitable on both sides of the galaxy, Yang Wen-li of the Alliance and Reinhard von Lohengramm of the Empire each ask themselves the same questions: how will history look back on their actions? Will the ends justify the means?

[Written by MAL Rewrite]', NULL, 23, 'https://myanimelist.net/images/anime/1215/103351.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (10800, 'Chihayafuru', 'ちはやふる', 'TV', 25, 'FINISHED', 8.18, 195227, 471, 523, 'As a child, Chihaya Ayase had only one dream: to see her elder sister Chitose become Japan''s most successful model. However, upon defending her ostracised classmate Arata Wataya from his bully—Chihaya''s childhood friend Taichi Mashima—she discovers the world of competitive karuta and soon becomes enamoured with the sport.

Based on the Ogura Hundred Poets anthology, this card game where poems are studied requires excellent memory, agility, and a tremendous endurance from the players. Full of hope, Chihaya joins the Shiranami Society together with the newly reconciled Arata and Taichi, embarking on an exciting journey for the title awarded to the top-ranked female player—Queen of Karuta.

Since middle school, Chihaya grew distant from a dispassionate Taichi and separated from Arata. However, in order to improve her skills, Chihaya decides to create a karuta club in her high school. With the help of Taichi, another veteran player, and a few spirited newcomers, Chihaya''s new-founded Mizusawa Karuta Club aims for victory in the Omi Shrine''s national championship.

[Written by MAL Rewrite]', 6, 1, 'https://myanimelist.net/images/anime/1959/156735.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (7791, 'K-On!!', 'けいおん!!', 'TV', 26, 'FINISHED', 8.18, 413967, 478, 306, 'It is the new year, which means that the senior members of the Light Music Club are now third-years, with Azusa Nakano being the only second-year. The seniors soon realize that Azusa will be the only member left once they graduate and decide to recruit new members. Despite trying many methods of attracting underclassmen—handing out fliers, bringing people into the clubroom, and performing at the welcoming ceremony—there are no signs of anyone that plans to join.

While heading to the clubroom, Azusa overhears Yui Hirasawa say that the club is fine with only five people and that they can do many fun things together. Changing her mind, she decides that they do not need to recruit any members for the time being. 

K-On!! revolves around the members of the Light Music Club as they experience their daily high school life. From rehearsing for concerts to just messing around, they are ready to make their last year together an exciting one!

[Written by MAL Rewrite]', 62, 15, 'https://myanimelist.net/images/anime/12/76121.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (22297, 'Fate/stay night: Unlimited Blade Works', 'Fate/stay night [Unlimited Blade Works]', 'TV', 12, 'FINISHED', 8.18, 730714, 472, 142, 'The Holy Grail War is a battle royale among seven magi who serve as Masters. Masters, through the use of the command seals they are given when they enter the war, command Heroic Spirits known as Servants to fight for them in battle. In the Fifth Holy Grail War, Rin Toosaka is among the magi entering the competition. With her Servant, Archer, she hopes to obtain the ultimate prize—the Holy Grail, a magical artifact capable of granting its wielder any wish.
 
One of Rin''s classmates, Shirou Emiya, accidentally enters the competition and ends up commanding a Servant of his own known as Saber. As they find themselves facing mutual enemies, Rin and Shirou decide to form a temporary alliance as they challenge their opponents in the Holy Grail War. 

[Written by MAL Rewrite]', 37, 35, 'https://myanimelist.net/images/anime/12/67333.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (4107, 'Tengen Toppa Gurren Lagann Movie 1: Gurren-hen', '劇場版 天元突破グレンラガン 紅蓮篇', 'UNKNOWN', 1, 'FINISHED', 8.18, 90263, 486, 1438, 'Animation studio Gainax presented a website for the release of a movie adaptation of the Tengen Toppa Gurren Lagann TV series in the fall of 2008. Both the original director and series script editor will return to work on the new project. Gainax will also be hosting four events to celebrate this occasion at this year''s Tokyo International Anime Fair, featuring voice actors from the anime.', NULL, 41, 'https://myanimelist.net/images/anime/1270/115752.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (40729, 'Nomad: Megalo Box 2', 'NOMAD メガロボクス2', 'TV', 13, 'FINISHED', 8.18, 92181, 483, 1224, 'Megalo Box is an advanced form of boxing where competitors wear metal frames called Gear. When the first ever Megalonia tournament took place, "Gearless" Joe became its champion and known to all as a legendary fighter. However, soon after, he lost an exhibition match against the second champion and vanished from the public eye.

Seven years later, Joe now goes by "Nomad" and keeps a low profile, occasionally fighting in a few underground matches to get by. He is haunted by hallucinations and relies on a set of painkillers to numb his mind.

During a match, Joe wins against an opponent, Chief, who purposefully loses for some extra cash from gamblers. Subsequently, Joe discovers that Chief is from a community of immigrants called the Casa. Chief is gradually trying to make enough money to purchase the land where they live illegally. At first, Joe hesitates to get involved, but eventually decides to lend the Casa a helping hand.

[Written by MAL Rewrite]', 11, 14, 'https://myanimelist.net/images/anime/1190/113352.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (18195, 'Little Busters! Refrain', 'リトルバスターズ！～Refrain～', 'TV', 13, 'FINISHED', 8.18, 81550, 479, 1561, 'Following the Little Busters after they lost their first baseball game, the team decides to have a pancake party. It has been almost one semester since the return of Kyousuke Natsume. As usual, Riki Naoe continues to help the Little Busters'' members—both old and new—with confronting their inner struggles. However, strange happenings begin to occur, leading Rin Natsume and Riki closer to unraveling the truth behind the "secret of this world."

Little do Rin and Rikki know, their discovery will end up changing the peaceful everyday lives created by the Little Busters once and for all. Little Busters!: Refrain brings a conclusion to the colorful stories of its ensemble cast—forged with the weight of emotions and strengthened with the bond of friendship—as they come to terms with their regrets and weaknesses.

[Written by MAL Rewrite]', 51, 58, 'https://myanimelist.net/images/anime/10/55049.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1519, 'Black Lagoon: The Second Barrage', 'BLACK LAGOON The Second Barrage', 'TV', 12, 'FINISHED', 8.18, 341820, 470, 434, 'Rokurou "Rock" Okajima has joined the Lagoon Company, a pirate mercenary group which operates out of Roanapur, Thailand. Despite his initial protests, this filthy slum of depraved souls and merciless criminals now serves as the former salaryman''s home. Stranded, with nothing left of his past life but the clothes on his back and his inner morality, Rock is forced to perform jobs alongside the other members of the Lagoon crew. Berated for his lack of spine as he wades through the underbelly of society, he must decide whether to continue on amidst the gunfire and ruthlessness or risk everything he has in an attempt to be free. Whether he chooses the comfort of a familiar land or the freedom of being an outlaw, his decision will have lasting consequences on the crew who gave him a home.

[Written by MAL Rewrite]', 40, 1, 'https://myanimelist.net/images/anime/1701/152849.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (1142, 'Hachimitsu to Clover II', 'ハチミツとクローバー II', 'TV', 12, 'FINISHED', 8.18, 56751, 474, 2050, 'Back from his journey across Japan, Yuuta Takemoto reminisces about his college life so far. He has matured significantly since his second year and is motivated to move forward.

Feeling more confident than ever before, he finally confesses to Hagumi Hanamoto, the girl he has been in love with since their first encounter. However, Hagumi has been confused by her attempts to understand the mysterious Shinobu Morita. Hiding behind a playful demeanor, Morita may be the most burdened by his own potential. Meanwhile, Takumi Mayama has become a full-fledged working adult and has landed Ayumi Yamada several pottery orders through his company in an act of friendship.

The five youths continue to face individual hardships in academics, work, love, and friendship as they push each other toward the paths that they are destined to walk.

[Written by MAL Rewrite]', 86, 58, 'https://myanimelist.net/images/anime/6/11040.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (962, 'Aria the Natural', 'ARIA The NATURAL', 'TV', 26, 'FINISHED', 8.18, 32352, 468, 2630, 'Akari Mizunashi continues her training to become a Prima Undine (a professional tour guide gondolier) along with her friends Aika and Alice in the peaceful city of Neo Venezia. Despite the fact that these three girls are from competing companies, they are constantly together, learning more about how to become better tour guides and more about the mysteries of Neo Venezia.

As the group continues to meet interesting and unforgettable people through their daily routines, they will also come closer to the secrets that make the enigmatic and ever beautiful city of Neo Venezia so warm and alive.

Welcome back to Neo Venezia: the city where miracles can be created by hand.

[Written by MAL Rewrite]', 13, 67, 'https://myanimelist.net/images/anime/2/77621.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (558, 'Major S2', 'メジャー (第2シリーズ)', 'TV', 26, 'FINISHED', 8.18, 48042, 480, 2817, 'Gorou Honda has finally returned to Mifune East Junior High School, surprising his friends upon arrival. Now, Gorou is once again surrounded by those he holds closest, and he strives to continue playing and enjoying the game he loves most.

However, things do not go as planned, as Gorou is reminded of the harsh realities of baseball as he copes with an injury he sustained while playing baseball at Hitaka Little. Between new rivals, old friends, and mending broken relationships, Gorou must overcome challenges he has never faced before. 

His goal of attending elite baseball high school Kaido may not be far from his reach, but complicated circumstances may stop him in his tracks once again. How will he deal with the immense pressures of the game? And will he ever be able to find the type of baseball he loves most?

[Written by MAL Rewrite]', 102, 122, 'https://myanimelist.net/images/anime/6/73972.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (42894, 'Natsume Yuujinchou: Ishi Okoshi to Ayashiki Raihousha', '夏目友人帳 石起こしと怪しき来訪者', 'UNKNOWN', 1, 'FINISHED', 8.18, 14054, 482, 3459, 'Ishi Okoshi
While searching for Nyanko-sensei, Takashi Natsume encounters meek and small-looking youkai Mitsumi. Mitsumi was entrusted by his leader Gantetsu, a powerful and strong ayakashi, to be the year''s "Ishi Okoshi," whose role consists of waking him from his deep slumber. Seeing how much Mitsumi wants to prove himself as Gantetsu''s worthy servant, Natsume decides to help him fulfill his task. However, time is running out—for they are not the only ones who want to awaken the divine being.

Ayashiki Raihousha
One day, Natsume''s friend Kaname Tanuma is visited by a strange man. In the subsequent days, the visitor briefly talks with Tanuma and leaves. Natsume soon discovers that the outsider is a youkai disguised as a human, who claims to bear no danger. Despite trusting the youkai, Tanuma''s health slowly begins to deteriorate, causing Natsume to become more suspicious of the interloper. What is the truth of his sudden appearance and his connection with Tanuma?

[Written by MAL Rewrite]', NULL, 22, 'https://myanimelist.net/images/anime/1992/111560.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (23623, 'Non Non Biyori Repeat', 'のんのんびより りぴーと', 'TV', 12, 'FINISHED', 8.18, 107592, 484, 1308, 'Far from the hustle and bustle of urban life, and with only a single candy store and bus route to its name, the rural Asahigaoka is certainly not a place for everyone. Nevertheless, the village''s children still manage to cheerfully spend their days exploring and having fun in the wilderness around them. One such child, Renge Miyauchi, the youngest of the group, looks forward to the entrance ceremony of the upcoming school year, signalling her entry into first grade and the beginning of her elementary school life. Attending the only school in town, Renge and her friends, seventh grader Natsumi Koshigaya and her eighth grade sister Komari, make the most out of their rural lifestyle, playing and studying everyday.

Meanwhile, fifth grader Hotaru Ichijou has just moved to Asahigaoka from Tokyo, unaware of the numerous adventures and memories that await her. 

[Written by MAL Rewrite]', 103, 88, 'https://myanimelist.net/images/anime/9/75105.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (18, 'Initial D Fourth Stage', '頭文字〈イニシャル〉D FOURTH STAGE', 'TV', 24, 'FINISHED', 8.18, 119560, 476, 1301, 'Takumi Fujiwara finally joins Ryousuke and Keisuke Takahashi to create "Project D." Their goal is twofold: Ryousuke wants to develop his "High-Speed Street Racing Theory," while Keisuke and Takumi aim at improving their driving skills by facing powerful opponents on dangerous roads. The idea of Project D is to challenge street racing teams from other prefectures to improve both their uphill and downhill records. In order to attract the attention of the best racing teams, Ryousuke creates a dedicated website to announce the future battles of Project D and post the team''s results.

The fourth season of Initial D details the hardships and successes of the members of Project D as they try to become the best street racing team outside of Gunma Prefecture.

[Written by MAL Rewrite]', 19, 114, 'https://myanimelist.net/images/anime/9/10521.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (42897, 'Horimiya', 'ホリミヤ', 'TV', 13, 'FINISHED', 8.18, 993673, 475, 79, 'On the surface, the thought of Kyouko Hori and Izumi Miyamura getting along would be the last thing in people''s minds. After all, Hori has a perfect combination of beauty and brains, while Miyamura appears meek and distant to his fellow classmates. However, a fateful meeting between the two lays both of their hidden selves bare. Even though she is popular at school, Hori has little time to socialize with her friends due to housework. On the other hand, Miyamura lives under the noses of his peers, his body bearing secret tattoos and piercings that make him look like a gentle delinquent.

Having opposite personalities yet sharing odd similarities, the two quickly become friends and often spend time together in Hori''s home. As they both emerge from their shells, they share with each other a side of themselves concealed from the outside world.

[Written by MAL Rewrite]', 25, 26, 'https://myanimelist.net/images/anime/1695/111486.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (235, 'Meitantei Conan', '名探偵コナン', 'TV', NULL, 'AIRING', 8.18, 170271, 481, 725, 'Shinichi Kudou, a high school student of astounding talent in detective work, is well known for having solved several challenging cases. One day, when Shinichi spots two suspicious men and decides to follow them, he inadvertently becomes witness to a disturbing illegal activity. Unfortunately, he is caught in the act, so the men dose him with an experimental drug formulated by their criminal organization, leaving him to his death. However, to his own astonishment, Shinichi lives to see another day, but now in the body of a seven-year-old child.

Perfectly preserving his original intelligence, he hides his real identity from everyone, including his childhood friend Ran Mouri and her father, private detective Kogorou Mouri. To this end, he takes on the alias of Conan Edogawa, inspired by the mystery writers Arthur Conan Doyle and Ranpo Edogawa.

Shinichi, as Conan, starts secretly solving the senior Mouri''s cases from behind the scenes with his still exceptional sleuthing skills, while covertly investigating the organization responsible for his current state, hoping to reverse the drug''s effects someday.

[Written by MAL Rewrite]', 94, 14, 'https://myanimelist.net/images/anime/7/75199.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (34636, 'Ballroom e Youkoso', 'ボールルームへようこそ', 'TV', 24, 'FINISHED', 8.18, 160478, 469, 755, 'Tatara Fujita is a shy middle schooler who has no particular plan for the future. He has gotten through life by avoiding any kind of confrontation and blending in with the crowd. But blending in isn''t enough to get out of trouble, as some bullies harass him for money. Luckily, he is saved by a man named Kaname Sengoku.

Kaname invites Tatara to his dance studio. Although he would normally never set foot in such a place, Tatara is captivated by Sengoku''s commanding presence. Granted an opportunity to dance with fellow classmate Shizuku Hanaoka—who often practices at the studio—Tatara realizes there''s something about the idea of being put in the limelight and dancing where people will see him that keeps him coming back. With an earnest, passionate drive to improve, Tatara begins his journey into the world of competitive dance.

[Written by MAL Rewrite]', 48, 23, 'https://myanimelist.net/images/anime/5/86739.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59708, 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 4th Season: 2-nensei-hen 1 Gakki', 'ようこそ実力至上主義の教室へ 4th Season 2年生編1学期', 'TV', 16, 'AIRING', 8.17, 17827, 493, 1533, 'As Ayanokouji and his classmates begin their second year at the Advanced Nurturing High School, they''re greeted by a fresh gauntlet of exams and a fresh batch of rather unique first-year students. They''ll have to get to know each other quickly, because the first special exam pairs the first-years with the second-years on a written test—with only the second-years facing expulsion if their team performs poorly! Worse yet? It seems one of the new first-years is also from the White Room. Can Ayanokouji avoid expulsion while sussing out the identity of this hidden foe?

(Source: Crunchyroll)', 17, 60, 'https://myanimelist.net/images/anime/1176/153626.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (59228, 'Kuroshitsuji: Midori no Majo-hen', '黒執事 -緑の魔女編-', 'TV', 13, 'FINISHED', 8.17, 25726, 490, 2898, 'Queen Victoria of England has ordered her loyal watchdog, 13-year-old Earl Ciel Phantomhive, to investigate a series of suspicious deaths in southern Germany. Across multiple villages, all the victims have one thing in common: they had entered the so-called Werewolves'' Forest right before they developed strange deformities and subsequently died. The rumors put blame on a "witch''s curse," the nearby villagers'' firm belief based on old folklore.

Unconvinced that anything truly supernatural is at play, Ciel and his contracted demonic butler, Sebastian Michaelis—along with the rest of the Phantomhive servants—come across an isolated village in the Werewolves'' Forest. Its residents are only women, hostile toward the outsiders and serving a young girl with emerald eyes and bound feet, Sieglinde "Green Witch" Sullivan. Ciel and Sebastian investigate to uncover the truth, but as they soon fall victim to the curse themselves, it appears that there is more to the local myths than meets the eye.

[Written by MAL Rewrite]', 54, 26, 'https://myanimelist.net/images/anime/1517/148292.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (57433, 'Seishun Buta Yarou wa Santa Claus no Yume wo Minai', '青春ブタ野郎はサンタクロースの夢を見ない', 'TV', 13, 'FINISHED', 8.17, 68953, 492, 1316, 'After surviving the entrance exams, Sakuta Azusagawa has finally enrolled in the same university as his girlfriend, Mai Sakurajima. He is gradually getting used to the unfamiliar environment as he attends student gatherings and makes new acquaintances. Everything seems to be going smoothly until Sakuta''s friend and Sweet Bullet idol group member Uzuki Hirokawa begins acting out.

With fellow Sweet Bullet member Nodoka Toyohama pleading for his help, Sakuta realizes that he has stumbled upon another case of the inexplicable Puberty Syndrome—Uzuki is feeling pressured by the sudden surge of popularity and rumors of a potential solo career. While Sakuta searches for a solution, another occurrence of Puberty Syndrome gradually emerges from the shadows.

[Written by MAL Rewrite]', 65, 26, 'https://myanimelist.net/images/anime/1823/149858.jpg');
INSERT INTO ani_anime (mal_id, title, title_japanese, media_type, episodes, status, score, scored_by, rank, popularity, synopsis, season_id, studio_id, image_url) VALUES (56009, 'Yuusha-kei ni Shosu: Choubatsu Yuusha 9004-tai Keimu Kiroku', '勇者刑に処す 懲罰勇者9004隊刑務記録', 'TV', 12, 'FINISHED', 8.17, 117776, 496, 932, 'In a world where the title of Hero is treated as a punishment rather than an honor, the worst criminals are sentenced to the front lines of an endless war against the Demon Lords. Branded as Heroes, they are forced into military service without even the mercy of death, condemned to be revived and sent back into battle forever.

Among them is Xylo Forbartz, once a respected commander of the Holy Knights. Now the leader of Penal Hero Unit 9004, he commands a squad of convicts considered expendable by the very nation they serve. During one chaotic mission, he encounters Teoritta, a living weapon known as a Goddess, whose presence threatens to shift the balance of both the war and his own fate.

As the unit is sent on increasingly dangerous operations, Xylo must balance leading his unit, surviving the battles he finds himself in, and uncovering the truth behind his own sentencing.

[Written by MAL Rewrite]', 15, 105, 'https://myanimelist.net/images/anime/1062/151911.jpg');
